import type {
  OriginalImageElement,
  OriginalImageElementCopy,
  ElementOffset,
} from '../../types'

import { calculateFixedPositionedElementBorderBoxCoordinates } from './calculate-fixed-positioned-element-coordinates'
import { getTallestClientRect } from './get-tallest-client-rect'

/**
 * Updates canvas size and position in accordance to its predecessor, which is
 * an original image.
 *
 * @param {OriginalImageElement} imgElement The original image element
 * @param {OriginalImageElementCopy} canvasElement The sibling canvas element of the image
 */
export function updatePositionAndSizeToCanvas(
  imgElement: OriginalImageElement,
  canvasElement: OriginalImageElementCopy,
): void {
  const originalImageOffset: DOMRect | null = getTallestClientRect(imgElement)
  const targetOffset: ElementOffset | null = calculateFixedPositionedElementBorderBoxCoordinates(
    canvasElement,
    originalImageOffset,
  )
  const canvasElementStyle: CSSStyleDeclaration = canvasElement.style
  if (!targetOffset) {
    console.warn('The canvas copy is not visible')
    // If "originalImageOffset" is null it means that the original image is invisible
    // on the screen.
    canvasElementStyle.display = 'none'
    return
  }

  const tallestRect = getTallestClientRect(imgElement)
  if (!tallestRect) {
    console.warn('visible image is not properly displayed')
    return
  }

  const canvasNewStyle: Partial<CSSStyleDeclaration> = {
    blockSize: '',
    // Set canvas position and left/top offsets to cover the image
    position: 'fixed',
    width: `${tallestRect.width}px`,
    height: `${tallestRect.height}px`,
    top: `${targetOffset.top}px`,
    left: `${targetOffset.left}px`,
  }

  Object.assign(canvasElementStyle, canvasNewStyle)
}
