/**
 * Returns the DOMRect of the given elements tallest client rect
 *
 * @export
 * @param {(HTMLElement | SVGSVGElement)} element - the element which coordinates should be returned
 * @return {(ElementOffset | null)} - the tallest rect or null if the element is not visible.
 */
export function getTallestClientRect(
  element: HTMLElement | SVGElement,
): DOMRect | null {
  // an element may be divided into many pieces which are located on many spine items.
  const elementContainingBlockRects = element.getClientRects()

  let tallestRect = elementContainingBlockRects.item(0)
  if (!tallestRect) {
    console.warn(
      'There are no on screen coordinates for the element. The element is not displayed.',
    )
    return null
  }

  for (let i = 0; i < elementContainingBlockRects.length; i++) {
    const rect = elementContainingBlockRects.item(i)
    if (rect && rect.height > tallestRect.height) {
      tallestRect = rect
    }
  }

  return tallestRect
}
