import { NavigatorErrorType } from '../../const'
import { NavigatorError } from '../../types'

import { AsyncTaskRejectionErrorFabric } from './types'

// https://www.typescriptlang.org/docs/handbook/release-notes/typescript-2-2.html#example
export class AsyncTaskRejectionErrorImplementation<T extends NavigatorErrorType>
  extends Error
  implements NavigatorError<T> {
  public get flowpubNavigatorErrorType(): T {
    return this.navigatorErrorType
  }
  constructor(
    // parameters as the regular Error constructor has
    message: string,
    private navigatorErrorType: T,
    stack?: string,
  ) {
    super(message)
    Object.setPrototypeOf(this, new.target.prototype)
    if (stack) {
      this.stack = stack
    }
  }
}

function asyncTaskRejectionErrorFabricImpl<T extends NavigatorErrorType>(
  errorMessage: string,
  navigatorErrorType: T,
): NavigatorError<T>
function asyncTaskRejectionErrorFabricImpl<T extends NavigatorErrorType>(
  error: Error,
  navigatorErrorType: T,
): NavigatorError<T>
function asyncTaskRejectionErrorFabricImpl<T extends NavigatorErrorType>(
  messageOrError: string | Error,
  navigatorErrorType: T,
): NavigatorError<T> {
  const errorMessage: string =
    messageOrError instanceof Error ? messageOrError.message : messageOrError
  const errorStackOrUndefined: string | undefined =
    messageOrError instanceof Error ? messageOrError.stack : undefined
  const asyncTaskRejectionError = new AsyncTaskRejectionErrorImplementation(
    errorMessage,
    navigatorErrorType,
    errorStackOrUndefined,
  )
  return asyncTaskRejectionError
}

export const asyncTaskRejectionErrorFabric: AsyncTaskRejectionErrorFabric<NavigatorErrorType> = asyncTaskRejectionErrorFabricImpl
