import {
  PageLabelVisibilityHandler,
  VisiblePageLabelsInfoListener,
  ContentViewProperties,
  VisiblePageLabelsInfoListenerParameters,
  PageLabelInfoByVisibilityHandlerTypeName,
  PageLabelVisibilityHandlerReflowableLayoutBookTypeName,
} from './types'
import { PageLabelVisibilityHandlerTypeName } from './enum'

export class PageLabelVisibilityHandlerReflowable<
  P extends PageLabelInfoByVisibilityHandlerTypeName<
    PageLabelVisibilityHandlerReflowableLayoutBookTypeName
  >
>
  implements
    PageLabelVisibilityHandler<
      PageLabelVisibilityHandlerReflowableLayoutBookTypeName
    > {
  static pageLabelVisibilityHandlerFixedLayoutBookTypeName: PageLabelVisibilityHandlerReflowableLayoutBookTypeName =
    PageLabelVisibilityHandlerTypeName.Reflowable

  protected contentViewStartOffset = 0
  protected contentViewEndOffset = 0
  protected contentVisibleAdditionalWidth = 0
  private visiblePageLabelsInfoListenersSet: Set<
    VisiblePageLabelsInfoListener<
      PageLabelVisibilityHandlerReflowableLayoutBookTypeName,
      P
    >
  > = new Set()
  private isEnabled = false

  public enable(): void {
    this.isEnabled = true
  }

  public disable(): void {
    this.isEnabled = false
    this.emitEmptyPageLabelsVisibleInfo()
  }

  public addVisiblePageLabelsInfoListener(
    listener: VisiblePageLabelsInfoListener<
      PageLabelVisibilityHandlerReflowableLayoutBookTypeName,
      P
    >,
  ): void {
    this.visiblePageLabelsInfoListenersSet.add(listener)
  }
  public removeVisiblePageLabelsInfoListener(
    listener: VisiblePageLabelsInfoListener<
      PageLabelVisibilityHandlerReflowableLayoutBookTypeName,
      P
    >,
  ): void {
    this.visiblePageLabelsInfoListenersSet.delete(listener)
  }

  public setContentViewProperties(
    contentViewProperties: ContentViewProperties<
      PageLabelVisibilityHandlerReflowableLayoutBookTypeName
    >,
  ): void {
    const {
      viewStartOffset,
      viewEndOffset,
      contentVisibleAdditionalWidth,
    } = contentViewProperties
    this.contentViewStartOffset = viewStartOffset
    this.contentViewEndOffset = viewEndOffset
    this.contentVisibleAdditionalWidth = contentVisibleAdditionalWidth
  }

  public updatePageLabelsVisibility(pageLabelsInfo: P[]): void {
    if (!this.isEnabled) {
      return
    }

    const screenAdditionalWidth: number = this.getBookPageContainerWidth()
    const pageLabelsVisibleOnWiderScreenInfo: P[] = this.getInfoOfVisiblePageLabels(
      pageLabelsInfo,
      screenAdditionalWidth,
    )
    const pageLabelsVisibleOnActualContentScreenInfo: P[] = this.getInfoOfVisiblePageLabels(
      pageLabelsInfo,
      0,
    )
    const contentViewProperties: ContentViewProperties<PageLabelVisibilityHandlerReflowableLayoutBookTypeName> = this.getContentViewProperties()
    const visiblePageLabelsInfoListenerParameters: VisiblePageLabelsInfoListenerParameters<
      PageLabelVisibilityHandlerReflowableLayoutBookTypeName,
      P
    > = {
      visibleOnWiderScreenPageLabelsInfo: pageLabelsVisibleOnWiderScreenInfo,
      visiblePageLabelsInfo: pageLabelsVisibleOnActualContentScreenInfo,
      contentViewProperties,
    }

    this.emitPageLabelsVisibleInfo(visiblePageLabelsInfoListenerParameters)
  }

  protected getBookPageContainerWidth(): number {
    return this.contentVisibleAdditionalWidth
  }

  protected getContentViewProperties(): ContentViewProperties<
    PageLabelVisibilityHandlerReflowableLayoutBookTypeName
  > {
    const {
      contentViewEndOffset,
      contentViewStartOffset,
      contentVisibleAdditionalWidth,
    } = this
    return {
      viewStartOffset: contentViewStartOffset,
      viewEndOffset: contentViewEndOffset,
      contentVisibleAdditionalWidth,
    }
  }

  protected getInfoOfVisiblePageLabels(
    pageLabelsInfo: P[],
    screenAdditionalWidth: number,
  ): P[] {
    if (!pageLabelsInfo.length) {
      return []
    }

    const {
      contentViewStartOffset: viewStartOffset,
      contentViewEndOffset: viewEndOffset,
    } = this
    const currentScreenStartOffsetWithAdditionalWidth =
      viewStartOffset - screenAdditionalWidth
    const currentScreenEndOffsetWithAdditionalWidth =
      viewEndOffset + screenAdditionalWidth

    const labelsVisibleRenderInfo: P[] = pageLabelsInfo.reduce(
      (labelsVisibleList, labelDescriptionWithPosition) => {
        const { position, pageLabelWidth } = labelDescriptionWithPosition
        const { x: pageLabelPositionX } = position

        const isVisible =
          Number.isFinite(pageLabelPositionX) &&
          Number.isFinite(pageLabelWidth) &&
          pageLabelPositionX >= currentScreenStartOffsetWithAdditionalWidth &&
          // to calculate whether the entire page label is visible on the screen
          // we should consider its width
          pageLabelPositionX <=
            currentScreenEndOffsetWithAdditionalWidth - pageLabelWidth

        if (isVisible) {
          labelsVisibleList.push(labelDescriptionWithPosition)
        }
        return labelsVisibleList
      },
      [] as P[],
    )

    return labelsVisibleRenderInfo
  }

  protected emitPageLabelsVisibleInfo(
    eventParameters: VisiblePageLabelsInfoListenerParameters<
      PageLabelVisibilityHandlerReflowableLayoutBookTypeName,
      P
    >,
  ): void {
    this.visiblePageLabelsInfoListenersSet.forEach((listener) =>
      listener(eventParameters),
    )
  }

  protected emitEmptyPageLabelsVisibleInfo() {
    this.emitPageLabelsVisibleInfo({
      visiblePageLabelsInfo: [],
      visibleOnWiderScreenPageLabelsInfo: [],
      contentViewProperties: this.getContentViewProperties(),
    })
  }
}
