import { ISettingEntry, SettingName, ReadingMode } from './types'

interface IReadiumCSSSettingValueConverter {
  name: string
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  converter: (val: any) => string | null
}

function stringConverter(value: string): string {
  return value
}

function percentConverter(value: number): string {
  return `${value}%`
}

function readingModeConverter(value: ReadingMode): string {
  switch (value) {
    case 'night':
      return 'readium-night-on'
    case 'sepia':
      return 'readium-sepia-on'
    case 'day':
      return 'readium-day-on'
    default:
      return 'readium-default-on'
  }
}

/**
 * Function for setting font stack on iframe document
 *
 * If `value` is 'default' or '' then we return null to express removal of stype
 * If called with non-blank `value` other than
 * one of ['old-style', 'modern', 'neutral, 'humanist', 'monospace']
 * font stack will pass-thru the provided `value`
 *
 * @param font View setting to specify font
 */
function fontStackConverter(font: string): string | null {
  switch (font) {
    case 'old-style':
      return 'var(--RS__oldStyleTf)'
    case 'modern':
      return 'var(--RS__modernTf)'
    case 'neutral':
      return 'var(--RS__sansTf)'
    case 'humanist':
      return 'var(--RS__humanistTf)'
    case 'monospace':
      return 'var(--RS__monospaceTf)'
    case 'default':
    case '':
      return null
    default:
      return font
  }
}

const READIUM_CSS_VAR_MAP: Map<string, IReadiumCSSSettingValueConverter> =
  new Map([
    [
      SettingName.FontSize,
      { name: '--USER__fontSize', converter: percentConverter },
    ],
    [
      SettingName.FontFamily,
      { name: '--USER__fontFamily', converter: fontStackConverter },
    ],
    [
      SettingName.ReadingMode,
      { name: '--USER__appearance', converter: readingModeConverter },
    ],
    [
      SettingName.TextColor,
      { name: '--USER__textColor', converter: stringConverter },
    ],
    [
      SettingName.BackgroundColor,
      { name: '--USER__backgroundColor', converter: stringConverter },
    ],
    [
      SettingName.FontOverride,
      { name: '--USER__fontOverride', converter: stringConverter },
    ],
    [
      SettingName.AdvancedSettings,
      { name: '--USER__advancedSettings', converter: stringConverter },
    ],
    [
      SettingName.DefaultsOverride,
      { name: '--USER__defaultsOverride', converter: stringConverter },
    ],
    [
      SettingName.FontSizeOverride,
      { name: '--USER__fontSizeOverride', converter: stringConverter },
    ],
    [
      SettingName.TextAlign,
      { name: '--USER__textAlign', converter: stringConverter },
    ],
    [
      SettingName.LineHeight,
      { name: '--USER__lineHeight', converter: stringConverter },
    ],
    [
      SettingName.Hyphens,
      { name: '--USER__bodyHyphens', converter: stringConverter },
    ],
  ])

export class ViewSettings {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private settings: Map<SettingName, any> = new Map()

  public getAllSettings(): ISettingEntry[] {
    const ret: ISettingEntry[] = []
    this.settings.forEach((value, name) => {
      ret.push({ name, value })
    })

    return ret
  }

  /**
   * Updates the view settings map with provided values
   * For font-family, the book default can be assigned by providing a value of
   * 'default' or ''
   * @param newSettings new settings to apply
   */
  public updateSetting(newSettings: ISettingEntry[]): void {
    for (const s of newSettings) {
      this.settings.set(s.name, s.value)
    }
  }

  public updateView(view: HTMLElement): void {
    this.settings.forEach((val, name) => {
      this.setCss(view, name, val)
    })
  }

  public getSetting<T>(name: SettingName): T | undefined {
    const val = this.settings.get(name)
    if (val === undefined) {
      return undefined
    }

    return val as T
  }

  public getSettingWithDefaultValue<T>(name: SettingName, defaultVal: T): T {
    const val = this.settings.get(name)
    if (val === undefined) {
      return defaultVal
    }

    return val as T
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private setCss(view: HTMLElement, varName: string, varVal: any): void {
    const cssConverter = READIUM_CSS_VAR_MAP.get(varName)
    if (cssConverter) {
      const converterValue = cssConverter.converter(varVal)
      if (converterValue) {
        view.style.setProperty(
          cssConverter.name,
          cssConverter.converter(varVal),
        )
      } else {
        view.style.removeProperty(cssConverter.name)
      }
    }
  }
}
