import ResizeSensor from 'resize-sensor'

export interface ContentViewResizeSensorConstructorParameters {
  element: HTMLElement
  callbackOnEachResize: () => void
  callbackOnFirstResize?: () => void
  callbackOnFirstResizeTimeoutMS?: number
}

export interface ContentViewResizeSensor {
  /**
   * Stop listening for resize events
   *
   * @memberof ContentViewResizeSensor
   */
  detach(): void
}

const CallbackOnFirstResizeTimeoutMSDefault = 2000

export class ContentViewResizeSensorImpl implements ContentViewResizeSensor {
  protected readonly element: HTMLElement
  protected readonly callbackOnEachResize: () => void
  protected callbackOnFirstResize?: () => void
  protected callbackOnFirstResizeTimeoutMS?: number
  protected callbackOnFirstResizeTimer?: ReturnType<typeof setTimeout>
  protected resizeSensor: typeof ResizeSensor
  constructor(parameters: ContentViewResizeSensorConstructorParameters) {
    const {
      element,
      callbackOnEachResize,
      callbackOnFirstResize,
      callbackOnFirstResizeTimeoutMS,
    } = parameters

    this.element = element
    this.callbackOnEachResize = callbackOnEachResize
    this.callbackOnFirstResize = callbackOnFirstResize
    this.callbackOnFirstResizeTimeoutMS =
      callbackOnFirstResizeTimeoutMS ?? CallbackOnFirstResizeTimeoutMSDefault

    this.createResizeSensor()
    this.runCallbackOnFirstResizeTimerIfNeeded()
  }

  public detach() {
    this.resizeSensor?.detach()

    const callbackOnFirstResizeTimer = this.callbackOnFirstResizeTimer

    if (callbackOnFirstResizeTimer) {
      clearTimeout(callbackOnFirstResizeTimer)
    }
  }

  protected runCallbackOnFirstResizeTimerIfNeeded(): void {
    if (this.callbackOnFirstResize) {
      // if onResize has not been triggered for 2 seconds
      // it's possibly won't be triggered at all
      this.callbackOnFirstResizeTimer = setTimeout(
        this.runAndUnsetCallbackOnFirstResize,
        this.callbackOnFirstResizeTimeoutMS,
      )
    }
  }

  protected createResizeSensor(): void {
    this.resizeSensor = new ResizeSensor(this.element, this.resizeHandler)
  }

  private resizeHandler = (): void => {
    if (this.callbackOnFirstResize) {
      this.runAndUnsetCallbackOnFirstResize()
    }
    this.callbackOnEachResize()
  }

  private runAndUnsetCallbackOnFirstResize = () => {
    const callback = this.callbackOnFirstResize

    this.callbackOnFirstResize = undefined
    clearTimeout(this.callbackOnFirstResizeTimer)
    callback?.()
  }
}
