import { updatePositionAndSizeToCanvas } from '../iframe-document-postprocessor/utils'

import type { ImageCopyProcessor, ImageCopyProcessorArgument } from './types'

export const imageCopyProcessor: ImageCopyProcessor = async function imageCopyProcessorImpl(
  parameters: ImageCopyProcessorArgument,
): Promise<void> {
  const { originalImage, originalImageCopy } = parameters

  if (!originalImage) {
    throw new Error('"originalImage" parameter is not defined')
  }
  if (!originalImageCopy) {
    throw new Error('"originalImageCopy" parameter is not defined')
  }
  updatePositionAndSizeToCanvas(originalImage, originalImageCopy)
}
