import { PanEvent } from '@flowpub/glue-shared'
import { SnapDirection, Viewport } from '@flowpub/renderer'

import { PanManager } from '../pan-handling'
import { Navigator } from '../navigator'

export enum PanningStateName {
  Inactive = 'INACTIVE',
  Active = 'ACTIVE',
  ScreenTransition = 'SCREEN_TRANSITION',
  Finish = 'FINISH',
  Disabled = 'DISABLED',
}

export interface PanningState {
  readonly name: PanningStateName
  /**
   * Handle an event
   *
   * @param {PanEvent} event
   * @returns {void}
   * @memberof PanningState
   */
  onPan(event: PanEvent): void
}

export type NavigatorPanStateMethods = Pick<
  Navigator,
  | 'enableScreenTransitionAnimation'
  | 'saveViewOffset'
  | 'getZoomScale'
  | 'setClearSelectionSetting'
  | 'setZoomScale'
  | 'snap'
  | 'isNavigationQueueEmpty'
>

export type ViewportPanContextMethods = Pick<Viewport, 'translate'>

export type PanManagerPanContextMethods = Pick<
  PanManager,
  | 'lastScreenX'
  | 'panningDisabled'
  | 'getGestureParams'
  | 'panStart'
  | 'getHorizontalSwipeVelocity'
  | 'getSwipeHorizontalDistance'
>

export interface PanningContext extends PanningState {
  /**
   * The very first position from which a panning
   * has started
   *
   * @type {number}
   * @memberof PanningContext
   */
  readonly panStartScrollPosition: number
  /**
   * The direction of the active screen transition
   * movement
   *
   * @type {(SnapDirection | null)}
   * @memberof PanningContext
   */
  readonly activeSnapDirectionOrNull: SnapDirection | null
  /**
   * Instance of PanManager
   *
   * @type {PanManager}
   * @memberof PanningContext
   */
  readonly panManager: PanManagerPanContextMethods // TODO - think on how to avoid violation of information expert principle
  /**
   * Returns the width of the content placed outside
   * of the visible area
   *
   * @returns {number}
   * @memberof PanningContext
   */
  getMaxScrollDist(): number
  /**
   * Set the current direction or reset it
   *
   * @param {(SnapDirection | null)} snapDirectionOrNull
   * @memberof PanningContext
   */
  setActiveSnapDirectionOrNull(snapDirectionOrNull: SnapDirection | null): void
  /**
   * Change the current state to the new one
   *
   * @param {PanningState} state
   * @returns {void}
   * @memberof PanningContext
   */
  changeState(state: PanningStateName): void
  /**
   * Update the current value of
   *
   * @param {number} panStartScrollPosition
   * @memberof PanningContext
   */
  setPanStartScrollPosition(panStartScrollPosition: number): void
  /**
   * Returns the current scroll left position of
   * the content container element
   *
   * @returns {number} HTMLElement.scrollLeft
   * @memberof PanningContext
   */
  getContentContainerScrollLeft(): number
  /**
   * Enable transition animaiton in Navigator
   *
   * @memberof PanningContext
   */
  enableNavigatorScreenTransitionAnimation(): void
  /**
   * Disable transition animaiton in Navigator
   *
   * @memberof PanningContext
   */
  disableNavigatorScreenTransitionAnimation(): void
  /**
   * Save the current offset (position) of the currently
   * visible page
   *
   * @memberof PanningContext
   */
  saveNavigatorCurrentViewOffset(): void
  /**
   * Moves the current page to the right on a given
   * number of pixels
   *
   * @param {number} offsetPx
   * @memberof PanningContext
   */
  translateNavigatorView(offsetPx: number): void
  /**
   * Returns the curren zoom scale level
   *
   * @returns {number}
   * @memberof PanningContext
   */
  getNavigatorZoomScale(): number
  /**
   * Set the current zoom level to 1
   *
   * @memberof PanningContext
   */
  resetNavigatorZoomLevel(): void
  /**
   * Enable the functionality of cleaning the current text
   * selection on any navigation action
   *
   * @memberof PanningContext
   */
  enableNavigatorClearSelectionSetting(): void
  /**
   * Disable the functionality of cleaning the current text
   * selection on any navigation action
   *
   * @memberof PanningContext
   */
  disableNavigatorClearSelectionSetting(): void
  /**
   * Snap the screen
   *
   * @param {SnapDirection} direction
   * @memberof PanningContext
   */
  snapNavigator(direction: SnapDirection): Promise<void>
  /**
   * Checks whether any active navigation task is in progress
   *
   * @returns {boolean}
   * @memberof PanningContext
   */
  isNavigatorTransitionInProgress(): boolean
}

export interface PanningStateConstructor {
  /**
   * Declares which of the states this constructor builds
   *
   * @type {PanningStateName}
   * @memberof PanningStateConstructor
   */
  state: PanningStateName
  new (context: PanningContext): PanningState
}

export interface PanningContextConstructorParameters {
  navigator: NavigatorPanStateMethods
  viewport: ViewportPanContextMethods
  contentContainer: HTMLElement
  panManager: PanManagerPanContextMethods
  stateConstructors: PanningStateConstructor[]
}

export interface PanningContextConstructor {
  new (parameters: PanningContextConstructorParameters): PanningContext
}
