import { getComputedStyle, getElementCSSStyles } from '../../../utils'

import type { IsContainingBlockForFixedPositionedElementCallback } from './types'

// Inspired by the code https://github.com/zakplus/containing-block/blob/master/src/index.js#L110
export const isContainingBlockForFixedPositionedElementCallbackImpl: IsContainingBlockForFixedPositionedElementCallback = function isContainingBlockForFixedPositionedElement(
  element: HTMLElement,
): boolean {
  if (!element) {
    throw new Error('"element" is not defined')
  }
  if (element.tagName.toLowerCase() === 'html') {
    return false
  }
  // need to check these two objects separately, see function descriptions for details
  const computedStyles = getComputedStyle(element)
  const {
    contain,
    backdropFilter,
  } = getElementCSSStyles(element)
  return Boolean(
    checkComputedStylesForFixedPositionElement(computedStyles) ||
      contain === 'paint' ||
      (backdropFilter && backdropFilter !== 'none' && backdropFilter !== '')
  )
}

function checkComputedStylesForFixedPositionElement(styles: CSSStyleDeclaration): boolean {
  const {
    perspective,
    transform,
    filter,
    willChange,
  } = styles
  return Boolean(
    (perspective && perspective !== 'none' && perspective !== '') ||
      (transform && transform !== 'none' && transform !== '') ||
      (filter && filter !== 'none' && filter !== '') ||
      willChange === 'transform' ||
      willChange === 'perspective' ||
      willChange === 'filter',
  )
}