import type {
  Resource,
  ResourceTypeCSS,
  InstantiateResourceByURL,
} from '../navigator'

/**
 * Returns a resource description by a CSS file url.
 *
 * @template U
 * @param {U} url - the url of a CSS file.
 * @return {Resource<ResourceTypeCSS, U>}
 */
export const instantiateCSSResourceByUrl: InstantiateResourceByURL<ResourceTypeCSS> = function instantiateCSSResourceByUrl<
  U extends string
>(url: U): Resource<ResourceTypeCSS, U> {
  return {
    type: 'text/css',
    href: url,
    insertion: 'append',
    target: 'head',
  }
}
