import { PanEvent } from '@flowpub/glue-shared'
import { SnapDirection } from '@flowpub/renderer'

import { PanSettings } from '../../pan-handling'
import { PanningState, PanningStateName, PanningContext } from '../types'

export class PanningFinished implements PanningState {
  static state: PanningStateName = PanningStateName.Finish
  public get name(): PanningStateName {
    return PanningFinished.state
  }
  constructor(private readonly context: PanningContext) {}

  public onPan(event: PanEvent): void {
    if (!event.end) {
      return
    }

    const context = this.context
    // end of panning or user transitioned from panning to pinching
    const direction: SnapDirection | null = this.getSnapDirectionOrNull(event)

    // TODO - add a method for lastScreenX = event.screenX1
    context.panManager.lastScreenX = event.screenX1

    if (direction === null) {
      context.changeState(PanningStateName.Inactive)
      context.onPan(event)
      return
    }

    context.setActiveSnapDirectionOrNull(direction)
    context.changeState(PanningStateName.ScreenTransition)
    context.onPan(event)
  }

  protected getSnapDirectionOrNull(event: PanEvent): SnapDirection | null {
    const context = this.context

    // if (context.isNavigatorTransitionInProgress()) {
    //   // TODO - verify this
    //   return null
    // }

    const panManager = context.panManager
    // end of panning or user transitioned from panning to pinching
    const gestureParams: PanSettings = panManager.getGestureParams()
    const swipeVelocity: number = panManager.getHorizontalSwipeVelocity(
      panManager.panStart,
      event,
    )
    const swipeHorizontalDistance = panManager.getSwipeHorizontalDistance(
      panManager.panStart,
      event,
    )
    let direction: SnapDirection | null = null

    if (context.getNavigatorZoomScale() === 1) {
      direction = SnapDirection.Auto
      if (swipeVelocity > gestureParams.swipeVelocityThreshold) {
        direction = SnapDirection.Prev
      } else if (swipeVelocity < -gestureParams.swipeVelocityThreshold) {
        direction = SnapDirection.Next
      }
    }

    // if zoomed in, change page only if swiping ends outside of visible content
    if (direction === null && context.panStartScrollPosition < 1) {
      if (
        swipeVelocity > gestureParams.swipeVelocityThreshold ||
        swipeHorizontalDistance * 0.2 > window.innerWidth
      ) {
        direction = SnapDirection.Prev
      } else {
        direction = SnapDirection.Auto
      }
    }

    // if zoomed in, change page only if swiping ends outside of visible content
    if (
      direction === null &&
      context.panStartScrollPosition > context.getMaxScrollDist() - 1
    ) {
      if (
        swipeVelocity < -gestureParams.swipeVelocityThreshold ||
        -swipeHorizontalDistance * 0.2 > window.innerWidth
      ) {
        direction = SnapDirection.Next
      } else {
        direction = SnapDirection.Auto
      }
    }
    return direction
  }
}
