export { Navigator }

export function createNavigator(
  viewportRootSelector: HTMLElement | string,
): Navigator {
  const navigator = new Navigator(viewportRootSelector)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  ;(globalThis as any).flowpub_debug_navigator = navigator
  return navigator
}

