/**
 * Only a certain number of digits after comma matters,
 * thus others will be dropped.
 *
 * @private
 * @param {number} coordinatePixels - the original coordinates in px.
 * @return {number} - rounded.
 * @memberof ElementVisibilityChecker
 */
export function roundPixelCoordinate(coordinatePixels: number): number {
  if (Number.isNaN(coordinatePixels)) {
    throw new Error('The argument should not be a NaN value')
  }
  if (typeof coordinatePixels !== 'number') {
    throw new Error('The argument should be a numeric value')
  }
  return Math.round(coordinatePixels * 1000) / 1000
}
