import type {
  UnobserveCallback,
  ImageCopyTracker,
  IContentView,
} from '@flowpub/renderer'
import {
  unobserveImages,
  createImageCopyTrackerDefaultImpl,
} from '@flowpub/renderer'

import type { Navigator } from './navigator'

/**
 * Navigator API methods which are used by the function.
 *
 * @export
 * @interface TrackDRMObfuscatedImageSizesParametersNavigator
 * @extends {(Pick<Navigator, 'onVisiblePagesReady' | 'onResizeEndCallback'>)}
 */
export interface TrackDRMObfuscatedImageSizesParametersNavigator
  extends Pick<Navigator, 'onVisiblePagesReady' | 'onResizeEndCallback'> {
  viewportMethods:
    | Pick<
        Exclude<Navigator['viewportMethods'], undefined>,
        'getDocumentsOfVisibleSpineItems' | 'setUnloadSpineItemHandler'
      >
    | undefined
}

export interface TrackDRMObfuscatedImageSizesParameters {
  /**
   * A limited set of API Navigator methods that are used
   * internally by the function.
   *
   * @type {Navigator}
   * @memberof TrackDRMObfuscatedImageSizesParameters
   */
  navigator: TrackDRMObfuscatedImageSizesParametersNavigator
  /**
   * An instance that is employed to handle changes in the size/position
   * of the original images.
   *
   * @type {ImageCopyTracker}
   * @memberof TrackDRMObfuscatedImageSizesParameters
   */
  imageCopyTracker?: ImageCopyTracker
  /**
   * Unobserve images to avoid memory leak issue in DRM image obfuscation.
   *
   * @type {UnobserveCallback}
   * @memberof TrackDRMObfuscatedImageSizesParameters
   */
  unobserveCallback?: UnobserveCallback
}

/**
 * Tracks the position and size of DRM obfuscated images
 * and reflect the changes on image copies.
 *
 * @export
 * @param {TrackDRMObfuscatedImageSizesParameters} parameters
 */
export function trackDRMObfuscatedImageSizes(
  parameters: TrackDRMObfuscatedImageSizesParameters,
): void {
  const { navigator, imageCopyTracker, unobserveCallback } = parameters

  if (!navigator) {
    throw new Error('"navigator" parameter should be defined')
  }

  const imageCopyTrackerImpl =
    imageCopyTracker ?? createImageCopyTrackerDefaultImpl()
  const unobserveCallbackImpl = unobserveCallback ?? unobserveImages

  let isUnobserveCallbackSet = false
  function setUnobserveCallback(): void {
    if (isUnobserveCallbackSet) {
      return
    }
    if (!navigator.viewportMethods) {
      return
    }
    // Unobserve images in DRM to avoid memory leak
    navigator.viewportMethods.setUnloadSpineItemHandler(
      (contentView: IContentView) =>
        unobserveCallbackImpl(contentView.element()),
    )
    isUnobserveCallbackSet = true
  }

  async function updateOnSingleSpineDocument(
    this: ImageCopyTracker,
    spineDocument: Document,
  ): Promise<void> {
    await this.collectAndUpdate({
      document: spineDocument,
    })
  }

  const eventHandlerContext = {
    navigator,
    updateOnSingleSpineDocument: updateOnSingleSpineDocument.bind(
      imageCopyTrackerImpl,
    ),
    setUnobserveCallback,
  }
  async function updateImagesOnVisibleSpines(
    this: typeof eventHandlerContext,
  ): Promise<void> {
    this.setUnobserveCallback()

    const documents: Document[] =
      this.navigator.viewportMethods?.getDocumentsOfVisibleSpineItems() || []
    await Promise.all(documents.map(this.updateOnSingleSpineDocument))
  }
  // bind to the object to reduce memory consumption
  const updateImagesOnVisibleSpinesBindToContext = updateImagesOnVisibleSpines.bind(
    eventHandlerContext,
  )

  navigator.onVisiblePagesReady(updateImagesOnVisibleSpinesBindToContext)
  navigator.onResizeEndCallback(updateImagesOnVisibleSpinesBindToContext)
  setUnobserveCallback()
}
