import { Caller } from '@flowpub/glue-rpc'
import {
  ContentEventListenerContext,
  ContentEventManager,
  ContentEventSource,
  Viewport,
} from '@flowpub/renderer'
import { Link, Publication } from '@flowpub/webpub-model'
import { degausser } from 'degausser'

import {
  ContentViewProperties,
  PageLabelVisibilityHandlerFixedLayoutBookTypeName,
  VisiblePageLabelsInfoListener,
  VisiblePageLabelsInfoListenerParameters,
} from '../../renderer/src/navigator/types'

import {
  PageLabelVisibilityHandler,
  PageLabelVisibilityHandlerTypeName,
} from './page-label-visibility-handler'
import {
  PageLabelManagerEventEmitter,
  Rect,
  PageLabelsVisibleInfoEventEmitter,
  PageLabelInfo,
  Locator,
} from './types'
import { PageLabelVisibilityHandlerTypeNameIfFixedLayout } from './page-label-visibility-handler/types'
import { pageLabelVisibilityHandlerFabricByType } from './page-label-visibility-handler/page-label-visibility-handler-fabric-by-type'
import { getRangeForCfi } from './utils/location-comparitors'
import {
  classBlacklist,
  elementBlacklist,
  idBlacklist,
} from './default-blacklist'

export const PageLabelAddMessage = 'PAGE_LABEL_ADD'
export const PageLabelViewportUdateMessage = 'PAGE_LABEL_VIEWPORT_UPDATE'
export const PageLabelAriaLabelUpdateMessage = 'PAGE_LABEL_ARIA_LABEL_UPDATE'

// PageLabelLocationType replicated in flowpub/core/packages/content/src/page-label-handling.ts
enum PageLabelLocationType {
  Anchor,
  CFI,
  Offset,
  None,
}

type SpineItemIndex = number

type SpineItemResponse = Promise<string>

type SpineItemsPendingResponse = Map<SpineItemIndex, SpineItemResponse>

export type PageLabelInfoWithPosition = PageLabelInfo & {
  position: Rect
  timestampMs: number
}

export type PageLabelsPositionsUpdateListener = (
  pageLabelInfoWithPositionAndAriaLabel: PageLabelInfoWithPosition[],
) => void

export type PageLabelVisibleRange = {
  actualStartOffset: number
  actualEndOffset: number
  spineItemIndex: number
  isFirstVisible: boolean
}

export type PageLabelsVisibleRangeUpdatedListener = (
  visibleRange: PageLabelVisibleRange,
) => void

export type PageLabelsVisibilityFlagListener = (
  arePageLabelsVisible: boolean,
) => void

class PageLabelHandling extends Caller {
  public async addPageLabels(
    pageLabelListJson: string,
    ariaLabel: string,
  ): Promise<string> {
    return this.call(PageLabelAddMessage, [pageLabelListJson, ariaLabel])
  }

  public async updateViewport(): Promise<string> {
    return this.call(PageLabelViewportUdateMessage, [])
  }

  public async ariaLabelUpdate(ariaLabel: string): Promise<string> {
    return this.call(PageLabelAriaLabelUpdateMessage, [ariaLabel])
  }
}

class PageLabelEventSource implements ContentEventSource {
  public spineItemIndex = -1

  private eventSource: PageLabelHandling

  public constructor(win: Window) {
    this.eventSource = new PageLabelHandling('page-label-handling', win)
  }

  public async addPageLabels(
    pageLabelListJson: string,
    ariaLabel: string,
  ): Promise<string> {
    return await this.eventSource.addPageLabels(pageLabelListJson, ariaLabel)
  }

  public async updateViewport(): Promise<string> {
    return await this.eventSource.updateViewport()
  }

  public async ariaLabelUpdate(ariaLabel: string): Promise<string> {
    return await this.eventSource.ariaLabelUpdate(ariaLabel)
  }

  public async addListener(
    _listener: ContentEventListenerContext,
  ): Promise<number> {
    return 0
  }

  public async removeListener(
    _listener: ContentEventListenerContext,
  ): Promise<void> {
    // Empty function
  }
}

export class PageLabelManager<FXL extends boolean = boolean>
  extends ContentEventManager
  implements PageLabelManagerEventEmitter {
  private pageLabelStringMap = new Map<number, string>()
  private pageLabelInfoList: PageLabelInfo[] = []

  private ariaLabel = 'Page break'

  private isPageLabelVisible = false

  private isEnabled = false

  private viewport: Viewport
  private isFixedLayout: FXL = false as FXL

  private actualPageLabelsInfoWithPositionsStringifiedResponsePending: SpineItemsPendingResponse = new Map()
  private pageLabelsPositionsUpdateListeners: PageLabelsPositionsUpdateListener[] = []

  private pageLabelsVisibleRangeUpdatedListeners: PageLabelsVisibleRangeUpdatedListener[] = []

  private pageLabelsVisibilityFlagListeners: PageLabelsVisibilityFlagListener[] = []
  private get pageLabelVisibilityHandlerTypeName(): PageLabelVisibilityHandlerTypeNameIfFixedLayout<
    FXL
  > {
    return (this.isFixedLayout
      ? PageLabelVisibilityHandlerTypeName.Fixed
      : PageLabelVisibilityHandlerTypeName.Reflowable) as PageLabelVisibilityHandlerTypeNameIfFixedLayout<
      FXL
    >
  }

  private pageLabelVisibilityHandler: PageLabelVisibilityHandler<
    PageLabelVisibilityHandlerTypeNameIfFixedLayout<FXL>
  >

  /**
   * If the "init" method has been called
   *
   * @protected
   * @memberof PageLabelManager
   */
  protected isInitialized = false
  public init(pageList: Link[], pub: Publication, v: Viewport): void {
    this.createAndSetPageLabelVisibilityHandler()
    this.switchPageLabelVisibilityHandler(this.isEnabled)
    this.setViewport(v)

    const pageLabelMap = new Map<number, PageLabelInfo[]>()
    for (const pageLabel of pageList) {
      if (!pageLabel.title) {
        continue
      }
      const href = pageLabel.href.split('#')[0]
      const spineItemIndex = pub.findSpineItemIndexByHref(href)
      if (spineItemIndex < 0) {
        continue
      }

      const label = this.pageLinkToPageLabel(pageLabel)

      let labels = pageLabelMap.get(spineItemIndex)
      if (!labels) {
        labels = []
        pageLabelMap.set(spineItemIndex, labels)
      }
      labels.push(label)
    }

    const isFixedLayout = this.isFixedLayout

    pageLabelMap.forEach((value, key) => {
      if (isFixedLayout) {
        this.pageLabelStringMap.set(key, value[0].label)
      } else {
        this.pageLabelStringMap.set(key, JSON.stringify(value))
      }
      this.pageLabelInfoList.push(...value)
    })
    if (isFixedLayout) {
      this.setListenerFXLBookPageLabelVisibilityInfo()
    }
    this.isInitialized = true
  }

  public pageLinkToPageLabel(pageLink: Link): PageLabelInfo {
    const [href, fragment] = pageLink.href.split('#')
    const spineItemIndex = this.viewport.getSpineItemIndexByHref(href)

    let pageLabelType = PageLabelLocationType.Anchor
    // somehow fragment might not be exists
    if (fragment?.indexOf('epubcfi(/') >= 0) {
      pageLabelType = PageLabelLocationType.CFI
    }

    return {
      type: pageLabelType,
      location: fragment,
      label: pageLink.title || '',
      spineItemIndex: spineItemIndex,
    }
  }

  /**
   * Converts a link object to a locator object with as much information as available
   * @param pageLink Link object
   * @param sizeUpToResource character offset up to resource in reading order
   */
  public pageLinkToLocation(
    pageLink: Link,
    sizeUpToResource?: number,
  ): Locator {
    const pageLabel = this.pageLinkToPageLabel(pageLink)
    const labelLocator: Locator = {
      href: `${pageLink.href.split('#')[0]}`,
      type: 'application/xhtml+xml',
      title: pageLabel.label,
      locations: {},
    }

    if (typeof pageLabel.location !== 'string') {
      return labelLocator
    }

    const fragments = []
    fragments.push(pageLabel.location)
    labelLocator.locations = {
      fragments,
    }
    const spineItemView = this.viewport.getSpineItemViewByHref(
      labelLocator.href,
    )
    let range
    // todo refactor each case to separate function/class to manage size/scope
    if (pageLabel.type === PageLabelLocationType.CFI) {
      // get partial CFI info
      let partialCfi = ''
      if (pageLabel.location.includes('epubcfi(')) {
        partialCfi = pageLabel.location.split('epubcfi(')[1]
        if (partialCfi.includes('!')) {
          // partial cfi is part after step indirection, '!', if present
          partialCfi = partialCfi.split('!')[1]
        }
        partialCfi = partialCfi.split(')')[0]
        labelLocator.locations.partialCfi = partialCfi
      }

      // todo fetch spine item view before if block
      if (!spineItemView) {
        return labelLocator
      }

      range = getRangeForCfi(spineItemView.getContentView(), partialCfi)
      if (!range) {
        return labelLocator
      }
    } else if (pageLabel.type === PageLabelLocationType.Anchor) {
      if (!spineItemView) {
        return labelLocator
      }

      const iframeDoc: Document | null = this.viewport.getSpineItemDocumentByHrefOrNull(
        labelLocator.href,
      )
      if (!iframeDoc) {
        return labelLocator
      }

      const element = iframeDoc.getElementById(pageLabel.location)
      if (!element) {
        return labelLocator
      }

      // get position/relativePosition info
      range = document.createRange()
      range.selectNode(element)
    }

    if (!range) {
      return labelLocator
    }

    const relativePosition = PageLabelManager.rangeToRelativePosition(range)
    if (relativePosition === null) {
      return labelLocator
    }

    labelLocator.locations.relativePosition = relativePosition
    if (sizeUpToResource !== undefined) {
      labelLocator.locations.position = relativePosition + sizeUpToResource
    }

    return labelLocator
  }

  /**
   * Calculates the text offset from the start of the document to the end of the range
   * @param range DOM Range
   * @returns number text offset
   */
  private static rangeToRelativePosition(range: Range): number | null {
    range.collapse(false)
    if (!range.startContainer?.ownerDocument?.documentElement) {
      return null
    }

    range.setStartBefore(
      range.startContainer?.ownerDocument?.documentElement as Node,
    )
    const fragment = range.cloneContents()
    return degausser(fragment, {
      classBlacklist,
      idBlacklist,
      elementBlacklist,
    }).length
  }

  public attachToVisiblePageLabelsInfoEventEmitter(
    visiblePageLabelsInfoEventEmitter: PageLabelsVisibleInfoEventEmitter,
  ): void {
    visiblePageLabelsInfoEventEmitter.attachToPageLabelVisibilityHandler(
      this.pageLabelVisibilityHandler,
    )
  }

  /**
   * Disabling and enabling the manager is implemented through switching of
   * the visibility of page labels, b/c even if the instance is not enabled
   * events should be handled to do rendering properly after this instance is
   * enabled again.
   *
   * @memberof PageLabelManager
   */
  public enable(): void {
    this.isEnabled = true
    if (this.isPageLabelVisible) {
      this.notifyPageLabelsVisibilityChangeIfInitialized(true)
    }
    this.switchPageLabelVisibilityHandlerIfInitialized(true)
  }

  public disable(): void {
    this.isEnabled = false
    this.switchPageLabelVisibilityHandlerIfInitialized(false)
  }

  public makeEventSource(
    win: Window,
    spineItemIndex: number,
  ): ContentEventSource {
    const eventSource = new PageLabelEventSource(win)

    this.handleEventSourceHasCreated(eventSource, spineItemIndex)
    return eventSource
  }

  public setIsFixedLayout(fxl: FXL): void {
    this.isFixedLayout = fxl
  }

  protected setViewport(v: Viewport): void {
    this.viewport = v
    this.attachToViewport()
  }

  public async updateViewport(): Promise<void> {
    for (const es of this.eventSources) {
      const pageLabelSource = es[1] as PageLabelEventSource
      await this.handlePendingResponseWithUpdatedPageLabelsInfoWithPositions(
        pageLabelSource.spineItemIndex,
        pageLabelSource.updateViewport(),
      )
    }
  }

  public updatePageLabelVisibility(visible: boolean): void {
    this.isPageLabelVisible = visible
    if (this.isEnabled) {
      this.notifyPageLabelsVisibilityChangeIfInitialized(visible)
    }
  }

  public async updateAriaLabel(ariaLabel: string): Promise<void> {
    this.ariaLabel = ariaLabel
    for (const es of this.eventSources) {
      const pageLabelSource = es[1] as PageLabelEventSource
      const siIndex = pageLabelSource.spineItemIndex

      if (this.isFixedLayout && this.viewport) {
        const pageLabel = this.pageLabelStringMap.get(siIndex)
        if (pageLabel) {
          const siView = this.viewport.getSpineItemView(siIndex)
          siView?.updatePageLabelAriaLabel(ariaLabel)
        }
      } else {
        await pageLabelSource.ariaLabelUpdate(ariaLabel)
      }
    }
  }

  public visibleRangeUpdate(
    startIndex: number,
    startOffset: number,
    endIndex: number,
    endOffset: number,
  ): void {
    if (this.isFixedLayout) {
      this.updateFXLBookPageLabelsVisibilityInfo({
        visibleSpineItemEndIndex: endIndex,
        visibleSpineItemStartIndex: startIndex,
      })
      return
    }

    for (const es of this.eventSources) {
      const pageLabelSource = es[1] as PageLabelEventSource
      const siIndex = pageLabelSource.spineItemIndex
      let actualStartOffset = startOffset
      let actualEndOffset = endOffset
      let isFirstVisible = true
      if (siIndex < startIndex || siIndex > endIndex) {
        continue
      }
      if (siIndex > startIndex) {
        actualStartOffset = 0
        isFirstVisible = false
      }
      if (siIndex < endIndex) {
        actualEndOffset = Number.MAX_SAFE_INTEGER
      }
      this.notifyVisibleRangeUpdate(
        actualStartOffset,
        actualEndOffset,
        isFirstVisible,
        siIndex,
      )
      this.updateViewport()
    }
  }

  public addListenerPageLabelsPositionsUpdate(
    listener: PageLabelsPositionsUpdateListener,
  ): void {
    this.pageLabelsPositionsUpdateListeners.push(listener)
  }

  public addPageLabelsVisibleRangeUpdatedListener(
    listener: PageLabelsVisibleRangeUpdatedListener,
  ): void {
    this.pageLabelsVisibleRangeUpdatedListeners.push(listener)
  }

  public addPageLabelsVisibilityFlagListener(
    listener: PageLabelsVisibilityFlagListener,
  ): void {
    this.pageLabelsVisibilityFlagListeners.push(listener)
  }

  protected updateFXLBookPageLabelsVisibilityInfo({
    visibleSpineItemStartIndex,
    visibleSpineItemEndIndex,
  }: {
    visibleSpineItemStartIndex: number
    visibleSpineItemEndIndex: number
  }): void {
    const pageLabelVisibilityHandler = this
      .pageLabelVisibilityHandler as PageLabelVisibilityHandler<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName
    >
    const pageLabelInfoList: PageLabelInfo[] = this.pageLabelInfoList
    const contentViewAttributes: ContentViewProperties<PageLabelVisibilityHandlerFixedLayoutBookTypeName> = {
      lastVisibleSpineItemIndex: visibleSpineItemEndIndex,
      firstVisibleSpineItemIndex: visibleSpineItemStartIndex,
    }
    pageLabelVisibilityHandler.setContentViewProperties(contentViewAttributes)
    pageLabelVisibilityHandler.updatePageLabelsVisibility(pageLabelInfoList)
  }

  protected createAndSetPageLabelVisibilityHandler(): void {
    this.pageLabelVisibilityHandler = pageLabelVisibilityHandlerFabricByType(
      this.pageLabelVisibilityHandlerTypeName,
    )
  }

  protected attachToViewport(): void {
    const viewport = this.viewport

    if (!viewport) {
      throw new Error('An instance of the Viewport should be set ')
    }
    if (!this.isFixedLayout) {
      viewport.handlePageLabelsManager(this)
      viewport.initReflowablePageLabelsView(
        this.pageLabelVisibilityHandler as PageLabelVisibilityHandler<
          PageLabelVisibilityHandlerTypeName.Reflowable
        >,
      )
    }
  }

  protected notifyPageLabelsVisibilityChangeIfInitialized(
    visible: boolean,
  ): void {
    // if this instance haven't been initialized through the "init" method
    // it's not necessary to notify any listeners about changes, because
    // a publication is not opened yet
    if (!this.isInitialized) {
      return
    }
    this.notifyPageLabelsVisibilityChange(visible)
  }

  protected notifyPageLabelsVisibilityChange(visible: boolean): void {
    for (const es of this.eventSources) {
      const pageLabelSource = es[1] as PageLabelEventSource
      const siIndex = pageLabelSource.spineItemIndex

      if (this.isFixedLayout && this.viewport) {
        const pageLabel = this.pageLabelStringMap.get(siIndex)
        if (pageLabel) {
          const siView = this.viewport.getSpineItemView(siIndex)
          siView?.updatePageLabelVisibility(this.isEnabled && visible)
        }
      }
    }
    this.notifyPageLabelsVisibilityFlagListeners(visible)
  }

  protected switchPageLabelVisibilityHandlerIfInitialized(isEnable: boolean) {
    if (this.isInitialized) {
      this.switchPageLabelVisibilityHandler(isEnable)
    }
  }

  protected switchPageLabelVisibilityHandler(isEnable: boolean) {
    if (isEnable) {
      this.pageLabelVisibilityHandler.enable()
    } else {
      this.pageLabelVisibilityHandler.disable()
    }
  }

  protected handleEventSourceHasCreated(
    eventSource: PageLabelEventSource,
    spineItemIndex: number,
  ): void {
    if (!this.isFixedLayout) {
      const pageLabelListJson = this.pageLabelStringMap.get(spineItemIndex)
      if (pageLabelListJson) {
        this.handlePendingResponseWithUpdatedPageLabelsInfoWithPositions(
          spineItemIndex,
          eventSource.addPageLabels(pageLabelListJson, this.ariaLabel),
        )
      } else {
        this.rerenderPageLabels()
      }
    }
  }

  protected emitPageLabelsPositionsUpdate(
    pageLabelInfoWithPositionAndAriaLabel: PageLabelInfoWithPosition[],
  ): void {
    this.pageLabelsPositionsUpdateListeners.forEach((listerFromList) =>
      listerFromList(pageLabelInfoWithPositionAndAriaLabel),
    )
  }

  protected rerenderPageLabels(): void {
    this.emitPageLabelsPositionsUpdate([])
  }

  protected handleResponseWithUpdatedPageLabelsInfoWithPositionsStringified(
    response: string,
  ): void {
    const responseParsed = JSON.parse(response) as PageLabelInfoWithPosition[]

    this.emitPageLabelsPositionsUpdate(responseParsed)
  }

  protected async handlePendingResponseWithUpdatedPageLabelsInfoWithPositions(
    spineItemIndex: SpineItemIndex,
    updatedPageLabelsInfoWithPositionsStringified: SpineItemResponse,
  ): Promise<void> {
    this.actualPageLabelsInfoWithPositionsStringifiedResponsePending.set(
      spineItemIndex,
      updatedPageLabelsInfoWithPositionsStringified,
    )

    const response = await updatedPageLabelsInfoWithPositionsStringified

    if (
      this.actualPageLabelsInfoWithPositionsStringifiedResponsePending.get(
        spineItemIndex,
      ) !== updatedPageLabelsInfoWithPositionsStringified
    ) {
      // if we have a newer pending promise we should handle result of that one rather than old one
      return
    }
    this.handleResponseWithUpdatedPageLabelsInfoWithPositionsStringified(
      response,
    )
  }

  protected notifyVisibleRangeUpdate(
    actualStartOffset: number,
    actualEndOffset: number,
    isFirstVisible: boolean,
    spineItemIndex: number,
  ): void {
    const visibleRange: PageLabelVisibleRange = {
      actualStartOffset,
      actualEndOffset,
      isFirstVisible,
      spineItemIndex,
    }
    this.pageLabelsVisibleRangeUpdatedListeners.forEach((listener) => {
      listener(visibleRange)
    })
  }

  protected notifyPageLabelsVisibilityFlagListeners(isVisible: boolean): void {
    this.pageLabelsVisibilityFlagListeners.forEach((listener) =>
      listener(isVisible),
    )
  }

  protected handlerFXLBookPageLabelVisibilityInfo(
    pageLabelsVisibilityInfo: VisiblePageLabelsInfoListenerParameters<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName
    >,
  ): void {
    if (!this.viewport) {
      throw new Error('There is no instance of Viewport existing')
    }
    if (!this.isFixedLayout) {
      throw new Error('Only fixed layout publications are supported')
    }
    if (!this.isPageLabelVisible) {
      return
    }

    const {
      contentViewProperties,
      visiblePageLabelsInfo,
    } = pageLabelsVisibilityInfo
    const { firstVisibleSpineItemIndex: startIndex } = contentViewProperties
    const isPageLabelVisible: boolean =
      this.isEnabled && this.isPageLabelVisible

    for (const es of this.eventSources) {
      const { spineItemIndex: siIndex } = es[1] as PageLabelEventSource
      const isFirstVisible = siIndex <= startIndex
      const siView = this.viewport.getSpineItemView(siIndex)

      if (!siView) {
        continue
      }

      const pageLabelsVisibleOnSpineItem = visiblePageLabelsInfo.filter(
        (pageLabelInfo) => pageLabelInfo.spineItemIndex === siIndex,
      )

      pageLabelsVisibleOnSpineItem.forEach(({ label }: PageLabelInfo) => {
        if (!label) {
          return
        }
        siView.renderPageLabel(
          label,
          isFirstVisible,
          isPageLabelVisible,
          this.ariaLabel,
        )
      })
    }
  }

  protected setListenerFXLBookPageLabelVisibilityInfo(): void {
    const pageLabelVisibilityHandler = this
      .pageLabelVisibilityHandler as PageLabelVisibilityHandler<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName
    >
    pageLabelVisibilityHandler.addVisiblePageLabelsInfoListener(
      this.listenerFXLBookPageLabelVisibilityInfo,
    )
  }

  private listenerFXLBookPageLabelVisibilityInfo: VisiblePageLabelsInfoListener<
    PageLabelVisibilityHandlerFixedLayoutBookTypeName
  > = (
    pageLabelsVisibilityInfo: VisiblePageLabelsInfoListenerParameters<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName
    >,
  ): void => {
    this.handlerFXLBookPageLabelVisibilityInfo(pageLabelsVisibilityInfo)
  }
}
