import {
  PageLabelsVisibleInfoEventEmitter,
  PageLabelVisibilityHandlerEventListenerMethods,
  PageLabelsVisibleInfoListener,
} from './types'
import {
  VisiblePageLabelsInfoListener,
  VisiblePageLabelsInfoListenerParametersCommon,
} from './page-label-visibility-handler/types'

export class PageLabelsVisibleInfoEventEmitterImpl
  implements PageLabelsVisibleInfoEventEmitter {
  private pageLabelVisibilityHandler:
    | PageLabelVisibilityHandlerEventListenerMethods
    | undefined
  private pageLabelsVisibleInfoListenersSet: Set<
    PageLabelsVisibleInfoListener
  > = new Set()
  public attachToPageLabelVisibilityHandler(
    pageLabelVisibilityHandler: PageLabelVisibilityHandlerEventListenerMethods,
  ): void {
    this.unsetListenersFromCurrentPageLabelVisibilityHandler()
    this.pageLabelVisibilityHandler = pageLabelVisibilityHandler
    this.setListenersOnPageLabelVisibilityHandler(pageLabelVisibilityHandler)
  }

  public addVisiblePageLabelsInfoListener(
    listener: PageLabelsVisibleInfoListener,
  ): void {
    this.pageLabelsVisibleInfoListenersSet.add(listener)
  }
  public removeVisiblePageLabelsInfoListener(
    listener: PageLabelsVisibleInfoListener,
  ): void {
    this.pageLabelsVisibleInfoListenersSet.delete(listener)
  }

  protected setListenersOnPageLabelVisibilityHandler(
    pageLabelVisibilityHandler: PageLabelVisibilityHandlerEventListenerMethods,
  ) {
    pageLabelVisibilityHandler.addVisiblePageLabelsInfoListener(
      this.handleVisiblePageLabelsInfo,
    )
  }

  protected unsetListenersOnPageLabelVisibilityHandler(
    pageLabelVisibilityHandler: PageLabelVisibilityHandlerEventListenerMethods,
  ) {
    pageLabelVisibilityHandler.removeVisiblePageLabelsInfoListener(
      this.handleVisiblePageLabelsInfo,
    )
  }

  protected unsetListenersFromCurrentPageLabelVisibilityHandler(): void {
    const pageLabelVisibilityHandler = this.pageLabelVisibilityHandler
    if (pageLabelVisibilityHandler) {
      this.unsetListenersOnPageLabelVisibilityHandler(
        pageLabelVisibilityHandler,
      )
    }
  }

  protected emitVisiblePageLabelsInfo(
    visiblePageLabelsEventParameter: VisiblePageLabelsInfoListenerParametersCommon,
  ): void {
    const { visiblePageLabelsInfo } = visiblePageLabelsEventParameter
    this.pageLabelsVisibleInfoListenersSet.forEach((listener) =>
      listener(visiblePageLabelsInfo),
    )
  }

  private handleVisiblePageLabelsInfo: VisiblePageLabelsInfoListener = (
    visiblePageLabelsEventParameter: VisiblePageLabelsInfoListenerParametersCommon,
  ): void => {
    this.emitVisiblePageLabelsInfo(visiblePageLabelsEventParameter)
  }
}
