/**
 * Will travel through all the nearest ancestors of an element.
 *
 * @export
 * @param {HTMLElement} element - initial element.
 * @param {(element: HTMLElement) => boolean} callback - a callback that will be invoked with an ancestor
 * of the previous ancestor of the initial element.
 * If the function returns "true" the execution will be terminated and the element, which is the argument,
 * the callback function was called with, will be returned as the result.
 * @return {(HTMLElement | null)} - an ancestor or null if the callback function didn't return "true" for
 * any of "element" ancestors.
 */
export function traverseThroughAncestors(
  element: HTMLElement,
  callback: (element: HTMLElement) => boolean,
  // if the inner loop will exceed this limit on iterations number an error will be thrown.
  maxDepth = 100,
): HTMLElement | null {
  let nearestParent: HTMLElement | null = element.parentElement
  let depth = 1
  while (nearestParent) {
    if (callback(nearestParent)) {
      break
    }
    depth += 1
    if (depth >= maxDepth) {
      throw new Error('The max depth has reached')
    }
    nearestParent = nearestParent.parentElement
  }
  return nearestParent
}
