export function removeAllImagesParentVerticalMargins(
  contentDocument: Document,
): void {
  const images = contentDocument.images
  if (!images) {
    return
  }

  for (let i = 0; i < images.length; i++) {
    const imgElement = images[i]
    removeImageParentVerticalMargins(imgElement)
  }
}

function removeImageParentVerticalMargins(
  imageElement: HTMLImageElement,
): void {
  let parentElement: HTMLElement | null = imageElement
  while (parentElement) {
    // set top and bottom margins to zero
    parentElement.style.marginTop = '0px'
    parentElement.style.marginBottom = '0px'
    parentElement = parentElement.parentElement
  }
}
