import {
  AsyncTaskRunner,
  AsyncTaskStore,
} from './async-tasks-storing-and-handling'
import {
  AsyncTaskDescription,
  AsyncTaskDescriptionStrict,
  AsyncTaskFabric,
  AsyncTaskId,
  AsyncQueue,
} from './types'
import {
  RunAsyncTaskInQueueParameters,
  AsyncQueueFabric,
  AsyncQueueFabricParameters,
} from './types/async-queue'

/**
 * Run async tasks one by one in FIFO sequence.
 * TODO - in future if it's necessary add concurrency support, cancellation token
 *
 * @export
 * @interface AsyncQueue
 */

export class AsyncQueueImpl implements AsyncQueue {
  /**
   * Indicates whether the queue has or doesn't
   * have any tasks postponed.
   *
   * @returns {boolean}
   * @memberof AsyncQueue
   */
  public get isEmpty(): boolean {
    const isPendingTasksStorageEmpty: boolean = this.asyncTaskStore.isEmpty
    const isTaskRunning = Boolean(this.queuedTaskRunningOrNull)
    return isPendingTasksStorageEmpty && !isTaskRunning
  }
  protected queuedTaskRunningOrNull: Promise<any> | null = null
  protected queuedTaskRunningDescriptionStrictOrNull: AsyncTaskDescriptionStrict<
    any
  > | null = null
  private readonly defaultTimeoutForTaskMs: number
  private readonly queueName: string
  private readonly asyncTaskStore: AsyncTaskStore
  private readonly asyncTaskRunner: AsyncTaskRunner
  private readonly useLogging: boolean
  constructor(parameters: AsyncQueueFabricParameters) {
    const {
      queueName,
      useLogging,
      defaultTimeoutForTaskMs,
      asyncTaskStore,
      asyncTaskRunner,
    } = parameters
    this.asyncTaskStore = asyncTaskStore
    this.asyncTaskRunner = asyncTaskRunner
    this.queueName = queueName
    this.defaultTimeoutForTaskMs = defaultTimeoutForTaskMs
    this.useLogging = useLogging
  }
  public runInQueue<R>(
    parameters: RunAsyncTaskInQueueParameters<R>,
  ): Promise<R> {
    const { taskFabric, taskName, taskTimeoutMs } = parameters
    const pendingTask = this.addIntoQueueAndWaitForTurn(
      taskFabric,
      taskName,
      taskTimeoutMs,
    )

    this.launchQueue()
    return pendingTask
  }

  public stop(): void {
    const error = new Error('The queue has been closed')
    this.asyncTaskRunner.rejectCurrentTask(error)
    this.rejectAndRemoveAllTasksInStore(error)
    this.unsetCurrentTask()
  }

  protected rejectAndRemoveTaskById(
    taskPendingId: AsyncTaskId,
    error: Error,
  ): void {
    this.asyncTaskStore.rejectAndRemoveTaskById(taskPendingId, error)
  }

  protected runTaskById(
    taskPendingId: AsyncTaskId,
    timeoutMs: number,
    beforeFinishCallback?: () => void,
  ): Promise<unknown> {
    return this.asyncTaskRunner.runTaskById(
      taskPendingId,
      timeoutMs,
      beforeFinishCallback,
    )
  }

  protected runTaskByIdAndUnsetRunningTaskBeforeFinish(
    taskPendingId: AsyncTaskId,
    timeoutMs: number,
  ): Promise<unknown> {
    return this.runTaskById(taskPendingId, timeoutMs, this.unsetCurrentTask)
  }

  protected rejectAndRemoveAllTasksInStore(error: Error): void {
    const asyncTaskStore = this.asyncTaskStore
    const tasksPendingIds: AsyncTaskId[] = asyncTaskStore.getAllStoredTasksIds()
    tasksPendingIds.forEach((taskPendingId) => {
      try {
        this.rejectAndRemoveTaskById(taskPendingId, error)
      } catch (err) {
        console.error(err)
      }
    })
  }

  protected addIntoQueueAndWaitForTurn<R>(
    taskFabric: AsyncTaskFabric<R>,
    taskName?: string,
    taskTimeoutMs?: number,
  ): Promise<R> {
    const promisePending = new Promise<R>((res, rej) => {
      const taskDescription: AsyncTaskDescription<R> = {
        fabric: taskFabric,
        name: taskName ?? '',
        timeoutMs: taskTimeoutMs,
        onResolve: res,
        onError: rej,
        timestampMs: Date.now(),
      }
      this.addTaskDescriptionIntoQueue(taskDescription)
    })
    return promisePending
  }

  protected addTaskDescriptionIntoQueue(
    taskDescription: AsyncTaskDescription<any>,
  ): void {
    this.asyncTaskStore.addTask(taskDescription)
  }

  protected launchQueue(): void {
    if (this.queuedTaskRunningOrNull) {
      return
    }
    this.runNextTaskInQueue()
  }

  protected setCurrentQueuedTaskRunning(task: Promise<any>): void {
    this.queuedTaskRunningOrNull = task
  }

  protected unsetCurrentQueuedTaskRunning(): void {
    this.queuedTaskRunningOrNull = null
  }

  protected setCurrentTaskRunningDescription(
    taskDescriptionStrict: AsyncTaskDescriptionStrict<any>,
  ): void {
    this.queuedTaskRunningDescriptionStrictOrNull = taskDescriptionStrict
  }

  protected unsetCurrentTaskRunningDescription(): void {
    this.queuedTaskRunningDescriptionStrictOrNull = null
  }

  protected setCurrentTaskRunning(
    task: Promise<any>,
    taskDescriptionStrict: AsyncTaskDescriptionStrict<any>,
  ): void {
    this.setCurrentQueuedTaskRunning(task)
    this.setCurrentTaskRunningDescription(taskDescriptionStrict)
  }

  protected async runTaskByDescription(
    taskDescription: AsyncTaskDescriptionStrict<any>,
  ): Promise<void> {
    const { name, timeoutMs, id } = taskDescription
    const taskName: string = name ?? ''
    const timeoutForTask: number = timeoutMs ?? this.defaultTimeoutForTaskMs
    try {
      const taskRunning: Promise<unknown> = this.runTaskByIdAndUnsetRunningTaskBeforeFinish(
        id,
        timeoutForTask,
      )
      this.printQueueState()
      this.printLogString(`runTaskByDescription:start:${taskName}`)
      this.setCurrentTaskRunning(taskRunning, taskDescription)
      await taskRunning
      this.printLogString(`runTaskByDescription:finish:${taskName}`)
    } catch (err) {
      if (err instanceof Error) {
        this.printLogString(
          `runTaskByDescription:error:${taskName}:${err.message}`,
        )
      }
    } finally {
      this.printLogString(`runTaskByDescription:next:${taskName}`)
      this.runNextTaskInQueue()
    }
  }

  protected getNextTaskDescriptionStrictOrNull(): AsyncTaskDescriptionStrict<
    any
  > | null {
    return this.asyncTaskStore.getNextTaskOrNullToRun()
  }

  protected runNextTaskInQueue(): Promise<void> {
    const nextTaskDescriptionOrNull: AsyncTaskDescriptionStrict<
      any
    > | null = this.getNextTaskDescriptionStrictOrNull()

    if (!nextTaskDescriptionOrNull) {
      this.printLogString('runNextTaskInQueue:empty')
      this.unsetCurrentTask()
      return Promise.resolve()
    }
    return this.runTaskByDescription(nextTaskDescriptionOrNull)
  }

  protected printLogString(logString: string): void {
    if (!this.useLogging) {
      return
    }
    // eslint-disable-next-line no-console
    console.log(`${this.queueName}::${logString}`)
  }

  protected printQueueState() {
    if (!this.useLogging) {
      return
    }
    this.asyncTaskStore.logStateInConsole(this.queueName)
  }

  private unsetCurrentTask = (): void => {
    this.unsetCurrentQueuedTaskRunning()
    this.unsetCurrentTaskRunningDescription()
  }
}

export const asyncQueueFabric: AsyncQueueFabric = (
  parameters: AsyncQueueFabricParameters,
): AsyncQueue => {
  const asyncQueue: AsyncQueue = new AsyncQueueImpl(parameters)
  return asyncQueue
}
