import { Rect } from '../cfi/rect'
import { ViewSettings } from '../view-settings'
import { SettingName, SpreadLocation } from '../types'

import { R2ContentView } from './r2-content-view'
import * as DomUtils from './dom-utils'
import { GetCfiOptions } from './content-view'

type Size = [number, number]

export class R2SinglePageContentView extends R2ContentView {
  private spreadLocation: SpreadLocation
  private iframeScaler: HTMLElement

  private ePubSvg: SVGElement | null = null
  private ePubRoot: SVGElement | HTMLElement | null = null

  private metaSize: Size = [0, 0]
  private metaScale = 1

  private isVertical = false
  private isFixedLayout = true

  public applySpreadLocation(spreadLocation: SpreadLocation): void {
    this.spreadLocation = spreadLocation

    const borderColor = this.vs.getSetting(SettingName.BorderColor)
    if (borderColor === undefined) {
      this.iframeContainer.style.border = ''
      return
    }

    if (this.spreadLocation === SpreadLocation.Left) {
      this.iframeContainer.style.borderLeft = `${borderColor} solid 1px`
    } else if (this.spreadLocation === SpreadLocation.Right) {
      this.iframeContainer.style.borderRight = `${borderColor} solid 1px`
    } else if (this.spreadLocation === SpreadLocation.Center) {
      this.iframeContainer.style.borderLeft = `${borderColor} solid 1px`
      this.iframeContainer.style.borderRight = `${borderColor} solid 1px`
    } else {
      this.iframeContainer.style.border = ''
    }
  }

  public setLayout(isVert: boolean, isFxl: boolean): void {
    this.isVertical = isVert
    this.isFixedLayout = isFxl
  }

  public element(): HTMLElement {
    return this.iframeContainer
  }

  public metaWidth(): number {
    return this.metaSize[0]
  }

  public metaHeight(): number {
    return this.metaSize[1]
  }

  public calculatedHeight(): number {
    return DomUtils.height(this.iframeContainer)
  }

  public render(): void {
    this.iframeContainer = document.createElement('div')
    this.applySpreadLocation(this.spreadLocation)
    this.iframeScaler = document.createElement('div')
    this.iframe = document.createElement('iframe')

    this.iframeContainer.appendChild(this.iframeScaler)
    this.iframeScaler.appendChild(this.iframe)

    this.host.appendChild(this.iframeContainer)

    this.setupIframe()

    this.useReadiumCss = !this.isFixedLayout
    this.useCssOverride = true
  }

  public setViewSettings(viewSetting: ViewSettings): void {
    super.setViewSettings(viewSetting)
    this.onResize()
  }

  public getOffsetFromCfi(cfi: string): number {
    const offset = this.cfiNavLogic.getOffsetByCfi(cfi)
    if (offset === null) {
      return -1
    }

    return this.isVertical ? offset[1] : offset[0]
  }

  public getOffsetFromElementId(cfi: string): number {
    const offset = this.cfiNavLogic.getOffsetFromElementId(cfi)
    if (offset === null) {
      return -1
    }

    return this.isVertical ? offset[1] : offset[0]
  }

  public getPageIndexOffsetFromCfi(_cfi: string): number {
    return 0
  }

  public getPageIndexOffsetFromElementId(_elementId: string): number {
    return 0
  }

  public getOffsetFromCharOffset(charOffset: number): number {
    const offset = this.charOffsetNavLogic.getOffsetByCharOffset(charOffset)
    if (offset === null) {
      return -1
    }

    return this.isVertical ? offset[1] : offset[0]
  }

  public getPageIndexOffsetFromCharOffset(_charOffset: number): number {
    return 0
  }

  public getContentViewVerticalOffset(): number {
    return this.iframeContainer.offsetTop
  }

  public getCfi(
    offsetMain: number,
    offset2nd: number,
    backward: boolean,
    options?: GetCfiOptions,
  ): string {
    // set options
    const recalcLeftBasedOnDirection =
      options?.recalcLeftBasedOnDirection === undefined
        ? true
        : options.recalcLeftBasedOnDirection

    const isScaleNeeded =
      options?.isScaleNeeded === undefined ? true : options.isScaleNeeded

    let left: number
    let top: number
    let right: number
    let bottom: number
    if (this.isVertical) {
      const size: [number, number] | null = this.getHostSize()
      left = offset2nd
      top = offsetMain
      if (recalcLeftBasedOnDirection && backward && size) {
        // Adjust the visible rect section defined using top
        top -= size[1]
      }

      right = left
      bottom = top
      if (size) {
        right += size[0]
        bottom += size[1]
      }
    } else {
      left = offsetMain
      top = offset2nd

      const metaWidth = isScaleNeeded
        ? this.metaWidth() * this.metaScale
        : this.metaWidth()

      const metaHeight = isScaleNeeded
        ? this.metaHeight() * this.metaScale
        : this.metaHeight()

      if (recalcLeftBasedOnDirection && backward) {
        left -= metaWidth
      }

      right = left + metaWidth
      bottom = top + metaHeight
    }

    const cfi = this.cfiNavLogic.getFirstVisibleCfi(
      new Rect(left, top, right, bottom),
      backward,
    )

    return cfi ? cfi : ''
  }

  public scale(scale: number): void {
    this.transform(scale, 0, 0)
  }

  public spineItemPageCount(): number {
    return 1
  }

  public onResize(): void {
    // fxl page has different logic for page height
    if (this.isFixedLayout) {
      return
    }

    const contHeight = this.contentDocHeight()
    if (contHeight > 0) {
      this.setHeight(contHeight)
    }
  }

  private preventDefault(e: Event) {
    e.preventDefault()
  }

  protected onIframeLoaded(success: boolean): void {
    const epubContentDocument = this.iframe.contentDocument
    if (epubContentDocument) {
      epubContentDocument.addEventListener(
        'wheel',
        function (event) {
          // prevent pinch zooming whole website on macOS chrome
          if (event.ctrlKey) {
            event.preventDefault()
          }
        },
        { passive: false },
      )

      // prevents pinch zooming whole website on macOS safari
      epubContentDocument.addEventListener('gesturestart', this.preventDefault)
      epubContentDocument.addEventListener('gesturechange', this.preventDefault)
      epubContentDocument.addEventListener('gestureend', this.preventDefault)
      epubContentDocument.addEventListener('contextmenu', this.preventDefault)

      // prevent default browser action for assistive selection shortcut
      epubContentDocument.addEventListener('keydown', function (
        e: KeyboardEvent,
      ) {
        if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
          e.preventDefault()
        }
      })

      this.ePubHtml = epubContentDocument.querySelector('html')
      if (!this.ePubHtml) {
        this.ePubSvg = epubContentDocument.querySelector('svg')
      } else {
        this.ePubHtml.style.touchAction = 'pan-x pan-y'
        this.ePubBody = this.ePubHtml.querySelector('body')
        if (this.ePubBody) {
          this.ePubBody.style.touchAction = 'pan-x pan-y'
        }
      }
    }
    this.ePubRoot = this.ePubHtml || this.ePubSvg

    this.updateMetaSize()

    this.setViewSettings(this.vs)

    super.onIframeLoaded(success)

    if (!this.isFixedLayout) {
      this.showIFrame()
    }
  }

  private contentDocHeight(): number {
    const win = this.iframe.contentWindow
    const doc = this.iframe.contentDocument

    if (win && doc && doc.documentElement) {
      return Math.round(DomUtils.height(doc.documentElement, win))
    }

    if (this.ePubRoot) {
      console.error('getContentDocHeight ??')

      return DomUtils.height(this.ePubRoot)
    }

    return 0
  }

  private setHeight(h: number): void {
    DomUtils.setHeight(this.iframeScaler, h)
    DomUtils.setHeight(this.iframeContainer, h)
  }

  private updateMetaSize(): void {
    const contentDocument = this.iframe.contentDocument
    if (!contentDocument) {
      return
    }

    let content
    const viewport = contentDocument.querySelector('meta[name=viewport]')
    if (viewport) {
      content = viewport.getAttribute('content')
    }

    if (!content) {
      const viewbox = contentDocument.querySelector('meta[name=viewbox]')
      if (viewbox) {
        content = viewbox.getAttribute('content')
      }
    }

    let size: Size | undefined
    if (content) {
      size = this.parseMetaSize(content)
    }

    if (!size) {
      size = this.parseSvgSize(contentDocument)
    }

    if (size !== undefined) {
      this.metaSize = size
    }
  }

  private parseMetaSize(content: string): Size | undefined {
    const pairs = content.replace(/\s/g, '').split(',')

    let width = Number.NaN
    let height = Number.NaN

    for (const pair of pairs) {
      const nameVal = pair.split('=')
      if (nameVal.length === 2) {
        if (nameVal[0] === 'width') {
          width = parseInt(nameVal[1], 10)
        }
        if (nameVal[0] === 'height') {
          height = parseInt(nameVal[1], 10)
        }
      }
    }

    if (!isNaN(width) && !isNaN(height)) {
      return [width, height]
    }

    return undefined
  }

  private parseSvgSize(contentDoc: Document): Size | undefined {
    const docElement = contentDoc.documentElement
    if (
      !docElement ||
      !docElement.nodeName ||
      docElement.nodeName.toLowerCase() !== 'svg'
    ) {
      return undefined
    }

    let width: number | undefined
    const wAttr = docElement.getAttribute('width')
    const isWidthPercent =
      wAttr && wAttr.length >= 1 && wAttr[wAttr.length - 1] === '%'
    if (wAttr) {
      try {
        width = parseInt(wAttr, 10)
      } catch (err) {
        width = undefined
      }
    }

    if (width && isWidthPercent) {
      width = undefined
    }

    let height: number | undefined
    const hAttr = docElement.getAttribute('height')
    const isHeightPercent =
      hAttr && hAttr.length >= 1 && hAttr[hAttr.length - 1] === '%'
    if (hAttr) {
      try {
        height = parseInt(hAttr, 10)
      } catch (err) {
        height = undefined
      }
    }

    if (height && isHeightPercent) {
      height = undefined
    }

    if (width && height) {
      return [width, height]
    }

    return undefined
  }

  private transform(scale: number, left: number, top: number): void {
    this.metaScale = scale
    const elWidth = Math.ceil(this.metaWidth() * scale)
    // The scale should be adjusted since the width is rounded to ceiling,
    // otherwise gap could introduced between the iframe container
    // and scaler
    const appliedScale = elWidth / this.metaWidth()
    const elHeight = Math.floor(this.metaHeight() * appliedScale)

    this.iframeContainer.style.left = `${left}px`
    this.iframeContainer.style.top = `${top}px`
    this.iframeContainer.style.width = `${elWidth}px`
    this.iframeContainer.style.height = `${elHeight}px`

    const enable3D = false
    const needsFixedLayoutScalerWorkAround = false
    let scalerWidth = this.metaWidth()
    let scalerHeight = this.metaHeight()
    let scalerScale = appliedScale
    if (
      this.ePubBody && // not SVG spine item (otherwise fails in Safari OSX)
      needsFixedLayoutScalerWorkAround
    ) {
      // See https://github.com/readium/readium-shared-js/issues/285
      if (this.ePubRoot) {
        this.ePubRoot.style.transform = enable3D
          ? `scale3D(${appliedScale}, ${appliedScale}, 0)`
          : `scale(${appliedScale})`

        // this is to fix a rendering issue on microsoft edge
        // text looks pixelated after scaling viewport-clipper
        // not clear about the root cause or why this fixes it
        // something to do with nested divs that apply scaling values
        this.ePubRoot.style.transformStyle = 'preserve-3d'

        this.ePubRoot.style.minWidth = `${this.metaWidth()}px`
        this.ePubRoot.style.minHeight = `${this.metaHeight()}px`
      }

      if (this.ePubBody) {
        this.ePubBody.style.width = `${this.metaWidth()}px`
        this.ePubBody.style.height = `${this.metaHeight()}px`
      }

      scalerWidth *= appliedScale
      scalerHeight *= appliedScale
      scalerScale = 1
    }

    // translateZ(0) accelerates render performance to fix a render issue caused by scale
    const transString = enable3D
      ? `scale3D(${scalerScale}, ${scalerScale}, 0)`
      : `scale(${scalerScale}) translateZ(0)`
    this.iframeScaler.style.transform = transString
    this.iframeScaler.style.width = `${scalerWidth}px`
    this.iframeScaler.style.height = `${scalerHeight}px`
    this.iframeScaler.style.transformOrigin = enable3D
      ? '0px 0px 0px'
      : '0px 0px'

    // Chrome workaround: otherwise text is sometimes invisible
    // (probably a rendering glitch due to the 3D transform graphics backend?)
    // _$epubHtml.css("visibility", "hidden"); // "flashing" in two-page spread mode is annoying :(
    if (this.ePubRoot) {
      this.ePubRoot.style.opacity = '0.9999'
    }

    this.showIFrame()

    setTimeout(() => {
      if (this.ePubRoot) {
        this.ePubRoot.style.opacity = '1'
      }
    }, 0)
  }
}
