import type { InjectCSSAsync, InjectCSSParameters } from '../../navigator'

import { injectCSSByFileURLs } from './inject-css-by-file-urls'
import type { InjectCSSFilesByUrls } from './types'

/**
 * Fetch CSS files, create local URLs for them and add them to a spine iframe.
 *
 * @param {InjectCSSParameters} parameters
 * @return {Promise<void>}
 */
export const injectCssAsync: InjectCSSAsync = async function injectCssAsyncImpl(
  parameters: InjectCSSParameters,
  injectCSSByURL: InjectCSSFilesByUrls = injectCSSByFileURLs,
): Promise<void> {
  await injectCSSByURL(parameters)
}
