import { SpineItemView } from '..'
import { applyToStyleDeclaration } from '../../utils/css-rules'

import { PageLabelContentContainerOffsets } from './page-labels-renderer'
import type { CSSRules, WaitContentViewFitInIframeWindow } from './types'

export function getScrollTop(): number {
  return window.pageYOffset || document.documentElement.scrollTop
}

export function getWindowScrollLeft(): number {
  return window.pageXOffset || document.documentElement.scrollLeft
}

export function getContainerOffsetTopByRect(containerRect: DOMRect): number {
  return getScrollTop() + containerRect.top
}

export function getContainerOffsetLeftByRect(containerRect: DOMRect): number {
  return getWindowScrollLeft() + containerRect.left
}

export function getHTMLElementOffsets(
  htmlElement: HTMLElement,
): PageLabelContentContainerOffsets {
  const rect = htmlElement.getBoundingClientRect()
  const offsetTop = getContainerOffsetTopByRect(rect)
  const offsetLeft = getContainerOffsetLeftByRect(rect)
  return {
    top: offsetTop,
    left: offsetLeft,
  }
}

const StyleForNonInteractiveElement: CSSRules = {
  pointerEvents: 'none',
  userSelect: 'none',
  touchAction: 'none',
  background: 'none',
}

export function applyCssRulesToNonInteractiveElementStyle(
  htmlElementStyle: CSSStyleDeclaration,
) {
  applyToStyleDeclaration(htmlElementStyle, StyleForNonInteractiveElement)
}

export const waitContentViewFitInIframeWindowOrTimeout: WaitContentViewFitInIframeWindow = (
  spineItemView: SpineItemView,
  timeoutMs = 3000,
): Promise<void> => {
  let timeout: number
  const onResizePending = new Promise<void>((res) => {
    spineItemView.onSelfResizeOnce(() => {
      clearTimeout(timeout)
      res()
    })
  })
  const timeoutPending = new Promise<void>((res) => {
    timeout = setTimeout(res, timeoutMs)
  })
  return Promise.race([onResizePending, timeoutPending])
}
