import {
  injectCssAsync,
  getReadiumCSSAssetUrls,
  applyResourcesToDocument,
  WaitImagesDimensionsImpl,
} from '../../utils'
import { getFlowpubCSSAssetUrls } from '../../utils/get-css-asset-urls'
import { ContentType } from '../content-loader'
import type { ContentLoader } from '../content-loader'
import type {
  SpineDocumentLoadingInterceptor,
  XHTMLParser,
  XHTMLParserSupportedType,
  ReadiumCSSAssetUrls,
  Resource,
} from '../types'

import { crossoriginProcessor } from './crossorigin-processor'
import type {
  InjectCSSParameters,
  InjectCSSAsync,
  ApplyResourcesToDocument,
  ApplyResourcesToDocumentAsync,
  IFrameContentInjector,
  IFrameDocumentPostProcessor,
  IframeLoaderConfig,
  IFrameLoaderDependencies,
  LoaderCssConfig,
  R1AttachedDataType,
  WaitImagesDimensions,
} from './types'

export class IFrameLoader implements ContentLoader {
  private publicationURI?: string

  private isIE: boolean
  private useSrcdoc = false

  private cssBasePath?: string
  private loaderEvents: { [eventName: string]: Function[] } = {}
  private injectableResources: Resource[]

  private loaderConfig: IframeLoaderConfig
  private xhtmlParser: XHTMLParser = new DOMParser()

  private readonly waitImagesDimensions: WaitImagesDimensions =
    new WaitImagesDimensionsImpl()

  /**
   * Injects HTML code into the IFrame document
   *
   * @private
   * @type {IFrameContentInjector}
   * @memberof IFrameLoader
   */
  private readonly iframeContentInjector?: IFrameContentInjector
  /**
   * Can process the iframe document right before the iframe is ready to be displayed
   * on the page.
   *
   * @private
   * @type {IFrameDocumentPostProcessor}
   * @memberof IFrameLoader
   */
  private readonly iframeDocumentPostProcessor?: IFrameDocumentPostProcessor
  /**
   * If set this intsance will be responsible for the fetching and
   * processing of the HTML content of a spine item.
   *
   * @private
   * @type {SpineDocumentLoadingInterceptor}
   * @memberof IFrameLoader
   */
  private spineDocumentLoadingInterceptor?: SpineDocumentLoadingInterceptor

  /**
   * This is used to inject JS/CSS bundles into an spine item IFrame document.
   *
   * @private
   * @type {ApplyResourcesToDocumentAsync}
   * @memberof IFrameLoader
   */
  private applyResourcesToIframeDocument:
    | ApplyResourcesToDocument
    | ApplyResourcesToDocumentAsync = applyResourcesToDocument

  /**
   * Inject CSS to spine iframe html.
   *
   * @private
   * @type {InjectCSSAsync}
   * @memberof IFrameLoader
   */
  private injectCSS: InjectCSSAsync = injectCssAsync

  constructor(
    publicationURI?: string,
    dependencies: IFrameLoaderDependencies = {},
  ) {
    const {
      waitImagesDimensions,
      iframeContentInjector,
      iframeDocumentPostProcessor,
      xhtmlParser,
      applyResourcesToIframeDocument,
      injectCSS,
    }: IFrameLoaderDependencies = dependencies

    this.publicationURI = publicationURI
    this.isIE =
      window.navigator.userAgent.indexOf('Trident') > 0 ||
      window.navigator.userAgent.indexOf('Edge') > 0
    this.iframeContentInjector = iframeContentInjector
    this.iframeDocumentPostProcessor = iframeDocumentPostProcessor
    if (xhtmlParser) {
      this.xhtmlParser = xhtmlParser
    }
    if (waitImagesDimensions) {
      this.waitImagesDimensions = waitImagesDimensions
    }
    if (applyResourcesToIframeDocument) {
      this.applyResourcesToIframeDocument = applyResourcesToIframeDocument
    }
    if (injectCSS) {
      this.injectCSS = injectCSS
    }
  }

  public setCssBasePath(path: string): void {
    this.cssBasePath = path
  }

  public enableUseSrcdoc(): void {
    this.useSrcdoc = true
  }

  public addContentLoadedListener(listener: Function): void {
    const eventName = 'iframeLoaded'
    this.addListener(eventName, listener)
  }

  public addContentUnloadedListener(listener: Function): void {
    const eventName = 'iframeUnloaded'
    this.addListener(eventName, listener)
  }

  public contentType(): ContentType {
    return ContentType.Html
  }

  public setConfig(config: IframeLoaderConfig): void {
    this.loaderConfig = config
  }

  /**
   * Set an interceptor loading of XHTML contentent of a spine item
   *
   * @param {SpineDocumentLoadingInterceptor} spineDocumentLoadingInterceptor
   * @memberof IFrameLoader
   */
  public setSpineDocumentLoadingInterceptor(
    spineDocumentLoadingInterceptor?: SpineDocumentLoadingInterceptor,
  ): void {
    this.spineDocumentLoadingInterceptor = spineDocumentLoadingInterceptor
  }

  public loadContent(
    spintItemIndex: number,
    iframe: HTMLIFrameElement,
    src: string,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/explicit-module-boundary-types
    callback: any,
    attachedData: string | R1AttachedDataType,
  ): void {
    const baseURI =
      this.publicationURI ??
      (iframe.baseURI || document.baseURI || location.href)
    iframe.setAttribute('data-baseUri', baseURI)
    iframe.setAttribute('data-src', src)

    const contentUri = new URL(src, baseURI).toString()

    let contentType = 'text/html'

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    if ((attachedData as any).spineItem !== undefined) {
      const data = attachedData as R1AttachedDataType
      if (data.spineItem.media_type?.length) {
        contentType = data.spineItem.media_type
      }
    } else {
      contentType = attachedData as string
    }

    this.fetchContentDocument(contentUri).then(
      (contentData: string | Document) => {
        return this.loadIframeWithDocument(
          spintItemIndex,
          iframe,
          contentUri,
          contentData,
          contentType,
          callback,
        )
      },
    )
  }

  public unloadContent(spineItemIndex: number): void {
    this.iframeUnloaded(spineItemIndex)
  }

  private addListener(eventName: string, callback: Function): void {
    const events = this.loaderEvents[eventName] || []
    events.push(callback)

    this.loaderEvents[eventName] = events
  }

  private async fetchContentDocument(src: string): Promise<string | Document> {
    const spineDocumentLoadingInterceptor = this.spineDocumentLoadingInterceptor
    if (spineDocumentLoadingInterceptor) {
      return spineDocumentLoadingInterceptor.fetch({
        spineXHTMLUrl: src,
        xhtmlParser: this.xhtmlParser,
      })
    }
    return this.fetchContentDocumentInternal(src)
  }

  private async fetchContentDocumentInternal(src: string): Promise<string> {
    const resp = await fetch(src)

    return resp.text()
  }

  public registerInjectableResources(resources: Resource[]): void {
    this.injectableResources = resources
  }

  private async inject(
    sourceTextOrDocument: string | Document,
    contentType: string,
    href: string,
    loaderCssConfig: LoaderCssConfig,
  ): Promise<string> {
    const doc: Document =
      typeof sourceTextOrDocument === 'string'
        ? this.xhtmlParser.parseFromString(
            sourceTextOrDocument,
            contentType as XHTMLParserSupportedType,
          )
        : sourceTextOrDocument
    const headElement = doc.querySelector('head')
    if (!doc.documentElement || !headElement) {
      // No head element.. not a valid (X)HTML document?
      // Then just return the original source
      return typeof sourceTextOrDocument === 'string'
        ? sourceTextOrDocument
        : this.getDocumentSourceText(doc, contentType)
    }

    crossoriginProcessor(doc)

    this.injectBaseHref(doc, headElement, href)

    const { useReadiumCss, useCssOverride } = loaderCssConfig
    await this.injectCSSFiles(
      doc,
      Boolean(useReadiumCss),
      Boolean(useCssOverride),
    )

    await this.applyResourcesToIframeDocument(this.injectableResources, doc)
    return this.getDocumentSourceText(doc, contentType)
  }

  protected async injectCSSFiles(
    document: Document,
    useReadiumCss: boolean,
    useOverride: boolean,
  ): Promise<void> {
    if (!this.cssBasePath) {
      return
    }

    const readiumCssAssetUrlsOrUndefined: ReadiumCSSAssetUrls | undefined =
      useReadiumCss ? getReadiumCSSAssetUrls(this.cssBasePath) : undefined

    const overrideCssUrlOrUndefined: string | undefined = useOverride
      ? getFlowpubCSSAssetUrls(this.cssBasePath).fixedLayoutCssUrl
      : undefined

    const params: InjectCSSParameters = {
      document,
      readiumCssAssetUrlsOrUndefined,
      overrideCssUrlOrUndefined,
      applyResourcesToIframeDocument: this.applyResourcesToIframeDocument,
    }
    await this.injectCSS(params)
  }

  private getDocumentSourceText(doc: Document, contentType: string): string {
    if (contentType.includes('xml')) {
      return new XMLSerializer().serializeToString(doc)
    }

    if (!doc.documentElement) {
      return ''
    }

    return doc.documentElement.outerHTML
  }

  private injectBaseHref(
    doc: Document,
    headEle: HTMLHeadElement,
    href: string,
  ): void {
    const baseElement = doc.createElement('base')
    baseElement.setAttribute('href', href)

    headEle.insertBefore(baseElement, headEle.firstChild)
  }

  private iframeLoaded(
    spintItemIndex: number,
    iframe: HTMLIFrameElement,
  ): void {
    const eventCbs = this.loaderEvents.iframeLoaded
    if (!eventCbs) return

    eventCbs.forEach((eventCb) => eventCb(spintItemIndex, iframe))
  }

  private iframeUnloaded(spineItemIndex: number): void {
    const eventCbs = this.loaderEvents.iframeUnloaded
    if (!eventCbs) return

    eventCbs.forEach((eventCb) => eventCb(spineItemIndex))
  }

  private async loadIframeWithDocument(
    spintItemIndex: number,
    iframe: HTMLIFrameElement,
    contentDocumentURI: string,
    contentDocumentData: string | Document,
    contentType: string,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    callback: any,
  ): Promise<void> {
    try {
      const injectWithIFrameContentInjector = Boolean(
        this.iframeContentInjector,
      )
      const iframeContentURL = new URL(
        contentDocumentURI,
        iframe.baseURI || document.baseURI || location.href,
      ).href
      const iframeHTMLSourceCodeWithInjectedStylesAndJS: string =
        await this.inject(
          contentDocumentData,
          contentType,
          iframeContentURL,
          this.loaderConfig,
        )

      if (typeof contentDocumentData === 'object') {
        // release memory by cleaning up the DOM tree
        contentDocumentData.documentElement.remove()
      }
      if (injectWithIFrameContentInjector && this.iframeContentInjector) {
        await this.iframeContentInjector({
          documentContent: iframeHTMLSourceCodeWithInjectedStylesAndJS,
          documentMIMEType: contentType,
          documentUrl: iframeContentURL,
          iframe,
        })
      } else {
        this.injectIFrameContentDefault(
          iframe,
          iframeHTMLSourceCodeWithInjectedStylesAndJS,
          contentType,
        )
      }

      // wait till the script will update the iframe inner HTML code
      // and parse it
      await new Promise<unknown>((res) =>
        iframe.addEventListener('load', res, { once: true }),
      )

      const iframeDocumentOrUndefined = iframe.contentWindow?.document
      if (iframeDocumentOrUndefined) {
        try {
          // the main window might throw an exception if iframe does not share
          // the same domain (according to CORS policy)
          await this.waitImagesDimensions.waitAllImagesHaveDimension(
            Array.from(iframeDocumentOrUndefined?.images),
          )
        } catch (err) {
          console.error(err)
        }
        await this.iframeDocumentPostProcessor?.({
          document: iframeDocumentOrUndefined,
        })
      }
      this.iframeLoaded(spintItemIndex, iframe)
      callback(true)
    } catch (err) {
      console.error(err)
      callback(false)
      throw err
    }
  }

  // TODO - CYP-1135 refactor this to make "injectIFrameContentDefault" an external dependency
  // provided in the constructor parameters
  protected injectIFrameContentDefault(
    iframe: HTMLIFrameElement,
    basedContentData: string,
    contentType: string,
  ): void {
    let documentDataUri = ''
    if (this.useSrcdoc) {
      iframe.setAttribute('srcdoc', basedContentData)
    } else if (!this.isIE) {
      documentDataUri = window.URL.createObjectURL(
        new Blob([basedContentData], { type: contentType }),
      )
    } else if (iframe.contentWindow) {
      // Internet Explorer doesn't handle loading documents from Blobs correctly.
      // Currently using the document.write() approach only for IE, as it breaks CSS selectors
      // with namespaces for some reason (e.g. the childrens-media-query sample EPUB)
      iframe.contentWindow.document.open()

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const MSApp = (window as any).MSApp

      // Currently not handled automatically by winstore-jscompat,
      // so we're doing it manually. See:
      // https://github.com/MSOpenTech/winstore-jscompat/

      if (MSApp?.execUnsafeLocalFunction) {
        // tslint:disable-next-line:no-disable-auto-sanitization
        MSApp.execUnsafeLocalFunction(() => {
          if (iframe.contentWindow) {
            iframe.contentWindow.document.write(basedContentData)
          }
        })
      } else {
        iframe.contentWindow.document.write(basedContentData)
      }
    }

    if (this.useSrcdoc) {
      // intentionally blank
    } else if (!this.isIE) {
      iframe.setAttribute('src', documentDataUri)
    } else if (iframe.contentWindow) {
      iframe.contentWindow.document.close()
    }
  }
}
