import { Caller } from '@flowpub/glue-rpc'
import { Callback } from '@flowpub/glue-shared'
import {
  ContentEventListenerContext,
  ContentEventManager,
  ContentEventSource,
} from '@flowpub/renderer'

import type { SelectionData } from './types'

export const SelectionChangingMessageAddListener =
  'ADD_SELECTION_CHANGING_LISTENER'
export const SelectionChangeMessageRemoveListener =
  'REMOVE_SELECTION_CHANGE_LISTENER'

class SelectionHandling extends Caller {
  public async addSelectionChangeListener(listener: Callback): Promise<number> {
    return this.call(SelectionChangingMessageAddListener, [], listener)
  }

  public async removeEventListener(listenerID: number): Promise<void> {
    return this.call(SelectionChangeMessageRemoveListener, [listenerID])
  }
}

export type SelectionEventListener = (
  index: number,
  data: SelectionData | null,
) => void

interface SelectionEventListenerContext extends ContentEventListenerContext {
  callback: SelectionEventListener
}

class SelectionChangingEventSource implements ContentEventSource {
  public spineItemIndex = -1

  private eventSource: SelectionHandling

  public constructor(win: Window) {
    this.eventSource = new SelectionHandling('selection-handling', win)
  }

  public async addListener(
    listener: SelectionEventListenerContext,
  ): Promise<number> {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const eventSourceCallback = (result: any[]): void => {
      listener.callback(this.spineItemIndex, result[0])
    }
    return await this.eventSource.addSelectionChangeListener(
      eventSourceCallback,
    )
  }

  public async removeListener(
    listener: SelectionEventListenerContext,
  ): Promise<void> {
    const listenerID = listener.listenerIDs[this.spineItemIndex]
    await this.eventSource.removeEventListener(listenerID)
  }
}

export class SelectionChangingEventManager extends ContentEventManager {
  public makeEventSource(win: Window): ContentEventSource {
    return new SelectionChangingEventSource(win)
  }

  public addSelectionChangingListener(callback: SelectionEventListener): void {
    const newListener: SelectionEventListenerContext = {
      callback,
      listenerIDs: {},
      removed: false,
    }

    this.eventListeners.push(newListener)
  }
}
