// tslint:disable-next-line: import-name
import { Link } from '@flowpub/webpub-model'

import { ContentLoader } from '../../content-loader'
import { CfiNavigationLogic } from '../cfi/cfi-navigation-logic'
import { CharOffsetNavigationLogic } from '../cfi/char-offset-navigation-logic'
import { ElementBlacklistedChecker } from '../cfi/element-checker'
import { CancellationToken, SpreadLocation } from '../types'
import { ViewSettings } from '../view-settings'

import { getAllPrecedingElements, getIdsFromElements } from './dom-utils'
import { GetCfiOptions, IContentView, SelfResizeCallback } from './content-view'
import {
  ContentViewResizeSensor,
  ContentViewResizeSensorConstructorParameters,
  ContentViewResizeSensorImpl,
} from './content-view-resize-sensor'

type IframeLoadedCallback = (success: boolean) => void

export class R2ContentView implements IContentView {
  protected host: HTMLElement

  protected contentLoader: ContentLoader

  protected iframeContainer: HTMLElement
  protected iframe: HTMLIFrameElement

  protected iframeLoadedCallbacks: IframeLoadedCallback[] = []
  protected selfResizeCallbacks: SelfResizeCallback[] = []

  protected spineItem: Link
  protected spineItemIndex: number
  protected spineItemPgCount = 1

  protected ePubHtml: HTMLHtmlElement | null = null
  protected ePubBody: HTMLBodyElement | null = null

  protected useReadiumCss = true
  protected useCssOverride = false
  protected vs: ViewSettings

  protected elementChecker: ElementBlacklistedChecker
  protected cfiNavLogic: CfiNavigationLogic
  protected charOffsetNavLogic: CharOffsetNavigationLogic

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  protected resizeSensor: ContentViewResizeSensor | null = null

  protected callShowFrameOnFirstResize = false

  public constructor(
    loader: ContentLoader,
    eleChecker: ElementBlacklistedChecker,
  ) {
    this.contentLoader = loader
    this.elementChecker = eleChecker
  }

  public render(): void {
    throw new Error('Method not implemented.')
  }

  public loadSpineItem(
    spineItem: Link,
    spineItemIndex: number,
    viewSettings: ViewSettings,
    _token?: CancellationToken | undefined,
  ): Promise<void> {
    this.spineItem = spineItem
    this.spineItemIndex = spineItemIndex
    this.vs = viewSettings

    this.render()

    this.hideIframe()

    const onIframeContentLoaded = (success: boolean): void => {
      this.onIframeLoaded(success)
    }

    const loaderConfig = {
      useReadiumCss: this.useReadiumCss,
      useCssOverride: this.useCssOverride,
    }

    this.contentLoader.setConfig(loaderConfig)

    this.contentLoader.loadContent(
      spineItemIndex,
      this.iframe,
      spineItem.href,
      onIframeContentLoaded,
      spineItem.type,
    )

    return this.iframeLoadedPromise()
  }

  public applySpreadLocation(_spreadLocation: SpreadLocation): void {
    // do nothing
  }

  public getSpineItem(): Link {
    return this.spineItem
  }

  public spineItemLoadedPromise(
    _token?: CancellationToken | undefined,
  ): Promise<void> {
    return this.iframeLoadedPromise()
  }

  public unloadSpineItem(): void {
    this.selfResizeCallbacks = []
    if (this.resizeSensor) {
      this.resizeSensor.detach()
    }
    // check if the element has not been detached and still exists in the DOM
    if (this.iframeContainer.isConnected) {
      this.host.removeChild(this.iframeContainer)
    }
    this.contentLoader.unloadContent(this.spineItemIndex)
  }

  public attachToHost(host: HTMLElement): void {
    this.host = host
  }

  public setViewSettings(viewSetting: ViewSettings): void {
    if (!this.ePubHtml) {
      return
    }

    viewSetting.updateView(this.ePubHtml)
  }

  public scale(_scale: number): void {
    throw new Error('Method not implemented.')
  }

  public element(): HTMLElement {
    return this.iframeContainer
  }

  public metaWidth(): number {
    throw new Error('Method not implemented.')
  }

  public metaHeight(): number {
    throw new Error('Method not implemented.')
  }

  public calculatedHeight(): number {
    return 0
  }

  public spineItemPageCount(): number {
    return this.spineItemPgCount
  }

  public getOffsetFromCfi(_cfi: string): number {
    throw new Error('Method not implemented.')
  }

  public getOffsetFromElementId(_cfi: string): number {
    throw new Error('Method not implemented.')
  }

  public getPageIndexOffsetFromCfi(_cfi: string): number {
    throw new Error('Method not implemented.')
  }

  public getPageIndexOffsetFromElementId(_elementId: string): number {
    throw new Error('Method not implemented.')
  }

  public getOffsetFromCharOffset(_charOffset: number): number {
    throw new Error('Method not implemented.')
  }

  public getPageIndexOffsetFromCharOffset(_charOffset: number): number {
    throw new Error('Method not implemented.')
  }

  public getContentViewVerticalOffset(): number {
    throw new Error('Method not implemented.')
  }

  public getCfi(
    _offsetMain: number,
    _offset2nd: number,
    _backward: boolean,
    _options?: GetCfiOptions,
  ): string {
    throw new Error('Method not implemented.')
  }

  public getCfiFromElementId(elementId: string): string {
    const cfi = this.cfiNavLogic.getCfiFromElementId(elementId)
    return cfi === null ? '' : cfi
  }

  public getFragments(cfi: string): string[] {
    const element = this.getElementByCfi(cfi)
    const contextDocument = element?.ownerDocument

    if (!element || !contextDocument) {
      return []
    }

    let root = contextDocument.body
    if (!root) {
      root = contextDocument.documentElement
    }

    return getIdsFromElements(getAllPrecedingElements(root, element))
  }

  public getElementById(elementId: string): HTMLElement | null {
    return this.cfiNavLogic.getElementById(elementId)
  }

  public getElementByCfi(cfi: string): HTMLElement | null {
    return this.cfiNavLogic.getElementByCfi(cfi)
  }

  public onResize(): void {
    return
  }

  public onSelfResize(callback: SelfResizeCallback): void {
    this.selfResizeCallbacks.push(callback)
  }

  public removeOnSelfResizeListener(callback: SelfResizeCallback): void {
    this.selfResizeCallbacks = this.selfResizeCallbacks.filter(
      (cb) => cb !== callback,
    )
  }

  public onSelfResizeOnce(callback: SelfResizeCallback): void {
    this.onSelfResize((spineItemIndex: number): void => {
      this.removeOnSelfResizeListener(callback)
      callback(spineItemIndex)
    })
  }

  protected setupIframe(): void {
    this.iframeContainer.style.transform = 'none'
    this.iframe.width = '100%'
    this.iframe.height = '100%'
    this.iframe.style.border = '0px'
    this.iframe.tabIndex = -1
  }

  protected hideIframe(): void {
    this.iframe.style.visibility = 'hidden'
    this.iframe.style.pointerEvents = 'none'
  }

  protected showIFrame(): void {
    this.iframe.style.left = '0px'
    this.iframe.style.top = '0px'
    this.callShowFrameOnFirstResize = true
  }

  protected setStyleVisible() {
    this.iframe.style.visibility = 'visible'
    this.iframe.style.pointerEvents = 'auto'
  }

  protected iframeLoadedPromise(_token?: CancellationToken): Promise<void> {
    return new Promise<void>((resolve: () => void) => {
      const listener = (_success: boolean): void => {
        resolve()
      }

      this.iframeLoadedCallbacks.push(listener)
    })
  }

  protected getContentDocument(): Document {
    return this.iframe.contentDocument as Document
  }

  protected onIframeLoaded(success: boolean): void {
    // CYP-415: We disable the default copy functionality here as it now gets handled via the Context Menu
    if (this.ePubBody) {
      this.ePubBody.oncopy = function () {
        return false
      }
      this.ePubBody.oncut = function () {
        return false
      }
    }

    for (const callback of this.iframeLoadedCallbacks) {
      callback(success)
    }
    this.iframeLoadedCallbacks = []

    const doc = this.getContentDocument()
    this.cfiNavLogic = new CfiNavigationLogic(doc, this.elementChecker)
    this.charOffsetNavLogic = new CharOffsetNavigationLogic(
      doc,
      this.elementChecker,
    )
    this.resizeSensor = this.createAndReturnContentViewResizeSensor()
  }

  protected createAndReturnContentViewResizeSensor(): ContentViewResizeSensor {
    const doc = this.getContentDocument()
    const parameters: ContentViewResizeSensorConstructorParameters = {
      element: doc.body,
      callbackOnEachResize: this.onDocumentBodyResize,
      callbackOnFirstResize: this.onDocumentBodyResizeFirstTime,
    }
    const resizeSensor = new ContentViewResizeSensorImpl(parameters)

    this.resizeSensor = resizeSensor
    return resizeSensor
  }

  protected getHostSize(): [number, number] | null {
    if (!this.host.style.width || !this.host.style.height) {
      return null
    }

    const width = parseFloat(this.host.style.width)
    const height = parseFloat(this.host.style.height)

    return [width, height]
  }

  private onDocumentBodyResize = () => {
    this.onResize()
    for (const callback of this.selfResizeCallbacks) {
      callback(this.spineItemIndex)
    }
  }

  private onDocumentBodyResizeFirstTime = () => {
    if (this.callShowFrameOnFirstResize) {
      this.callShowFrameOnFirstResize = false
      this.setStyleVisible()
    }
  }
}
