import { ContentEventSource } from '@flowpub/renderer'

/**
 * Sometimes two event sources exist for the same spine item,
 * but the first one is not attached to spine item in the DOM
 * (it was unloaded previously), so we get the last one to ensure we have an
 * event source that is actually attached to a loaded spine item.
 *
 * @param spineItemIndex
 * @param eventSources
 */
export function getEventSourceForSpineItemOrNull<
  EventSourceType extends ContentEventSource
>(
  spineItemIndex: number,
  eventSources: [HTMLIFrameElement, ContentEventSource][],
): EventSourceType | null {
  let foundEventSource: EventSourceType | null = null

  for (const es of eventSources) {
    const eventSourceTemp = es[1] as EventSourceType
    if (eventSourceTemp.spineItemIndex === spineItemIndex) {
      foundEventSource = eventSourceTemp
    }
  }

  // return the LAST found matching event source
  return foundEventSource
}
