import { Caller } from '@flowpub/glue-rpc'
import { Callback } from '@flowpub/glue-shared'
import {
  ContentEventListenerContext,
  ContentEventManager,
  ContentEventSource,
} from '@flowpub/renderer'

import {
  Highlight,
  HighlightType,
  Location,
  SelectedHighlightInfo,
} from './types'
import { getEventSourceForSpineItemOrNull } from './utils/get-event-source-for-spine-item'

export const HighlightAddMessage = 'HIGHLIGHT_ADD'
export const HighlightRedrawMessage = 'HIGHLIGHT_REDRAW'
export const HighlightDeletionMessage = 'HIGHLIGHT_DELETION'
export const HighlightUpdateMessage = 'HIGHLIGHT_UPDATE'
export const HighlightVisibleRangeUpdateMessage =
  'HIGHLIGHT_VISIBLE_RANGE_UPDATE'
export const AddHighlightSelectedListenerMessage =
  'ADD_HIGHLIGHT_SELECTED_LISTENER'
export const RemoveHighlightSelectedListenerMessage =
  'REMOVE_HIGHLIGHT_SELECTED_LISTENER'
export const SetEphemeralHighlightDeletedCallbackMessage =
  'SET_EPHEMERAL_HIGHLIGHT_DELETE_CALLBACK'

class HighlightHandling extends Caller {
  public async deleteHighlight(id: string): Promise<void> {
    return this.call(HighlightDeletionMessage, [id])
  }

  public async addHighlight(
    id: string,
    type: HighlightType,
    start: string | number,
    end: string | number,
    color: string,
    duration = 0,
  ): Promise<void> {
    return this.call(HighlightAddMessage, [
      id,
      type,
      start,
      end,
      color,
      duration,
    ])
  }

  public async redrawHighlights(): Promise<void> {
    return this.call(HighlightRedrawMessage, [])
  }

  public async updateHighlight(id: string, color: string): Promise<void> {
    return this.call(HighlightUpdateMessage, [id, color])
  }

  public async addHighlightSelectedListener(
    listener: Callback,
  ): Promise<number> {
    return this.call(AddHighlightSelectedListenerMessage, [], listener)
  }

  public async removeHighlightSelectedListener(
    listenerID: number,
  ): Promise<void> {
    return this.call(RemoveHighlightSelectedListenerMessage, [listenerID])
  }

  public async visibleRangeUpdate(start: number, end: number): Promise<void> {
    return this.call(HighlightVisibleRangeUpdateMessage, [start, end])
  }

  public async setEphemeralHighlightDeletedCallback(
    callback: Callback,
  ): Promise<void> {
    return this.call(SetEphemeralHighlightDeletedCallbackMessage, [], callback)
  }
}

export type HighlightEventListener = (
  index: number,
  highlightInfo: SelectedHighlightInfo,
) => void

interface HighlightEventListenerContext extends ContentEventListenerContext {
  callback: HighlightEventListener
}

class HighlightEventSource implements ContentEventSource {
  public spineItemIndex = -1

  private eventSource: HighlightHandling

  public constructor(win: Window) {
    this.eventSource = new HighlightHandling('highlight-handling', win)
  }
  public async addListener(
    listener: HighlightEventListenerContext,
  ): Promise<number> {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const eventSourceCallback = (result: any[]): void => {
      listener.callback(this.spineItemIndex, result[0])
    }
    return await this.eventSource.addHighlightSelectedListener(
      eventSourceCallback,
    )
  }

  public async removeListener(
    listener: HighlightEventListenerContext,
  ): Promise<void> {
    const listenerID = listener.listenerIDs[this.spineItemIndex]
    await this.eventSource.removeHighlightSelectedListener(listenerID)
  }

  public async deleteHighlight(id: string): Promise<void> {
    return await this.eventSource.deleteHighlight(id)
  }

  public async updateHighlight(id: string, color: string): Promise<void> {
    return await this.eventSource.updateHighlight(id, color)
  }

  public async addHighlight(
    id: string,
    type: HighlightType,
    start: string | number,
    end: string | number,
    color: string,
    duration = 0,
  ): Promise<void> {
    const addHighlightPromise = new Promise<void>((resolve) => {
      requestAnimationFrame(() => {
        // call it a second time to ensure highlight is added AFTER repaint
        // requestAnimationFrame fires callback BEFORE repaint, so we need two
        requestAnimationFrame(() => {
          this.eventSource.addHighlight(
            id,
            type,
            start,
            end,
            color,
            duration,
          )
          resolve()
        })
      })
    })
    return await addHighlightPromise
  }

  public async redrawHighlights(): Promise<void> {
    return await this.eventSource.redrawHighlights()
  }

  public async visibleRangeUpdate(start: number, end: number): Promise<void> {
    return await this.eventSource.visibleRangeUpdate(start, end)
  }

  public async setEphemeralHighlightDeletedCallback(
    callback: Callback,
  ): Promise<void> {
    return await this.eventSource.setEphemeralHighlightDeletedCallback(
      (result: any[]) => {
        callback(result[0])
      },
    )
  }
}

export class HighlightManager extends ContentEventManager {
  private highlights: Map<string, Highlight> = new Map<string, Highlight>()

  public makeEventSource(
    win: Window,
    _spineItemIndex: number,
  ): ContentEventSource {
    const eventSource = new HighlightEventSource(win)
    eventSource.setEphemeralHighlightDeletedCallback((id: string) => {
      this.deleteHighlight(id)
    })

    this.highlights.forEach((highlight, _id) => {
      if (highlight.spineIndex === _spineItemIndex) {
        eventSource.addHighlight(
          highlight.id,
          highlight.type,
          highlight.start,
          highlight.end,
          highlight.color,
          highlight.duration,
        )
      }
    })

    return eventSource
  }

  public redrawHighlights(): void {
    for (const es of this.eventSources) {
      const highlightES = es[1] as HighlightEventSource
      highlightES.redrawHighlights()
    }
  }

  // If both CFI and Offset are present, CFI will take precedence
  public addHighlight(
    id: string,
    startLocation: Location | undefined,
    endLocation: Location | undefined,
    spineIndex: number,
    color: string,
    duration = 0,
  ): void {
    if (
      !startLocation ||
      !endLocation ||
      (!startLocation.partialCfi &&
        !endLocation.partialCfi &&
        startLocation.relativePosition == undefined &&
        endLocation.relativePosition == undefined)
    ) {
      // eslint-disable-next-line no-console
      console.error('Highlight Locators not present')
      return
    }

    let type, start, end
    if (startLocation.partialCfi && endLocation.partialCfi) {
      type = HighlightType.CFI
      start = startLocation.partialCfi
      end = endLocation.partialCfi
    } else if (
      startLocation.relativePosition != undefined &&
      endLocation.relativePosition != undefined
    ) {
      type = HighlightType.Offset
      start = startLocation.relativePosition
      end = endLocation.relativePosition
    }

    if (type == null || start == null || end == null) {
      // eslint-disable-next-line no-console
      console.error('Bad Highlight Locator processing')
      return
    }

    const newHighlight = {
      type,
      start,
      end,
      spineIndex,
      color,
      id,
      duration,
    }

    this.highlights.set(id, newHighlight as Highlight)
    const highlightES = getEventSourceForSpineItemOrNull<HighlightEventSource>(
      spineIndex,
      this.eventSources,
    )
    if (highlightES) {
      highlightES.addHighlight(id, type, start, end, color, duration)
    }
  }

  public deleteHighlight(id: string): void {
    const highlight = this.highlights.get(id)
    if (!highlight) {
      return
    }

    this.highlights.delete(id)
    const highlightES = getEventSourceForSpineItemOrNull<HighlightEventSource>(
      highlight.spineIndex,
      this.eventSources,
    )
    if (highlightES) {
      highlightES.deleteHighlight(id)
    }
  }

  public updateHighlight(id: string, color: string): void {
    const highlight = this.highlights.get(id)
    if (!highlight) {
      return
    }

    highlight.color = color
    const highlightES = getEventSourceForSpineItemOrNull<HighlightEventSource>(
      highlight.spineIndex,
      this.eventSources,
    )
    if (highlightES) {
      highlightES.updateHighlight(id, color)
    }
  }

  public visibleRangeUpdate(
    startIndex: number,
    startOffset: number,
    endIndex: number,
    endOffset: number,
  ): void {
    for (const es of this.eventSources) {
      const highlightSource = es[1] as HighlightEventSource
      const siIndex = highlightSource.spineItemIndex
      if (siIndex < startIndex || siIndex > endIndex) {
        continue
      }
      let actualStartOffset = startOffset
      if (siIndex > startIndex) {
        actualStartOffset = 0
      }
      let actualEndOffset = endOffset
      if (siIndex < endIndex) {
        actualEndOffset = Number.MAX_SAFE_INTEGER
      }
      highlightSource.visibleRangeUpdate(actualStartOffset, actualEndOffset)
    }
  }

  public addHighlightSelectedListener(callback: HighlightEventListener): void {
    const newListener: HighlightEventListenerContext = {
      callback,
      listenerIDs: {},
      removed: false,
    }

    this.eventListeners.push(newListener)
  }
}
