import { degausser } from 'degausser'

import { ElementBlacklistedChecker } from './element-checker'
import { DomNavigationLogic } from './dom-navigation-logic'

interface NodeContentInfo {
  node: Node
  content: string | undefined
  start: number
  length: number
}

export class CharOffsetNavigationLogic {
  private rootDocument: Document

  private domNaviLogic: DomNavigationLogic

  private nodeMap: NodeContentInfo[] = []

  // private charCount = -1

  public constructor(doc: Document, eleChecker: ElementBlacklistedChecker) {
    this.rootDocument = doc

    this.domNaviLogic = new DomNavigationLogic(doc, eleChecker)
  }

  public getOffsetByCharOffset(charOffset: number): [number, number] | null {
    if (this.nodeMap.length < 1) {
      // Lazy initialization of node mapping
      this.nodeMap = degausser(this.rootDocument, {
        map: true,
        elementBlacklist: this.domNaviLogic.getElementBlacklist(),
        idBlacklist: this.domNaviLogic.getIdBlacklist(),
        classBlacklist: this.domNaviLogic.getClassBlacklist(),
      })
    }

    // Special case for offset past end of node
    const lastNode = this.nodeMap[this.nodeMap.length - 1]
    if (lastNode && charOffset >= lastNode.start + lastNode.length) {
      const range = document.createRange()
      const lastNodeNode = lastNode.node

      // https://developer.mozilla.org/en-US/docs/Web/API/range/setStart
      // offset behaves differently for text type nodes vs other elements
      if (
        lastNodeNode.nodeType === Node.TEXT_NODE ||
        lastNodeNode.nodeType === Node.COMMENT_NODE ||
        lastNodeNode.nodeType === Node.CDATA_SECTION_NODE
      ) {
        range.setStart(lastNodeNode, lastNode.length)
        range.setEnd(lastNodeNode, lastNode.length)
      } else {
        // For non-text type nodes, offset is the number of child nodes
        // e.g., spine item with only a single image
        range.selectNode(lastNodeNode)
      }

      return this.domNaviLogic.getOffsetFromRange(range)
    }

    // Linear search through the nodes
    let specificNode: NodeContentInfo | null = null
    for (const nodeInfo of this.nodeMap) {
      if (
        nodeInfo.start <= charOffset &&
        charOffset < nodeInfo.start + nodeInfo.length
      ) {
        specificNode = nodeInfo
        break
      }
    }

    if (!specificNode) {
      // No node found for offset
      return null
    }

    let range: Range | null = null

    if (
      specificNode.node.nodeType !== Node.TEXT_NODE ||
      !specificNode.node.textContent
    ) {
      // If not a text node, simply return the node
      range = document.createRange()

      range.selectNode(specificNode.node)
    } else {
      // Do binary search for the correct offset inside the text node
      const offset = this.binarySearchForOffset(
        specificNode.node,
        charOffset - specificNode.start,
      )

      range = document.createRange()
      range.setStart(specificNode.node, offset)
      range.setEnd(specificNode.node, offset)
    }

    let offset: [number, number] | null = null
    if (range) {
      offset = this.domNaviLogic.getOffsetFromRange(range)
    }

    return offset
  }

  private binarySearchForOffset(node: Node, offset: number): number {
    if (!node.textContent) {
      return 0
    }

    const textContent = node.textContent

    let targetOffset: number | null = null

    let start = 0
    let end = textContent.length
    const holdingElement = document.createElement('p')

    do {
      const middle: number = Math.floor((start + end) / 2)

      // Degausser only works on nodes, so we'll have to stuff in the string
      holdingElement.innerHTML = ''
      holdingElement.append(textContent.slice(0, middle))

      const degaussedLength = degausser(holdingElement, {
        elementBlacklist: this.domNaviLogic.getElementBlacklist(),
        idBlacklist: this.domNaviLogic.getIdBlacklist(),
        classBlacklist: this.domNaviLogic.getClassBlacklist(),
      }).length

      if (degaussedLength < offset) {
        start = middle + 1
      }

      if (degaussedLength > offset) {
        end = middle - 1
      }

      if (degaussedLength === offset) {
        // This is if [middle] lands on a whitespace
        // This is because all whitespace is collapsed after Degaussing, so there's
        //  no good mapping to which whitespace the offset is on
        targetOffset = textContent.slice(0, middle).trimRight().length
        break
      }
    } while (start < end)

    if (targetOffset === null) {
      // This should account for the times charOffset is on a whitespace
      targetOffset = textContent.slice(0, start).trimRight().length
    }

    holdingElement.remove()

    return targetOffset
  }
}
