import { CSSRules } from '../navigator/views/types'

export function applyToStyleDeclaration(
  styleElementCurrent: CSSStyleDeclaration,
  styleUpdate: CSSRules,
): void {
  Object.keys(styleUpdate).forEach((cssPropName) => {
    const cssRule = String(styleUpdate[cssPropName as keyof typeof styleUpdate])

    styleElementCurrent[
      cssPropName as keyof typeof styleElementCurrent extends
        | 'length'
        | 'parentRule'
        ? keyof typeof styleElementCurrent
        : never
    ] = cssRule
  })
}
