import { Presentation } from '@flowpub/webpub-model'

import { Spread } from '../types'

/**
 * Returns Spread mode matching presentation spread setting
 *
 * @export
 * @param {(string | null)} presentationSpread
 * @returns {Spread}
 */
export function getDefaultSpreadModeForPresentation(
  presentationSpread: Required<Presentation>['spread'] | null,
): Spread {
  switch (presentationSpread) {
    case 'both':
      return 'double'
    case 'none':
      return 'single'
    case 'landscape':
    case 'auto':
      return 'auto'
    default:
      return 'auto'
  }
}

/**
 * Returns the Spread depending on the base spread mode
 * and the presentation spread setting
 *
 * @export
 * @param {(string | null)} presentationSpread
 * @param {(Spread | null)} spreadModeBase
 * @returns {(Spread | null)}
 */
export function getSpreadModeOrNullForPresentation(
  presentationSpread: Required<Presentation>['spread'] | null,
  spreadModeBase: Spread | null,
): Spread | null {
  const allowedSettings = ['auto', 'single', 'double']

  if (!spreadModeBase || !allowedSettings.includes(spreadModeBase)) {
    return null
  }
  if (spreadModeBase === 'auto' && presentationSpread) {
    return getDefaultSpreadModeForPresentation(presentationSpread)
  }
  return spreadModeBase
}
