import { PanEvent } from '@flowpub/glue-shared'
import { SnapDirection } from '@flowpub/renderer'

import {
  PanManagerPanContextMethods,
  PanningState,
  NavigatorPanStateMethods,
  PanningContext,
  PanningContextConstructorParameters,
  PanningStateConstructor,
  PanningStateName,
  ViewportPanContextMethods,
} from './types'

export class PanningContextIml implements PanningContext {
  public get name(): PanningStateName {
    return this.state.name
  }
  public get panStartScrollPosition(): number {
    return this._panStartScrollPosition
  }
  public get currentEventOrNull(): PanEvent | null {
    return this._currentEventOrNull
  }
  public get activeSnapDirectionOrNull(): SnapDirection | null {
    return this._activeSnapDirectionOrNull
  }
  public readonly panManager: PanManagerPanContextMethods
  private readonly contentContainer: HTMLElement
  private readonly navigator: NavigatorPanStateMethods
  private readonly viewport: ViewportPanContextMethods
  private readonly stateConstructors: Map<
    PanningStateName,
    PanningStateConstructor
  > = new Map()
  private state: PanningState
  private _panStartScrollPosition = 0
  private _currentEventOrNull: PanEvent | null = null
  private _activeSnapDirectionOrNull: SnapDirection | null = null
  constructor(parameters: PanningContextConstructorParameters) {
    const {
      contentContainer,
      navigator,
      panManager,
      stateConstructors,
      viewport,
    } = parameters

    this.contentContainer = contentContainer
    this.navigator = navigator
    this.panManager = panManager
    this.viewport = viewport
    this.setStateConstructorsMap(stateConstructors)
    this.setInitialState()
  }

  public onPan(event: PanEvent): void {
    this._currentEventOrNull = event
    this.setInitialStateIfCommandFailed(() => {
      this.state.onPan(event)
    })
  }

  public changeState(stateName: PanningStateName): void {
    this.setInitialStateIfCommandFailed(() => {
      this.state = this.getStateImplementationByStateName(stateName)
    })
  }

  public getMaxScrollDist(): number {
    return this.contentContainer.scrollWidth - this.contentContainer.clientWidth
  }

  public setActiveSnapDirectionOrNull(
    snapDirectionOrNull: SnapDirection | null,
  ): void {
    this._activeSnapDirectionOrNull = snapDirectionOrNull
  }

  public setPanStartScrollPosition(panStartScrollPosition: number): void {
    this._panStartScrollPosition = panStartScrollPosition
  }

  public getContentContainerScrollLeft(): number {
    return this.contentContainer.scrollLeft
  }

  public enableNavigatorScreenTransitionAnimation(): void {
    this.navigator.enableScreenTransitionAnimation(true)
  }

  public disableNavigatorScreenTransitionAnimation(): void {
    this.navigator.enableScreenTransitionAnimation(false)
  }

  public translateNavigatorView(offsetPX: number): void {
    this.viewport.translate(offsetPX)
  }

  public saveNavigatorCurrentViewOffset(): void {
    this.navigator.saveViewOffset()
  }

  public getNavigatorZoomScale(): number {
    return this.navigator.getZoomScale()
  }

  public resetNavigatorZoomLevel(): void {
    this.navigator.setZoomScale(1)
  }

  public enableNavigatorClearSelectionSetting(): void {
    this.navigator.setClearSelectionSetting(true)
  }

  public disableNavigatorClearSelectionSetting(): void {
    this.navigator.setClearSelectionSetting(false)
  }

  public snapNavigator(snapDirection: SnapDirection): Promise<void> {
    return this.navigator.snap(snapDirection)
  }

  public isNavigatorTransitionInProgress(): boolean {
    return !this.navigator.isNavigationQueueEmpty
  }

  protected setInitialStateIfCommandFailed(command: () => void): void {
    try {
      command()
    } catch (err) {
      this.setInitialState()
      throw err
    }
  }

  protected getStateConstructorByStateName(
    stateName: PanningStateName,
  ): PanningStateConstructor {
    const StateConstructorOrUndefined = this.stateConstructors.get(stateName)

    if (!StateConstructorOrUndefined) {
      throw new Error(`A constructor is not found for the state ${stateName}`)
    }
    return StateConstructorOrUndefined
  }

  protected getStateImplementationByStateName(
    stateName: PanningStateName,
  ): PanningState {
    const StateConstructor = this.getStateConstructorByStateName(stateName)
    return new StateConstructor(this)
  }

  private setStateConstructorsMap(
    stateConstructors: PanningStateConstructor[],
  ) {
    stateConstructors.forEach((stateConstructor) => {
      this.stateConstructors.set(stateConstructor.state, stateConstructor)
    })
  }

  private setInitialState(): void {
    const panManager = this.panManager

    // TODO - in some tests panManager is not defined
    if (panManager?.panningDisabled) {
      this.state = this.getStateImplementationByStateName(
        PanningStateName.Disabled,
      )
    } else {
      this.state = this.getStateImplementationByStateName(
        PanningStateName.Inactive,
      )
    }
    this._currentEventOrNull = null
    this._activeSnapDirectionOrNull = null
  }
}
