export enum NavigatorTaskName {
  NextScreen = 'nextScreen',
  PreviousScreen = 'previousScreen',
  Snap = 'snap',
  SetSpreadMode = 'setSpreadMode',
  SetViewSettings = 'setViewSettings',
  HandleResizeManual = 'handleResizeManual',
  SetAndApplyVerticalPadding = 'setAndApplyVerticalPadding',
  OnViewportResizedInternalWithNavigationQueue = 'onViewportResizedInternalWithNavigationQueue',
}

export enum NavigatorErrorType {
  /**
   * This error type should be used whenever a task execution
   * is rejected by queue handler.
   */
  RejectedByQueueHandler = 'RejectedByQueueHandler',
  /**
   * This error type should be used whenever a task execution
   * is rejected by timeout.
   */
  RejectedByTimeout = 'RejectedByTimeout',
}

export enum PublicationEdge {
  Start = 'Start',
  End = 'End',
}
