import { PanEvent } from '@flowpub/glue-shared'

import { PanningState, PanningStateName, PanningContext } from '../types'

export class PanningActive implements PanningState {
  static state: PanningStateName = PanningStateName.Active
  public get name(): PanningStateName {
    return PanningActive.state
  }
  constructor(private readonly context: PanningContext) {
    context.setActiveSnapDirectionOrNull(null)
  }
  public onPan(event: PanEvent): void {
    if (event.start) {
      throw new Error(
        'A new event should not start while another event is in process',
      )
    }

    const context = this.context

    // wait until the gesture is finished
    if (event.end) {
      context.changeState(PanningStateName.Finish)
      context.onPan(event)
      return
    }

    // only enable panning if user is panning outside of scrollable region
    if (
      context.panStartScrollPosition < 1 ||
      context.panStartScrollPosition > context.getMaxScrollDist() - 1
    ) {
      const { screenX1 } = event
      this.translateScreen(screenX1)
    }
  }

  protected translateScreen(horizontalOffsetPX: number): void {
    const context = this.context
    const zoomLevel = context.getNavigatorZoomScale()
    const offsetPX: number =
      (context.panManager.lastScreenX - horizontalOffsetPX) / zoomLevel

    // zoomScale needs to be accounted for because translate does not account for it
    context.translateNavigatorView(offsetPX)
    context.panManager.lastScreenX = horizontalOffsetPX
  }
}
