import type {
  ImageCopyGetter,
  ImageCopyProcessor,
  ImageCopyTracker,
  ImageCopyTrackerCollectAndUpdateMethodArgument,
  ImageCopyTrackerConstructorParameters,
  OriginalImagesCollector,
} from './types'

export class ImageCopyTrackerImpl implements ImageCopyTracker {
  protected imageCollector: OriginalImagesCollector
  protected imageCopyGetter: ImageCopyGetter
  protected imageCopyProcessor: ImageCopyProcessor
  constructor(parameters: ImageCopyTrackerConstructorParameters) {
    const { imageCollector, imageCopyGetter, imageCopyProcessor } = parameters

    if (!imageCollector) {
      throw new Error('"imageCollector" parameter should be defined')
    }
    if (!imageCopyGetter) {
      throw new Error('"imageCopyGetter" parameter should be defined')
    }
    if (!imageCopyProcessor) {
      throw new Error('"imageCopyProcessor" parameter should be defined')
    }
    this.imageCollector = imageCollector
    this.imageCopyGetter = imageCopyGetter
    this.imageCopyProcessor = imageCopyProcessor
  }

  public async collectAndUpdate(
    parameters: ImageCopyTrackerCollectAndUpdateMethodArgument,
  ): Promise<void> {
    const { document } = parameters
    if (!document) {
      throw new Error('"document" parameter is not specified')
    }
    await this.updateImageCopiesOnDocument(document)
  }

  /**
   * Collect the original images and their copies that exist in the document and run processing on them.
   *
   * @protected
   * @param {Document} document - a document which images should be processed
   * @return {Promise<void>}
   * @memberof ImageCopyTrackerImpl
   */
  protected async updateImageCopiesOnDocument(
    document: Document,
  ): Promise<void> {
    // TODO - run in queue. Each next call of this method should abort all the queued tasks.
    // There is no reasons to update images that are in invisible spine items.
    // However, such a refactoring should be done with caution, since it might cause issues such as
    // blinks/glitches in images displaying.
    const originalImagesInDocument = await this.imageCollector(document)
    if (!originalImagesInDocument.length) {
      return
    }

    await new Promise((res) => {
      window.requestAnimationFrame(res)
    })
    for (const originalImage of originalImagesInDocument) {
      const originalImageCopy = this.imageCopyGetter({
        originalImage,
        document,
      })

      if (!originalImageCopy) {
        continue
      }
      this.imageCopyProcessor({
        originalImage,
        originalImageCopy,
        document,
      })
    }
  }
}
