import { Caller } from '@flowpub/glue-rpc'
import { Callback } from '@flowpub/glue-shared'
import URI from 'urijs'
import { ContentEventManager } from '@flowpub/renderer'
import type {
  ContentEventSource,
  ContentEventListenerContext,
} from '@flowpub/renderer'

export const LinkHandlingMessageAddListener = 'ADD_LINK_LISTENER'
export const LinkHandlingMessageRemoveListener = 'REMOVE_LINK_LISTENER'

class LinkHandling extends Caller {
  public async addLinkClickListener(listener: Callback): Promise<number> {
    return this.call(LinkHandlingMessageAddListener, [], listener)
  }

  public async removeEventListener(listenerID: number): Promise<void> {
    return this.call(LinkHandlingMessageRemoveListener, [listenerID])
  }
}

export type ContentLinkEventListener = (index: number, href: string) => void

interface ContentLinkEventListenerContext extends ContentEventListenerContext {
  callback: ContentLinkEventListener
}

class ContentLinkEventSource implements ContentEventSource {
  public spineItemIndex = -1

  private eventSource: LinkHandling

  public constructor(win: Window) {
    this.eventSource = new LinkHandling('link-handling', win)
  }

  public async addListener(
    listener: ContentLinkEventListenerContext,
  ): Promise<number> {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const eventSourceCallback = (result: any[]): void => {
      listener.callback(this.spineItemIndex, result[0])
    }
    return await this.eventSource.addLinkClickListener(eventSourceCallback)
  }

  public async removeListener(
    listener: ContentLinkEventListenerContext,
  ): Promise<void> {
    const listenerID = listener.listenerIDs[this.spineItemIndex]
    await this.eventSource.removeEventListener(listenerID)
  }
}

export class ContentLinkEventManager extends ContentEventManager {
  private externalLinkListeners: ContentLinkEventListener[] = []
  private internalLinkListeners: ContentLinkEventListener[] = []

  public makeEventSource(win: Window): ContentEventSource {
    return new ContentLinkEventSource(win)
  }

  public initLinkSupport(): void {
    const newListener = {
      callback: this._handleLink.bind(this),
      listenerIDs: {},
      removed: false,
    }

    this.eventListeners.push(newListener)
  }

  public addExternalLinkListener(callback: ContentLinkEventListener): void {
    this.externalLinkListeners.push(callback)
  }

  public addInternalLinkListener(callback: ContentLinkEventListener): void {
    this.internalLinkListeners.push(callback)
  }

  private _handleLink(index: number, href: string): void {
    if (href.length === 0) {
      return
    }

    const hrefUri = new URI(href)
    const hrefIsRelative = hrefUri.is('relative')

    if (!hrefIsRelative) {
      this._onExernalLinkRequested(index, href)
    } else {
      this._onInternelLinkRequested(index, href)
    }
  }

  private _onExernalLinkRequested(index: number, href: string): void {
    for (const listener of this.externalLinkListeners) {
      listener(index, href)
    }
  }

  private _onInternelLinkRequested(index: number, href: string): void {
    for (const listener of this.internalLinkListeners) {
      listener(index, href)
    }
  }
}
