import { PanEvent } from '@flowpub/glue-shared'

import { PanningState, PanningStateName, PanningContext } from '../types'

export class PanningInactive implements PanningState {
  static state: PanningStateName = PanningStateName.Inactive
  public get name(): PanningStateName {
    return PanningInactive.state
  }
  constructor(private readonly context: PanningContext) {}
  public onPan(event: PanEvent): void {
    const context = this.context

    if (context.panManager.panningDisabled) {
      context.changeState(PanningStateName.Disabled)
      context.onPan(event)
      return
    }
    if (!event.start) {
      return
    }
    // if there any navigation action is active
    // in Navigator do not affect it with gestures
    if (context.isNavigatorTransitionInProgress()) {
      return
    }

    // TODO - add a method to panManager to set panManager.panStart = event
    context.panManager.panStart = event
    context.setPanStartScrollPosition(context.getContentContainerScrollLeft())
    context.disableNavigatorScreenTransitionAnimation()
    context.saveNavigatorCurrentViewOffset()
    context.changeState(PanningStateName.Active)
  }
}
