import type { PageLabelInfoWithPosition } from '../types'

import type { IContentView } from './content-view/content-view'
import { SpineItemView } from './spine-item-view'

export enum ZoomOptions {
  FitByWidth,
  FitByHeight,
  FitByPage,
}

export class CancellationToken {
  public isCancelled = false
}

export enum SettingName {
  ColumnGap = 'column-gap', // number,
  MaxColumnWidth = 'column-max', // number,
  MinColumnWidth = 'column-min', // number,
  SpreadMode = 'spread-mode', // string
  FontFamily = 'font-family', // string
  FontSize = 'font-size', // number
  ReadingMode = 'reading-mode', // string
  TextColor = 'text-color', // string
  BackgroundColor = 'background-color', // string
  TextAlign = 'text-align', // string
  FontOverride = 'font-override', // string
  FontSizeOverride = 'font-size-override', // string
  DefaultsOverride = 'default-override', // string
  AdvancedSettings = 'advanced-settings', // string
  LineHeight = 'line-height', // number
  BorderColor = 'border-color', // string
  Hyphens = 'hyphens', // string
}

export type ReadingMode = 'day' | 'night' | 'sepia'

export type FontFamily =
  | 'old-style'
  | 'modern'
  | 'neutral'
  | 'humanist'
  | 'monospace'
  | ''

export type FontStack =
  | 'var(--RS__oldStyleTf)'
  | 'var(--RS__modernTf)'
  | 'var(--RS__sansTf)'
  | 'var(--RS__humanistTf)'
  | 'var(--RS__monospaceTf)'
  | ''

export interface ISettingEntry {
  name: SettingName
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  value: any
}

const SETTING_NAME_MAP: Map<string, SettingName> = new Map([
  [SettingName.AdvancedSettings, SettingName.AdvancedSettings],
  [SettingName.BackgroundColor, SettingName.BackgroundColor],
  [SettingName.ColumnGap, SettingName.ColumnGap],
  [SettingName.DefaultsOverride, SettingName.DefaultsOverride],
  [SettingName.LineHeight, SettingName.LineHeight],
  [SettingName.MaxColumnWidth, SettingName.MaxColumnWidth],
  [SettingName.MinColumnWidth, SettingName.MinColumnWidth],
  [SettingName.FontFamily, SettingName.FontFamily],
  [SettingName.FontOverride, SettingName.FontOverride],
  [SettingName.FontSize, SettingName.FontSize],
  [SettingName.ReadingMode, SettingName.ReadingMode],
  [SettingName.SpreadMode, SettingName.SpreadMode],
  [SettingName.TextAlign, SettingName.TextAlign],
  [SettingName.TextColor, SettingName.TextColor],
  [SettingName.Hyphens, SettingName.Hyphens],
])

export function stringToSettingName(val: string): SettingName | undefined {
  return SETTING_NAME_MAP.get(val)
}

export enum SpreadMode {
  Freeform,
  FitViewportAuto,
  FitViewportSingleSpread,
  FitViewportDoubleSpread,
}

export enum SpreadLocation {
  Left,
  Right,
  Center,
  None,
}

export enum Hyphens {
  Auto = 'auto',
  Manual = 'manual',
  None = 'none',
}

export type AnimationProperties = Pick<
  CSSStyleDeclaration,
  | 'transitionProperty'
  | 'transitionDuration'
  | 'transitionTimingFunction'
  | 'transitionDelay'
>

export type OmitReadonlyStyleRules<T extends CSSStyleDeclaration> = {
  [k in keyof Omit<T, 'length' | 'parentRule'>]: T[k] extends Function
    ? never
    : T[k]
}

export type CSSRules = Partial<OmitReadonlyStyleRules<CSSStyleDeclaration>>

export type VisibleRangeUpdate = {
  actualStartOffset: number
  actualEndOffset: number
  spineItemIndex: number
  isFirstVisible: boolean
}

export enum PageLabelOnScreenSide {
  Left = 'LEFT',
  Right = 'RIGHT',
}

export type PageLabelInfoWithOnScreenSide = PageLabelInfoWithPosition & {
  onScreenSide: PageLabelOnScreenSide
  pageLabelWidth: number
}

export type ViewOffsets = {
  startOffset: number
  endOffset: number
}

export interface PageLabelManagerEventEmitter {
  addPageLabelsVisibilityFlagListener(
    listener: (arePageLabelsVisible: boolean) => void,
  ): void
  addListenerPageLabelsPositionsUpdate(
    listener: (pageLabelsInfo: PageLabelInfoWithPosition[]) => void,
  ): void
  addPageLabelsVisibleRangeUpdatedListener(
    listener: (visibleRange: VisibleRangeUpdate) => void,
  ): void
}

/**
 * Wait till all the adjustments are done and
 * the content fits into the iframe window
 *
 * @param {number} [2000] timeoutMs - the resulted promise will be resolved after this time
 * @export
 * @interface WaitContentViewFitInIframeWindow
 */
export interface WaitContentViewFitInIframeWindow {
  (spineItemView: SpineItemView, timeoutMs?: number): Promise<void>
}

/**
 * This type is for unobserveCallback function in DRM image obfuscation feature
 */
export type UnobserveCallback = (ele: HTMLElement) => void

/**
 * Will be invoked once a spine item is unloaded
 */
export type HandleUnloadSpineItemCallback = (contentView: IContentView) => void
