import type { UnobserveCallback } from '../../'

import { updatePositionAndSizeToCanvas } from './update-canvas-copy-position-and-size'
import { findImageCopyElement } from './find-image-copy-element'

function handleResizedEntities(entries: ResizeObserverEntry[]): void {
  for (const entry of entries) {
    const target = entry.target
    if (target.tagName !== 'IMG') continue
    else {
      const imgElement = target as HTMLImageElement
      const canvasElement = findImageCopyElement(imgElement)
      if (!canvasElement) continue

      // Update canvas size and position when image is changed
      updatePositionAndSizeToCanvas(imgElement, canvasElement)
    }
  }
}

/**
 * A class to get singleton ResizeObserver instance
 */
export class SingletonResizeObserver {
  // ResizeObserver will be instantiated in a SpineItem iframe
  // window.
  protected static _instancePerWindow = new WeakMap<Window, ResizeObserver>()
  /**
   * Returns an existing instance of ResizeObserver or instantiates
   * a new one.
   *
   * @static
   * @param {Window} windowInstance - a Window for which should exists an instance of
   * ResizeObserver. If there is no an existing one, then a new instance will be created
   * in the scope of this window.
   * @return {ResizeObserver} - an existing or a new instance.
   * @memberof SingletonResizeObserver
   */
  public static getInstance(windowInstance: Window): ResizeObserver {
    if (!windowInstance) {
      throw new Error('The argument is empty')
    }

    const resizeObserverInstanceForWindowOrUndefined = this._instancePerWindow.get(
      windowInstance,
    )
    if (resizeObserverInstanceForWindowOrUndefined) {
      return resizeObserverInstanceForWindowOrUndefined
    }
    const resizeObserverForWindow = new windowInstance.ResizeObserver(
      handleResizedEntities,
    )
    this._instancePerWindow.set(windowInstance, resizeObserverForWindow)
    return resizeObserverForWindow
  }

  /**
   * Returns an existing instance.
   * If there is no existing one, then it won't create a new one.
   *
   * @static
   * @param {Window} windowInstance
   * @return {(ResizeObserver | undefined)}
   * @memberof SingletonResizeObserver
   */
  public static getInstanceOrUndefined(
    windowInstance: Window,
  ): ResizeObserver | undefined {
    if (!windowInstance) {
      throw new Error('The argument is empty')
    }
    return this._instancePerWindow.get(windowInstance)
  }
}

/**
 * Exported function to unobserve images inside the spine item
 */
export const unobserveImages: UnobserveCallback = (
  contentViewElements: HTMLElement,
): void => {
  const imageArray = contentViewElements.getElementsByTagName('iframe')[0]
    .contentDocument?.images
  if (!imageArray) return
  for (const img of Array.from(imageArray)) {
    const imgElementWindow: Window | null = img.ownerDocument.defaultView
    if (!imgElementWindow) {
      continue
    }

    const imageResizeObserver = SingletonResizeObserver.getInstanceOrUndefined(
      imgElementWindow,
    )
    imageResizeObserver?.unobserve(img)
  }
}
