import { degausser } from 'degausser'
import { IContentView } from '@flowpub/renderer'
import * as EPUBcfi from '@evidentpoint/readium-cfi-js'

import { Locator } from '../types'
import { Location as RendererLocation } from '../../../renderer'
import {
  classBlacklist,
  elementBlacklist,
  idBlacklist,
} from '../default-blacklist'
import { ProcessedResource } from '../processed-publication'

