/**
 * Checks if two range intersect.
 * Any overlap, including a shared boundary, is considered intersecting.
 * A pair of locators define the start and end of the range.
 * A single locator will be considered a range with length 0.
 * @param a Array containing one or two locators
 * @param b Array containing one or two locators
 * @param processedResources all processed resources in reading order
 * @throws Error Will throw error if locators don't contain enough information
 */
export function doLocationsIntersect(
  [aStart, aEnd = aStart]: [Locator, Locator?],
  [bStart, bEnd = bStart]: [Locator, Locator?],
  processedResources: ProcessedResource[] = [],
): boolean {
  let aStartPos: number
  let aEndPos: number
  let bStartPos: number
  let bEndPos: number

  try {
    aStartPos = getLocationAbsolutePosition(aStart, processedResources)
    aEndPos = getLocationAbsolutePosition(aEnd, processedResources)
    bStartPos = getLocationAbsolutePosition(bStart, processedResources)
    bEndPos = getLocationAbsolutePosition(bEnd, processedResources)
  } catch {
    // use relative positions if possible
    if (aStart.href !== aEnd.href || bStart.href !== bEnd.href) {
      throw new Error('locators need additional location information')
    }

    if (aStart.href !== bStart.href) {
      return false
    }

    aStartPos = getLocationRelativePosition(aStart)
    aEndPos = getLocationRelativePosition(aEnd)
    bStartPos = getLocationRelativePosition(bStart)
    bEndPos = getLocationRelativePosition(bEnd)
  }

  if (aStartPos > aEndPos) {
    ;[aStartPos, aEndPos] = [aEndPos, aStartPos]
  }
  if (bStartPos > bEndPos) {
    ;[bStartPos, bEndPos] = [bEndPos, bStartPos]
  }

  const aStartAfterBEnd = aStartPos > bEndPos
  const bStartAfterAEnd = bStartPos > aEndPos
  return !(aStartAfterBEnd || bStartAfterAEnd)
}

function getLocationRelativePosition(locator: Locator, start = true): number {
  if (!locator.locations || !locator.locations.relativePosition) {
    if (start) {
      return 0
    } else {
      return Number.POSITIVE_INFINITY
    }
  }

  return locator.locations.relativePosition
}

/**
 * Returns the absolute position of a locator.
 * If absolute position is missing then will use processedResources to determine absolute position from relative position.
 * @param locator
 * @param processedResources all processed resources in reading order
 * @throws Error if locator is missing all of locator position, relativePosition and processedResources
 */
function getLocationAbsolutePosition(
  locator: Locator,
  processedResources: ProcessedResource[] = [],
): number {
  if (!locator.locations) {
    throw new Error('locator does not have locations')
  }

  if (locator.locations.position !== undefined) {
    return locator.locations.position
  }

  if (locator.locations.relativePosition === undefined) {
    throw new Error(
      'locator does not have position or relativePosition locations',
    )
  }

  // add all previous resource lengths to get absolute position
  const resourceIndex = processedResources.findIndex(
    (resource) => resource.href === locator.href,
  )
  if (resourceIndex === -1) {
    throw new Error('locator href not found in processedResources')
  }

  let absolutePosition = 0
  for (let i = 0; i < resourceIndex; i++) {
    const resource = processedResources[i]
    absolutePosition += resource.textLength
  }

  absolutePosition += locator.locations.relativePosition
  return absolutePosition
}

/**
 * Checks if range inner is contained within range outer.
 * Range inner is contained within range outer if and only if the
 * entire range inner is between the start and end of the range outer.
 * A pair of locators defines the start and end of the range.
 * A single locator will be considered a range with length 0.
 * @param outer Array defining the boundaries of outer range
 * @param inner Array defining the boundaries of inner range
 * @param strict if true, the inner range must not intersect the boundary of the outer range
 * @throws Error Will throw error if any range contain locators with different hrefs
 */
export function isLocationContained(
  [outerStart, outerEnd = outerStart]: [Locator, Locator?],
  [innerStart, innerEnd = innerStart]: [Locator, Locator?],
  strict = false,
  processedResources: ProcessedResource[] = [],
): boolean {
  let outerStartPos: number
  let outerEndPos: number
  let innerStartPos: number
  let innerEndPos: number

  try {
    outerStartPos = getLocationAbsolutePosition(outerStart, processedResources)
    outerEndPos = getLocationAbsolutePosition(outerEnd, processedResources)
    innerStartPos = getLocationAbsolutePosition(innerStart, processedResources)
    innerEndPos = getLocationAbsolutePosition(innerEnd, processedResources)
  } catch {
    // not enough information to use absolute positions
    if (
      outerStart.href !== outerEnd.href ||
      innerStart.href !== innerEnd.href
    ) {
      throw new Error('locators of the same range must have the same href')
    }

    if (outerStart.href !== innerStart.href) {
      return false
    }

    outerStartPos = getLocationRelativePosition(outerStart)
    outerEndPos = getLocationRelativePosition(outerEnd)
    innerStartPos = getLocationRelativePosition(innerStart)
    innerEndPos = getLocationRelativePosition(innerEnd)
  }

  if (outerStartPos > outerEndPos) {
    // https://prettier.io/docs/en/rationale.html#semicolons
    ;[outerStartPos, outerEndPos] = [outerEndPos, outerStartPos]
  }
  if (innerStartPos > innerEndPos) {
    ;[innerStartPos, innerEndPos] = [innerEndPos, innerStartPos]
  }

  const startOk = strict
    ? innerStartPos > outerStartPos
    : innerStartPos >= outerStartPos
  const endingOk = strict
    ? innerEndPos < outerEndPos
    : innerEndPos <= outerEndPos
  return startOk && endingOk
}

/**
 * Returns the distance between two ranges. 0 means they are intersecting.
 * Negative means the second range is before the first range.
 * @param first Array defining the boundary of the first range
 * @param second Array defining the boundary of the second range
 * @throws Error Will throw error if the ranges are not of the same href
 * @throws Error Will throw error if any range contain locators with different hrefs
 */
export function getCharacterOffsetDistance(
  [firstStart, firstEnd = firstStart]: [Locator, Locator?],
  [secondStart, secondEnd = secondStart]: [Locator, Locator?],
  processedResources: ProcessedResource[] = [],
): number {
  let firstStartPos: number
  let firstEndPos: number
  let secondStartPos: number
  let secondEndPos: number
  try {
    firstStartPos = getLocationAbsolutePosition(firstStart, processedResources)
    firstEndPos = getLocationAbsolutePosition(firstEnd, processedResources)
    secondStartPos = getLocationAbsolutePosition(
      secondStart,
      processedResources,
    )
    secondEndPos = getLocationAbsolutePosition(secondEnd, processedResources)
  } catch {
    if (firstStart.href !== secondStart.href) {
      throw new Error('ranges must be of the same href')
    }

    if (
      firstStart.href !== firstEnd.href ||
      secondStart.href !== secondEnd.href
    ) {
      throw new Error('locators of the same range must have the same href')
    }

    firstStartPos = getLocationRelativePosition(firstStart)
    firstEndPos = getLocationRelativePosition(firstEnd)
    secondStartPos = getLocationRelativePosition(secondStart)
    secondEndPos = getLocationRelativePosition(secondEnd)
  }

  if (firstStartPos > firstEndPos) {
    ;[firstStartPos, firstEndPos] = [firstEndPos, firstStartPos]
  }
  if (secondStartPos > secondEndPos) {
    ;[secondStartPos, secondEndPos] = [secondEndPos, secondStartPos]
  }

  const intersectionCheck = Math.max(
    Math.min(firstEndPos - secondStartPos, secondEndPos - firstStartPos) * -1,
    0,
  )

  if (intersectionCheck === 0) {
    return 0
  }

  if (firstStartPos > secondEndPos) {
    return (firstStartPos - secondEndPos) * -1
  }

  return secondStartPos - firstEndPos
}

/**
 * This currently uses an internal API from Navigation Logic
 *  but there was discussions about possibly moving navLogic away from
 *  ContentView?
 */
export function getRangeForLocation(
  location: RendererLocation,
  viewport: Pick<Viewport, 'getSpineItemViewByHref'>,
): Range | null {
  const cfi = location.getLocation()
  if (!cfi) {
    return null
  }

  const spineItemView = viewport.getSpineItemViewByHref(location.getHref())
  if (!spineItemView) {
    return null
  }

  return getRangeForCfi(spineItemView.getContentView(), cfi)
}

export function getRangeForCfi(
  contentView: IContentView,
  partialCfi: string,
): Range | null {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const navLogic = (contentView as any).cfiNavLogic

  try {
    // WARNING cfiNavLogic is internal API
    return navLogic.getRangeFromCfi(partialCfi)
  } catch (error) {
    console.error(error)
    return null
  }
}

/**
 * Returns the text content of a range.
 * A locator with no location is assumed to be the start(if start parameter)
 * or end(if end parameter) of the spine item which maps to the href.
 * @param start Locator defining the start of the range
 * @param end Locator defining the end of the range
 * @param viewport Viewport object in use
 * @throws Error Will throw error if the ranges are not of the same href
 * @throws Error Will throw error if iframe of locator is not loaded
 */
export function getTextContentBetween(
  [start, end = start]: [Locator, Locator?],
  viewport: Pick<Viewport, 'getSpineItemDocumentByHrefOrNull'>,
): string {
  if (start.href !== end.href) {
    throw new Error('ranges must be of the same href')
  }

  const iframeDocument = viewport.getSpineItemDocumentByHrefOrNull(start.href)
  if (!iframeDocument) {
    throw new Error('iframe document not loaded')
  }

  const contentRange = iframeDocument.createRange()
  contentRange.selectNode(iframeDocument.body)
  const textContent = degausser(contentRange.cloneContents(), {
    classBlacklist,
    idBlacklist,
    elementBlacklist,
  })

  let startPos = getLocationRelativePosition(start)
  let endPos = getLocationRelativePosition(end, false)
  if (startPos > endPos) {
    ;[startPos, endPos] = [endPos, startPos]
  }

  return textContent.substring(startPos, endPos)
}

/**
 *
 * Compares CFI strings and returns array of integers indicating relative locations.
 *
 * If given two CFIs for single points, returned array will contain a single value.
 * If given two range CFIs, returned array will contain two values corresponding
 * to relative order of range start CFIs and range end CFIs, respectively.
 *
 * This is a wrapper around Readium's CFI comparison logic.
 * More extensive documentation of this method can be found here:
 * {@link https://github.com/evidentpoint/readium-cfi-js/blob/f350eafc6d5267d5f9a47cc448a5e64ceecc82f8/src/interpreter.js#L356}
 *
 * @param cfiA A string corresponding to a CFI or range CFI
 * @param cfiB A string corresponding to a CFI or range CFI
 */
export function compareCFIs(cfiA: string, cfiB: string): string {
  try {
    const resultsArray = EPUBcfi.Interpreter.compareCFIs(
      `epubcfi(/99!${cfiA})`,
      `epubcfi(/99!${cfiB})`,
    )

    if (resultsArray[0] === resultsArray[1]) {
      return JSON.stringify(resultsArray.slice(1))
    }

    return JSON.stringify(resultsArray)
  } catch (error) {
    console.error('CFI parsing encountered an error: ', error)
    return JSON.stringify([])
  }
}
