import * as EPUBcfi from '@evidentpoint/readium-cfi-js'

import {
  ElementBlacklistedChecker,
  IVisibleElementInfo,
} from './element-checker'
import { Rect } from './rect'
import { DomNavigationLogic } from './dom-navigation-logic'

export class CfiNavigationLogic {
  private rootDocument: Document

  private domNavLogic: DomNavigationLogic

  public constructor(doc: Document, eleChecker: ElementBlacklistedChecker) {
    this.rootDocument = doc
    this.domNavLogic = new DomNavigationLogic(doc, eleChecker)
  }

  public setColumnSize(width: number, height: number): void {
    this.domNavLogic.setColumnSize(width, height)
  }

  public getCfiFromElementId(elementId: string): string | null {
    const element = this.domNavLogic.getElementById(elementId)
    if (!element) {
      return null
    }

    return this.getCfiFromElement(element)
  }

  public getCfiFromElement(element: Element): string {
    let cfi = EPUBcfi.Generator.generateElementCFIComponent(
      element,
      this.domNavLogic.getClassBlacklist(),
      this.domNavLogic.getElementBlacklist(),
      this.domNavLogic.getIdBlacklist(),
    )

    if (cfi[0] === '!') {
      cfi = cfi.substring(1)
    }

    return cfi
  }

  public getFirstVisibleCfi(viewport: Rect, fromEnd: boolean): string | null {
    const visChecker = this.domNavLogic.createVisibilityChecker(viewport)
    const visibleEleInfo = visChecker.findFirstVisibleElement(fromEnd)

    return this.findVisibleLeafNodeCfi(visibleEleInfo, viewport, fromEnd)
  }

  public getOffsetByCfi(cfi: string): [number, number] | null {
    if (this.isRangeCfi(cfi)) {
      const range = this.getNodeRangeInfoFromCfi(cfi)
      if (range) {
        return this.getOffsetFromRange(range)
      }

      return null
    }

    const ele = this.getElementByCfi(cfi)
    if (ele) {
      return this.getOffsetFromElement(ele)
    }

    return null
  }

  public getElementByCfi(cfi: string): HTMLElement | null {
    return this.getElementByPartialCfi(cfi)
  }

  public getOffsetFromElement(ele: Node): [number, number] | null {
    return this.domNavLogic.getOffsetFromElement(ele)
  }

  public getOffsetFromElementId(eleId: string): [number, number] | null {
    return this.domNavLogic.getOffsetFromElementId(eleId)
  }

  public getOffsetFromRange(range: Range): [number, number] | null {
    return this.domNavLogic.getOffsetFromRange(range)
  }

  public isRangeCfi(partialCfi: string): boolean {
    const cfi = this.wrapCfi(partialCfi)

    return (
      EPUBcfi.Interpreter.isRangeCfi(cfi) ||
      EPUBcfi.Interpreter.hasTextTerminus(cfi)
    )
  }

  public getElementById(eleId: string): HTMLElement | null {
    return this.domNavLogic.getElementById(eleId)
  }

  public getRangeFromCfi(cfi: string): Range | null {
    let range = null
    if (this.isRangeCfi(cfi)) {
      range = this.getNodeRangeInfoFromCfi(cfi)
    } else {
      const ele = this.getElementByCfi(cfi)
      if (ele) {
        range = document.createRange()
        range.selectNode(ele)
      }
    }

    return range
  }

  public getRangeFromCfiUnion(startCfi: string, endCfi?: string): Range | null {
    const startRange = this.getRangeFromCfi(startCfi)
    if (!endCfi) {
      return startRange
    }

    const endRange = this.getRangeFromCfi(endCfi)
    if (!endRange || !startRange) {
      return startRange
    }

    const unionRange = this.domNavLogic.createRange(
      startRange.startContainer,
      startRange.startOffset,
      endRange.endContainer,
      endRange.endOffset,
    )

    return unionRange
  }

  private findVisibleLeafNodeCfi(
    visNode: IVisibleElementInfo,
    viewport: Rect,
    fromEnd: boolean,
  ): string | null {
    const element = visNode.element
    const textNode = visNode.textNode

    // if a valid text node is found, try to generate a CFI with range offsets
    if (textNode && this.domNavLogic.isValidTextNode(textNode)) {
      const visChecker = this.domNavLogic.createVisibilityChecker(viewport)
      const visibleRange = visChecker.getVisibleTextRange(textNode, fromEnd)

      return this.generateCfiFromRange(visibleRange)
    }

    if (element) {
      return this.getCfiFromElement(element)
    }

    return null
  }

  private generateCfiFromRange(range: Range): string {
    if (range.collapsed && range.startContainer.nodeType === Node.TEXT_NODE) {
      return EPUBcfi.Generator.generateCharacterOffsetCFIComponent(
        range.startContainer,
        range.startOffset,
        this.domNavLogic.getClassBlacklist(),
        this.domNavLogic.getElementBlacklist(),
        this.domNavLogic.getIdBlacklist(),
      )
    }

    if (range.collapsed) {
      return this.getCfiFromElement(range.startContainer as Element)
    }

    return EPUBcfi.Generator.generateRangeComponent(
      range.startContainer,
      range.startOffset,
      range.endContainer,
      range.endOffset,
      this.domNavLogic.getClassBlacklist(),
      this.domNavLogic.getElementBlacklist(),
      this.domNavLogic.getIdBlacklist(),
    )
  }

  private getElementByPartialCfi(cfi: string): HTMLElement | null {
    const wrappedCfi = this.wrapCfi(cfi)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let $element: any
    try {
      //noinspection JSUnresolvedVariable
      $element = EPUBcfi.Interpreter.getTargetElement(
        wrappedCfi,
        this.rootDocument,
        this.domNavLogic.getClassBlacklist(),
        this.domNavLogic.getElementBlacklist(),
        this.domNavLogic.getIdBlacklist(),
      )
    } catch (ex) {
      // EPUBcfi.Interpreter can throw a SyntaxError
    }

    if (!$element || $element.length === 0) return null

    const node = $element[0]
    if (node.nodeType === Node.TEXT_NODE) {
      return node.parentElement
    }
    return node
  }

  private getNodeRangeInfoFromCfi(cfi: string): Range | null {
    const wrappedCfi = this.wrapCfi(cfi)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let nodeResult: any
    if (EPUBcfi.Interpreter.isRangeCfi(wrappedCfi)) {
      try {
        //noinspection JSUnresolvedVariable
        nodeResult = EPUBcfi.Interpreter.getRangeTargetElements(
          wrappedCfi,
          this.rootDocument,
          this.domNavLogic.getClassBlacklist(),
          this.domNavLogic.getElementBlacklist(),
          this.domNavLogic.getIdBlacklist(),
        )
      } catch (ex) {
        // EPUBcfi.Interpreter can throw a SyntaxError
      }

      if (!nodeResult) {
        console.error(`Can't find nodes for range CFI: ${cfi}`)

        return null
      }

      return this.domNavLogic.createRange(
        nodeResult.startElement,
        nodeResult.startOffset,
        nodeResult.endElement,
        nodeResult.endOffset,
      )
    }

    if (EPUBcfi.Interpreter.hasTextTerminus(wrappedCfi)) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      let textTerminusResult: any
      try {
        textTerminusResult = EPUBcfi.Interpreter.getTextTerminusInfo(
          wrappedCfi,
          this.rootDocument,
          this.domNavLogic.getClassBlacklist(),
          this.domNavLogic.getElementBlacklist(),
          this.domNavLogic.getIdBlacklist(),
        )
      } catch (ex) {
        // EPUBcfi.Interpreter can throw a SyntaxError
      }

      if (!textTerminusResult) {
        console.error(`Can't find node for text term CFI: ${cfi}`)

        return null
      }

      const container = textTerminusResult.textNode
      const start = textTerminusResult.textOffset

      // SG(2021.07.08): removed this as it was throwing out
      // of range error and doesn't appear necessary anymore
      // LD(2018.10.02): it seems like Chrome(v69) has a bug that collapsed
      // range with witespace char won't report proper getClientRects().
      // so a no-collapsed range is created instead
      // const end = textTerminusResult.textOffset + 1
      const end = textTerminusResult.textOffset

      return this.domNavLogic.createRange(container, start, container, end)
    }

    return null
  }

  private wrapCfi(partialCfi: string): string {
    return `epubcfi(/99!${partialCfi})`
  }
}
