import { degausser } from 'degausser'
import * as EPUBcfi from '@evidentpoint/readium-cfi-js'

import {
  classBlacklist,
  elementBlacklist,
  idBlacklist,
} from '../default-blacklist'

/**
 * Returns the cfi which maps to the end of the line of the range.
 * Can return empty string if no cfi can be found.
 * Warning! Range should be collapsed and contain a text node.
 *
 * @export
 * @param range collapsed range
 * @param iframeDocument document which contains the range
 * @returns cfi or empty string
 */
export function getLineEndCfi(range: Range, iframeDocument: Document): string {
  if (range.endContainer === document || !range.collapsed) {
    return ''
  }

  // First we find the text node which contains the first line break after the range
  // then we (binary) search through that node to find the precise offset of that line break

  const lineBreakNode = getNodeWithNextLineBreak(
    range.cloneRange(),
    iframeDocument,
  )
  if (!lineBreakNode) {
    return ''
  }

  let lowerBound
  let upperBound
  if (lineBreakNode === range.startContainer) {
    lowerBound = range.startOffset
  } else {
    lowerBound = 0
  }
  upperBound = lineBreakNode.textContent?.length || 0
  range.setEnd(lineBreakNode, upperBound)

  // binary search to find the character offset of the first line break
  while (lowerBound < upperBound) {
    const mid = Math.floor((lowerBound + upperBound) / 2)
    try {
      range.setEnd(range.endContainer, mid)
    } catch (e) {
      if ((e as DOMException).name === 'IndexSizeError') {
        upperBound = mid
        continue
      }

      return ''
    }

    // each line produces its own rect
    const clientRects = range.getClientRects()
    const boundingRect = range.getBoundingClientRect()
    if (clientRects[0].height !== boundingRect.height) {
      // line break found
      upperBound = mid
    } else {
      if (lowerBound === mid) {
        // diff between lower and upper is exactly one
        break
      } else {
        lowerBound = mid
      }
    }
  }

  // diff between lower and upper is 0 or 1
  // test upper bound and reduce it if necessary
  range.setEnd(range.endContainer, upperBound)
  if (
    range.getClientRects()[0].height !== range.getBoundingClientRect().height
  ) {
    upperBound = Math.max(upperBound - 1, 0)
    range.setEnd(range.endContainer, upperBound)
  }

  range.collapse(false)
  return generateCfi(range)
}

/**
 * Returns the text node which contains the first line break after the range
 *
 * @param range collapsed range
 * @param iframeDocument document which contains the range
 * @returns node with next line break or null
 */
function getNodeWithNextLineBreak(
  range: Range,
  iframeDocument: Document,
): Node | null {
  if (range.endContainer === document || !range.collapsed) {
    return null
  }

  const treeWalker = iframeDocument.createTreeWalker(
    iframeDocument.body,
    NodeFilter.SHOW_TEXT,
    {
      acceptNode: (node: Node) => {
        if (!node.textContent || node.textContent.trim() === '') {
          return NodeFilter.FILTER_SKIP
        }
        return NodeFilter.FILTER_ACCEPT
      },
    },
  )

  // iterate through nodes until we find the one that contains the range
  while (treeWalker.nextNode()) {
    const node = treeWalker.currentNode as Text
    if (node === range.startContainer) {
      break
    }
  }

  if (treeWalker.currentNode === iframeDocument.body) {
    // no nodes with text content found
    return null
  }

  // iterate through nodes until we find the one that contains the end of the line
  // each client rect is one line height, bounding client rect can be larger
  // large bounding client rect means it spans multiple lines
  // multiple nodes can be on one line, e.g., inline italics element
  do {
    // test start of range to end of current node
    range.setEnd(
      treeWalker.currentNode,
      treeWalker.currentNode.textContent?.length || 0,
    )
    const clientRects = range.getClientRects()
    if (clientRects.length > 1) {
      // possibly multiple lines
      const boundingRect = range.getBoundingClientRect()
      if (clientRects[0].height === boundingRect.height) {
        // bounding rect is only one line high
        // can happen with inline elements, e.g., italics

        // test start of next node
        // this is necessary to detect instances where line break is at end of currentNode
        if (treeWalker.nextNode()) {
          range.setEnd(treeWalker.currentNode, 1)

          // reset node
          treeWalker.previousNode()

          if (testForLineBreak(range)) {
            break
          }
        }

        continue
      } else {
        // bounding rect is more than one line height
        // found line break at currentNode
        break
      }
    } else {
      // test start of next node
      // this is necessary to detect instances where line break is at end of currentNode
      if (treeWalker.nextNode()) {
        range.setEnd(treeWalker.currentNode, 1)

        // reset node
        treeWalker.previousNode()

        if (testForLineBreak(range)) {
          break
        }
      }
    }
  } while (treeWalker.nextNode())

  return treeWalker.currentNode
}

/**
 * Check whether provided range contains a line break
 * @param range
 * @returns true if range contains a line break
 */
function testForLineBreak(range: Range): boolean {
  const clientRects = range.getClientRects()
  const boundingRect = range.getBoundingClientRect()
  if (clientRects[0].height < boundingRect.height) {
    // bounding rect is more than one line high
    // found line break
    return true
  }

  return false
}

/**
 * Copied and adapted from CFI-Nav-Logic, selection-handling.ts
 * Generate a CFI at a position from a collapsed DOM Range
 * @param range collapsed range
 * @returns {string} CFI or empty string if no CFI could be generated
 */
function generateCfi(range: Range): string {
  if (!range.collapsed) {
    console.error('Not collapsed range')
    return ''
  }
  if (range.startContainer.nodeType === Node.TEXT_NODE) {
    return EPUBcfi.Generator.generateCharacterOffsetCFIComponent(
      range.startContainer,
      range.startOffset,
      classBlacklist,
      idBlacklist,
      elementBlacklist,
    )
  } else {
    let cfi = EPUBcfi.Generator.generateElementCFIComponent(
      range.startContainer as Element,
    )

    if (cfi[0] === '!') {
      // this is for step indirections
      // http://idpf.org/epub/linking/cfi/#sec-path-indirection
      // not expected to trigger, but just in case
      cfi = cfi.substring(1)
    }

    return cfi
  }
}

/**
 * Returns a text wrapped in the range
 *
 * @export
 * @param {Range} range
 * @param {boolean} [begin=true] - whether the range should be collapsed to its start or the end
 * @returns {string}
 */
export function getStringFromRange(range: Range, begin = true): string {
  const documentElement = range.startContainer?.ownerDocument
    ?.documentElement as Node
  range.collapse(begin)
  range.setStartBefore(documentElement)

  const fragment = range.cloneContents()
  const text = degausser(fragment, {
    classBlacklist,
    idBlacklist,
    elementBlacklist,
  })
  return text
}
