import {
  AsyncTaskDescription,
  AsyncTaskDescriptionStrict,
  AsyncTaskDescriptionWithId,
  AsyncTaskId,
} from '../types'

import {
  AsyncTaskStorage,
  AsyncTaskStore,
  AsyncTaskStoreEventEmitter,
  AsyncTaskStoreFabric,
  AsyncTaskStoreFabricParameters,
} from './types'
import {
  AsyncTaskStoreEventName,
  AsyncTaskStoreEventParameter,
} from './types/async-task-store-events'

export function addIdentifierToAsyncTaskDescription<R>(
  taskDescription: AsyncTaskDescription<R>,
): AsyncTaskDescriptionWithId<R> {
  const { name: taskName } = taskDescription
  const taskDescriptionWithId: AsyncTaskDescriptionWithId<R> = {
    id: Symbol(taskName),
    ...taskDescription,
  }
  return taskDescriptionWithId
}

export class AsyncTaskStoreImpl implements AsyncTaskStore {
  public get isEmpty(): boolean {
    return this.storage.isEmpty
  }
  private eventEmitter: AsyncTaskStoreEventEmitter
  private storage: AsyncTaskStorage
  constructor(parameters: AsyncTaskStoreFabricParameters) {
    const { eventEmitter, storage } = parameters

    this.eventEmitter = eventEmitter
    this.storage = storage
  }
  public addTask<R>(taskDescription: AsyncTaskDescription<R>): void {
    const taskDescriptionWithId = addIdentifierToAsyncTaskDescription(
      taskDescription,
    )

    this.emitEventBeforeAddTaskByTaskDescription(taskDescriptionWithId)
    this.storage.addTask(taskDescriptionWithId)
    this.emitEventAfterAddTaskByTaskDescription(taskDescriptionWithId)
  }

  public getTaskDescriptionOrNullById<ID extends AsyncTaskId>(
    taskId: ID,
  ): AsyncTaskDescriptionStrict<unknown, ID> | null {
    return this.getTaskDescriptionOrNullByTaskId(taskId)
  }

  public rejectAndRemoveTaskById<ID extends AsyncTaskId>(
    taskId: ID,
    error: Error,
  ): void {
    this.runTaskDescriptionHandlerInTryCatchAndRemoveTheTaskByIdFinally(
      taskId,
      (taskDescription: AsyncTaskDescriptionWithId<unknown, ID>): void => {
        taskDescription.onError(error)
      },
    )
  }

  public resolveAndRemoveTaskById<R, ID extends AsyncTaskId>(
    taskId: ID,
    result: R,
  ): void {
    this.runTaskDescriptionHandlerInTryCatchAndRemoveTheTaskByIdFinally(
      taskId,
      (taskDescription: AsyncTaskDescriptionWithId<unknown, ID>): void =>
        taskDescription.onResolve(result),
    )
  }

  public getAllStoredTasksIds(): AsyncTaskId[] {
    return this.storage.getAllStoredTasksIds()
  }

  public getNextTaskOrNullToRun(): AsyncTaskDescriptionWithId<unknown> | null {
    const nextTaskToRunDescriptionOrNull: AsyncTaskDescriptionWithId<
      unknown
    > | null = this.getFirstTaskDescriptionOrNull()

    if (!nextTaskToRunDescriptionOrNull) {
      return null
    }

    this.emitEventBeforeNextTaskRunByTaskDescription(
      nextTaskToRunDescriptionOrNull,
    )

    // check whether task has been deleted from the list after the event was triggered
    const taskToRunDescriptionOrNull: AsyncTaskDescriptionWithId<
      unknown
    > | null = this.storage.getTaskOrNullById(nextTaskToRunDescriptionOrNull.id)

    if (!taskToRunDescriptionOrNull) {
      // the task was removed
      return this.getNextTaskOrNullToRun()
    }
    return taskToRunDescriptionOrNull
  }

  public logStateInConsole(groupTitle: string): void {
    this.storage.logStateInConsole(groupTitle)
  }

  protected emitEvent<E extends AsyncTaskStoreEventName>(
    event: E,
    eventParameters: AsyncTaskStoreEventParameter<E>,
  ) {
    this.eventEmitter.emit(event, eventParameters)
  }

  protected getEmitEventBaseParameter(
    taskDescriptionWithTaskId: AsyncTaskDescriptionWithId<any>,
  ): AsyncTaskStoreEventParameter<AsyncTaskStoreEventName> {
    const eventParameter: AsyncTaskStoreEventParameter<AsyncTaskStoreEventName> = {
      asyncTaskStore: this,
      taskDescriptionWithId: taskDescriptionWithTaskId,
    }
    return eventParameter
  }

  protected emitEventBeforeAddTaskByTaskDescription(
    taskDescriptionWithTaskId: AsyncTaskDescriptionWithId<any>,
  ) {
    const eventParameter: AsyncTaskStoreEventParameter<AsyncTaskStoreEventName.BeforeTaskAdded> = this.getEmitEventBaseParameter(
      taskDescriptionWithTaskId,
    )
    this.emitEvent(AsyncTaskStoreEventName.BeforeTaskAdded, eventParameter)
  }

  protected emitEventAfterAddTaskByTaskDescription(
    taskDescriptionWithTaskId: AsyncTaskDescriptionWithId<any>,
  ) {
    const eventParameter: AsyncTaskStoreEventParameter<AsyncTaskStoreEventName.AfterTaskAdded> = this.getEmitEventBaseParameter(
      taskDescriptionWithTaskId,
    )
    this.emitEvent(AsyncTaskStoreEventName.AfterTaskAdded, eventParameter)
  }

  protected emitEventBeforeNextTaskRunByTaskDescription(
    taskDescriptionWithTaskId: AsyncTaskDescriptionWithId<any>,
  ) {
    const eventParameter: AsyncTaskStoreEventParameter<AsyncTaskStoreEventName.BeforeNextTaskRun> = this.getEmitEventBaseParameter(
      taskDescriptionWithTaskId,
    )
    this.emitEvent(AsyncTaskStoreEventName.BeforeNextTaskRun, eventParameter)
  }

  protected getFirstTaskIdOrNullFromStore(): AsyncTaskId | null {
    const idsOfTasksPending = this.storage.getAllStoredTasksIds()

    if (!idsOfTasksPending.length) {
      return null
    }
    const firstTaskId: AsyncTaskId = idsOfTasksPending[0]
    return firstTaskId
  }

  protected getTaskDescriptionOrNullByTaskId<ID extends AsyncTaskId>(
    taskId: ID,
  ): AsyncTaskDescriptionWithId<unknown, ID> | null {
    return this.storage.getTaskOrNullById(taskId)
  }

  protected getTaskDescriptionByTaskId<ID extends AsyncTaskId>(
    taskId: ID,
  ): AsyncTaskDescriptionWithId<unknown, ID> {
    const taskDescriptionOrNull: AsyncTaskDescriptionWithId<
      unknown,
      ID
    > | null = this.getTaskDescriptionOrNullByTaskId(taskId)

    if (!taskDescriptionOrNull) {
      throw new Error(`There is no the description of the task ${taskId}`)
    }
    return taskDescriptionOrNull
  }

  protected getFirstTaskDescriptionOrNull(): AsyncTaskDescriptionWithId<
    unknown
  > | null {
    const firstTaskIdOrNull: AsyncTaskId | null = this.getFirstTaskIdOrNullFromStore()

    if (!firstTaskIdOrNull) {
      return null
    }

    const nextTaskToRunDescriptionOrNull: AsyncTaskDescriptionWithId<
      unknown
    > | null = this.getTaskDescriptionOrNullByTaskId(firstTaskIdOrNull)

    if (!nextTaskToRunDescriptionOrNull) {
      return null
    }
    return nextTaskToRunDescriptionOrNull
  }

  protected runTaskDescriptionHandlerInTryCatchAndRemoveTheTaskByIdFinally<
    ID extends AsyncTaskId
  >(
    taskId: ID,
    taskDescriptionHandler: (
      taskDescription: AsyncTaskDescriptionWithId<unknown, ID>,
    ) => void,
  ): void {
    const taskDescription = this.getTaskDescriptionByTaskId(taskId)

    try {
      taskDescriptionHandler(taskDescription)
    } finally {
      this.storage.removeTaskById(taskId)
    }
  }
}

export const asyncTaskStoreFabric: AsyncTaskStoreFabric = (
  parameters: AsyncTaskStoreFabricParameters,
): AsyncTaskStore => {
  const asyncTaskStoreInstance: AsyncTaskStore = new AsyncTaskStoreImpl(
    parameters,
  )
  return asyncTaskStoreInstance
}
