import type { Resource } from '../../navigator'

import type { AssetPreload, InjectAsset, InjectAssetAsync } from './types'
import {
  createCssLinkElement,
  createScriptElement,
} from './create-html-element'
import { loadContentAndReturnBlobURL } from './asset-preload'

export function injectAsset(resource: Resource, document: Document): boolean {
  const { href, type, target, insertion } = resource

  let element
  if (type === 'text/javascript') {
    element = createScriptElement(href, document)
  } else if (type === 'text/css') {
    element = createCssLinkElement(href, document)
  } else {
    return false
  }

  let targetElement
  if (target === 'head') {
    targetElement = document.head
  } else if (typeof target === 'string') {
    targetElement = document.querySelector(target)
  } else if (typeof target === 'object') {
    targetElement = target
  }

  if (!targetElement) {
    return false
  }

  if (insertion === 'prepend') {
    targetElement.prepend(element)
  } else if (insertion === 'append') {
    targetElement.append(element)
  } else {
    return false
  }

  return true
}

/**
 * Load a resource (or pull it up from the cache) and
 * inject the downloaded asset into the target document.
 *
 * @export
 * @param {Resource} resource - description of the asset.
 * @param {Document} document - the target document where to inject it.
 * @param {AssetPreload} [preloadResource=loadContentAndReturnBlobURL] - a utility that is used to get an asset url.
 * The function can implement a caching strategy in order not to load the same asset for each new document,
 * but to share the one that has already been downloaded.
 * @param {(InjectAsset | InjectAssetAsync)} [injectAssetToIFrame=injectAsset] - a function that injects the loaded resource into the
 * target document depending on its type.
 * @return {Promise<boolean>} - true if the resource was successfully loaded and injected.
 */
export async function injectAssetWithPreloadAsync(
  resource: Resource,
  document: Document,
  preloadResource: AssetPreload = loadContentAndReturnBlobURL,
  injectAssetToIFrame: InjectAsset | InjectAssetAsync = injectAsset,
): Promise<boolean> {
  const preloadedResourceUrl = await preloadResource(resource.href)
  const resourceWithNewUrl: Resource = {
    ...resource,
    href: preloadedResourceUrl,
  }

  return await injectAssetToIFrame(resourceWithNewUrl, document)
}
