export interface AnimationProperties {
  transitionDuration?: string
  transitionTimingFunction?: string
  transitionDelay?: string
  [key: string]: string | undefined
}

interface CompleteAnimationProperties extends AnimationProperties {
  transitionProperty: string
}

const defaultOptions: AnimationProperties = {
  transitionDuration: '0.25s',
  transitionTimingFunction: 'ease',
  transitionDelay: '0s',
}

const blankOptions: CompleteAnimationProperties = {
  transitionProperty: '',
  transitionDuration: '',
  transitionDelay: '',
  transitionTimingFunction: '',
}

export function getScreenTransitionAnimation(
  shouldUnset: boolean,
  animationProperties?: AnimationProperties,
): AnimationProperties {
  // TODO - maybe we can use it within "setScreenTransitionAnimation"
  let resultedAnimationProperties: AnimationProperties = {
    ...animationProperties,
  }
  if (
    resultedAnimationProperties &&
    Object.keys(resultedAnimationProperties).length > 0
  ) {
    for (const key of Object.keys(resultedAnimationProperties)) {
      resultedAnimationProperties[key] =
        resultedAnimationProperties[key] || defaultOptions[key]
    }
  } else {
    resultedAnimationProperties = {
      ...defaultOptions,
    }
  }

  // The property to be animated should not be configurable
  resultedAnimationProperties.transitionProperty = 'transform'

  const allowedProps: { [key: string]: string } = {
    transitionProperty: 'transitionProperty',
    transitionDuration: 'transitionDuration',
    transitionTimingFunction: 'transitionTimingFunction',
    transitionDelay: 'transitionDelay',
  }
  const allowedPropsList = Object.keys(allowedProps)

  // Loop over object that was passed in
  for (const key of Object.keys(resultedAnimationProperties)) {
    if (!allowedPropsList.includes(key)) {
      delete resultedAnimationProperties[key]
      continue
    }

    // Get name of CSS Property for object key
    const CSSPropertyKey = allowedProps[key]

    // Get value of CSS Property from animationProperties object or blankOptions
    const CSSPropertyValue = shouldUnset
      ? blankOptions[key]
      : resultedAnimationProperties?.[key]

    // Apply changes to layout root DOM element
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    resultedAnimationProperties[CSSPropertyKey] = CSSPropertyValue!
  }

  return resultedAnimationProperties
}

/**
 * Defines and sets and animation on screen transition
 *
 * These animation properties correspond to the CSS Transition
 * properties of the same names. Take a look at the
 * {@link https://developer.mozilla.org/en-US/docs/Web/CSS/transition MDN} docs for more details.
 *
 *
 * @param {AnimationProperties} animationProperties The properties for the animation.
 */
export function setScreenTransitionAnimation(
  layoutRoot: HTMLElement,
  shouldUnset: boolean,
  animationProperties?: AnimationProperties,
): AnimationProperties {
  if (animationProperties && Object.keys(animationProperties).length > 0) {
    for (const key of Object.keys(animationProperties)) {
      animationProperties[key] = animationProperties[key] || defaultOptions[key]
    }
  } else {
    // the animationProperties object is modified within the code
    animationProperties = {
      ...defaultOptions,
    }
  }

  // The property to be animated should not be configurable
  animationProperties.transitionProperty = 'transform'

  const allowedProps: { [key: string]: string } = {
    transitionProperty: 'transition-property',
    transitionDuration: 'transition-duration',
    transitionTimingFunction: 'transition-timing-function',
    transitionDelay: 'transition-delay',
  }

  // Loop over object that was passed in
  for (const key of Object.keys(animationProperties)) {
    if (!Object.keys(allowedProps).includes(key)) {
      delete animationProperties[key]
      continue
    }

    // Get name of CSS Property for object key
    const CSSPropertyKey = allowedProps[key]

    // Get value of CSS Property from animationProperties object or blankOptions
    const CSSPropertyValue = shouldUnset
      ? blankOptions[key]
      : animationProperties[key]

    // Apply changes to layout root DOM element
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    layoutRoot.style.setProperty(CSSPropertyKey, CSSPropertyValue!)
  }

  return animationProperties
}
