import { Caller } from '@flowpub/glue-rpc'
import { Callback } from '@flowpub/glue-shared'
import { ContentEventManager } from '@flowpub/renderer'
import type {
  ContentEventSource,
  ContentEventListenerContext,
} from '@flowpub/renderer'

export const WheelMessageAddListener = 'ADD_WHEEL_LISTENER'
export const WheelMessageRemoveListener = 'REMOVE_WHEEL_LISTENER'

class WheelHandling extends Caller {
  public async addWheelListener(listener: Callback): Promise<number> {
    return this.call(WheelMessageAddListener, [], listener)
  }

  public async removeEventListener(listenerID: number): Promise<void> {
    return this.call(WheelMessageRemoveListener, [listenerID])
  }
}

// export type WheelEventListener = (event: WheelEvent) => void
export type WheelEventListener = (
  iframeContext: boolean,
  clientX: number,
  clientY: number,
  ctrlKey: boolean,
  deltaY: number,
  spineItemIndex: number,
) => void

interface WheelEventListenerContext extends ContentEventListenerContext {
  callback: WheelEventListener
}

class WheelEventSource implements ContentEventSource {
  public spineItemIndex = -1

  private eventSource: WheelHandling

  public constructor(win: Window) {
    this.eventSource = new WheelHandling('wheel-handling', win)
  }

  public async addListener(
    listener: WheelEventListenerContext,
  ): Promise<number> {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const eventSourceCallback = (result: any[]): void => {
      listener.callback(
        result[0],
        result[1],
        result[2],
        result[3],
        result[4],
        this.spineItemIndex,
      )
    }
    return await this.eventSource.addWheelListener(eventSourceCallback)
  }

  public async removeListener(
    listener: WheelEventListenerContext,
  ): Promise<void> {
    const listenerID = listener.listenerIDs[this.spineItemIndex]
    await this.eventSource.removeEventListener(listenerID)
  }
}

export class WheelEventManager extends ContentEventManager {
  public makeEventSource(win: Window): ContentEventSource {
    return new WheelEventSource(win)
  }

  public addWheelListener(callback: WheelEventListener): void {
    const newListener: WheelEventListenerContext = {
      callback,
      listenerIDs: {},
      removed: false,
    }

    this.eventListeners.push(newListener)
  }
}
