import {
  AsyncTaskStoreEventEmitter,
  AsyncTaskStoreEventListener,
  AsyncTaskStoreEventName,
  AsyncTaskStoreEventParameter,
  AsyncTaskStoreEventsList,
} from './types'

type EventListeners<E extends AsyncTaskStoreEventName> = Set<
  AsyncTaskStoreEventListener<E>
>

type EventListenersMap<
  E extends AsyncTaskStoreEventName = AsyncTaskStoreEventName
> = Map<E, EventListeners<E>>

function getEventParameterWithIdAndEventName<E extends AsyncTaskStoreEventName>(
  eventName: E,
  eventParameterWithoutIdAndName: AsyncTaskStoreEventParameter<E>,
): AsyncTaskStoreEventsList[E] {
  const parameterWithIdAndEventName: AsyncTaskStoreEventsList[E] = ({
    ...eventParameterWithoutIdAndName,
    id: Symbol(eventName),
    eventName,
  } as unknown) as AsyncTaskStoreEventsList[E] // TODO - typescript resolves the type as never
  return parameterWithIdAndEventName
}

// TODO - we might refactor this into EventEmitter base class and inherit from it
export class AsyncTaskStoreEventEmitterImpl
  implements AsyncTaskStoreEventEmitter {
  private listenersMap: EventListenersMap = new Map()
  public addListener<E extends AsyncTaskStoreEventName>(
    event: E,
    listener: AsyncTaskStoreEventListener<E>,
  ): void {
    this.addListenerToListenersMap(event, listener)
  }
  public removeListener<E extends AsyncTaskStoreEventName>(
    event: E,
    listener: AsyncTaskStoreEventListener<E>,
  ): void {
    this.removeListenerFromListenersMap(event, listener)
  }
  public emit<E extends AsyncTaskStoreEventName>(
    event: E,
    parameter: AsyncTaskStoreEventParameter<E>,
  ): void {
    this.callEachEventListenerWithParameter(event, parameter)
  }

  protected addListenerToListenersMap<E extends AsyncTaskStoreEventName>(
    event: E,
    listener: AsyncTaskStoreEventListener<E>,
  ): void {
    const listeners: EventListeners<E> =
      this.listenersMap.get(event) ?? new Set<AsyncTaskStoreEventListener<E>>()
    listeners.add(listener)
    this.listenersMap.set(
      event,
      listeners as EventListeners<AsyncTaskStoreEventName>,
    )
  }

  protected removeListenerFromListenersMap<E extends AsyncTaskStoreEventName>(
    event: E,
    listener: AsyncTaskStoreEventListener<E>,
  ): void {
    const listenersOrUndefined:
      | EventListeners<E>
      | undefined = this.listenersMap.get(event)
    listenersOrUndefined?.delete(listener)
  }

  protected getRunnerListenerWithParameterInTryCatch<
    E extends AsyncTaskStoreEventName
  >(
    listenerParameter: AsyncTaskStoreEventsList[E],
  ): (listener: AsyncTaskStoreEventListener<E>) => void {
    return (listener: AsyncTaskStoreEventListener<E>): void => {
      try {
        listener(listenerParameter)
      } catch (err) {
        console.error(err)
      }
    }
  }

  protected callEachEventListenerWithParameter<
    E extends AsyncTaskStoreEventName
  >(event: E, parameter: AsyncTaskStoreEventParameter<E>): void {
    const listenersOrUndefined:
      | EventListeners<E>
      | undefined = this.listenersMap.get(event)
    const parameterWithId: AsyncTaskStoreEventsList[E] = getEventParameterWithIdAndEventName(
      event,
      parameter,
    )
    listenersOrUndefined?.forEach(
      this.getRunnerListenerWithParameterInTryCatch(parameterWithId),
    )
  }
}
