import { Caller } from '@flowpub/glue-rpc'
import { Callback } from '@flowpub/glue-shared'
import {
  ContentEventListenerContext,
  ContentEventManager,
  ContentEventSource,
  ContentLoader,
} from '@flowpub/renderer'

export const AddFocusableElementEndListenerMessage =
  'ADD_FOCUSABLE_ELEMENT_END_LISTENER'
export const EnableTabFocusMessage = 'ENBABLE_TABFOCUS'
export const FocusMessage = 'FOCUS'
export const TabFocusVisibleRangeUpdateMessage = 'TABFOCUS_VISIBLE_RANGE_UPDATE'

class TabFocusHandling extends Caller {
  public async enableTabFocus(enabled: boolean): Promise<void> {
    return this.call(EnableTabFocusMessage, [enabled])
  }

  public async focus(): Promise<boolean> {
    return this.call(FocusMessage, [])
  }

  public async visibleRangeUpdate(start: number, end: number): Promise<void> {
    return this.call(TabFocusVisibleRangeUpdateMessage, [start, end])
  }

  public async addFocusableElementEndListener(
    listener: Callback,
  ): Promise<number> {
    return this.call(AddFocusableElementEndListenerMessage, [], listener)
  }
}

export type TabFocusEventListener = (index: number) => void

interface TabFocusEventListenerContext extends ContentEventListenerContext {
  callback: TabFocusEventListener
}

class TabFocusEventSource implements ContentEventSource {
  public spineItemIndex = -1

  private eventSource: TabFocusHandling

  public constructor(win: Window) {
    this.eventSource = new TabFocusHandling('tab-focus-handling', win)
  }

  public async addListener(
    listener: TabFocusEventListenerContext,
  ): Promise<number> {
    const eventSourceCallback = (): void => {
      listener.callback(this.spineItemIndex)
    }
    return await this.eventSource.addFocusableElementEndListener(
      eventSourceCallback,
    )
  }

  public async removeListener(
    _listener: TabFocusEventListenerContext,
  ): Promise<void> {
    return
  }

  public async enableTabFocus(enabled: boolean): Promise<void> {
    return await this.eventSource.enableTabFocus(enabled)
  }

  public async focus(): Promise<boolean> {
    return await this.eventSource.focus()
  }

  public async visibleRangeUpdate(start: number, end: number): Promise<void> {
    return await this.eventSource.visibleRangeUpdate(start, end)
  }
}

export class TabFocusManager extends ContentEventManager {
  private isEnabled = false

  public constructor(loader: ContentLoader) {
    super(loader)
    this.init()
  }

  public makeEventSource(
    win: Window,
    spineItemIndex: number,
  ): ContentEventSource {
    const eventSource = new TabFocusEventSource(win)
    eventSource.spineItemIndex = spineItemIndex
    eventSource.enableTabFocus(this.isEnabled)
    return eventSource
  }

  public visibleRangeUpdate(
    startIndex: number,
    startOffset: number,
    endIndex: number,
    endOffset: number,
  ): void {
    for (const es of this.eventSources) {
      const focusSource = es[1] as TabFocusEventSource
      const siIndex = focusSource.spineItemIndex
      let actualStartOffset = startOffset
      let actualEndOffset = endOffset
      if (siIndex < startIndex || siIndex > endIndex) {
        actualStartOffset = -1
        actualEndOffset = -1
      } else {
        if (siIndex > startIndex) {
          actualStartOffset = 0
        }
        if (siIndex < endIndex) {
          actualEndOffset = Number.MAX_SAFE_INTEGER
        }
      }

      focusSource.visibleRangeUpdate(actualStartOffset, actualEndOffset)
    }
  }

  public enableTabFocus(enabled: boolean): void {
    this.isEnabled = enabled
    for (const es of this.eventSources) {
      const focusSource = es[1] as TabFocusEventSource
      focusSource.enableTabFocus(enabled)
    }
  }

  public async focus(): Promise<void> {
    const index = this.eventSources[0][1].spineItemIndex
    await this.focusInternal(index)
  }

  private init(): void {
    const handler = async (index: number) => {
      await this.focusInternal(index)
    }

    const newListener: TabFocusEventListenerContext = {
      callback: handler,
      listenerIDs: {},
      removed: false,
    }

    this.eventListeners.push(newListener)
  }

  private async focusInternal(index: number): Promise<void> {
    const foundNextFocus = await this.tryFocusNextSource(index, false)
    if (foundNextFocus === true) {
      return
    }

    await this.tryFocusNextSource(index, true)
  }

  private async tryFocusNextSource(
    startIndex: number,
    lookBefore: boolean,
  ): Promise<boolean> {
    for (const es of this.eventSources) {
      const focusSource = es[1] as TabFocusEventSource
      if (
        (lookBefore && focusSource.spineItemIndex <= startIndex) ||
        (!lookBefore && focusSource.spineItemIndex > startIndex)
      ) {
        const focused = await focusSource.focus()
        if (focused) {
          return true
        }
      }
    }
    return false
  }
}
