  constructor(viewportRoot: HTMLElement | string) {
    if (typeof viewportRoot === 'string') {
      this.viewportRoot = document.querySelector(viewportRoot) as HTMLElement
    } else {
      this.viewportRoot = viewportRoot
    }

    this.viewportElement = document.createElement('div')
    this.viewportRoot.appendChild(this.viewportElement)

    this.viewAsVertical = false
    this.enableScroll = false
    this._calcViewportDimensions()

    this.navigationAsyncTaskStoreEventEmitter =
      this.createNavigationAsyncQueueEventEmitterInstance()
    this.navigationAsyncQueue = this.createNavigationAsyncQueueInstance()
    this.initializeNavigationAsyncQueueEventHandlers()
  }

  private _calcViewportDimensions(): void {
    // For mobile SDKs, we use the `body` tag as the viewport root.
    // This causes an issue where changing the device orientation does not
    // properly update the dimenions of the viewpor root element on mobile.
    //
    // As a result, we have to adopt a different strategy for mobile -
    // we check the dimensions of `window` instead, as they update properly.
    //
    // For this reason, we are checking the node type of the viewport root
    // as a way of determining whether we are currently on mobile or not,
    // so that we know which dimensions to use.
    const isWebPlatform = this.viewportRoot.nodeName.toLowerCase() !== 'body'

    if (!isWebPlatform) {
      this.viewportHeight = window.innerHeight
      this.viewportWidth = window.innerWidth
      this.pageHeight = window.innerHeight
      this.pageWidth = window.innerWidth
      return
    }

    this.viewportHeight = this.viewportRoot.clientHeight
    this.viewportWidth = this.viewportRoot.clientWidth
    this.pageHeight = this.viewportRoot.clientHeight
    this.pageWidth = this.viewportRoot.clientWidth
  }

  /**
   * Set a value of a task timeout to an instance of ContentEventManager.
   * TODO - CYP-1308 refactor/add tests
   *
   * @private
   * @param {ContentEventManager} contentEventManager
   * @return {*}
   * @memberof Navigator
   */
  private setContentModuleTimeoutIfExists(
    contentEventManager: ContentEventManager,
  ) {
    const contentManagerTimeoutMsOrUndefined = this.contentManagerTimeoutMs
    if (!contentManagerTimeoutMsOrUndefined) {
      // if a zero or undefined, then do nothing
      return
    }
    contentEventManager.setTaskTimeoutMs(contentManagerTimeoutMsOrUndefined)
  }

  private _setupContentModule(loader: IFrameLoader): void {
    const iframeModuleRes: Resource = {
      href: `${this.contentModuleBase}/${this.contentModuleFileName}`,
      type: 'text/javascript',
      target: 'head',
      insertion: 'append',
    }

    const injectableResources = [iframeModuleRes]

    if (this.customStyleSheetPaths?.length) {
      for (const path of this.customStyleSheetPaths) {
        const customStyleSheet: Resource = {
          href: path,
          type: 'text/css',
          target: 'head',
          insertion: 'append',
        }
        injectableResources.push(customStyleSheet)
      }
    }

    loader.registerInjectableResources(injectableResources)

    this.contentDomEventManager = new ContentDomEventManager(loader)
    this.setContentModuleTimeoutIfExists(this.contentDomEventManager)

    this.contentLinkEventManager = new ContentLinkEventManager(loader)
    this.setContentModuleTimeoutIfExists(this.contentLinkEventManager)
    this.contentLinkEventManager.initLinkSupport()
    this.contentLinkEventManager.addInternalLinkListener(
      (index: number, href: string) => {
        this._gotoRelatvieHrefFromSpineItem(index, href)
      },
    )

    this.selectionChangingEventManager = new SelectionChangingEventManager(
      loader,
    )
    this.setContentModuleTimeoutIfExists(this.selectionChangingEventManager)
    this.selectionChangingEventManager.addSelectionChangingListener(
      (index: number, data: SelectionData | null) => {
        this.onSelectionChangingInternal(index, data)
      },
    )

    this.selectionEventManager = new SelectionEventManager(loader)
    this.setContentModuleTimeoutIfExists(this.selectionEventManager)
    this.selectionEventManager.addSelectionChangeListener((index, data) => {
      this.onSelectionChangedInternal(index, data)
    })

    this.assistiveSelectionEventManager = new AssistiveSelectionEventManager(
      loader,
    )
    this.setContentModuleTimeoutIfExists(this.assistiveSelectionEventManager)

    const scale = 1 // todo find good scale, might change depending on wheel event deltaMode
    this.wheelEventManager = new WheelEventManager(loader)
    this.setContentModuleTimeoutIfExists(this.wheelEventManager)
    this.wheelEventManager.addWheelListener(
      async (
        iframeContext: boolean,
        clientX: number,
        clientY: number,
        pinch: boolean,
        deltaY: number,
        spineItemIndex: number,
      ) => {
        const spineItemView =
          this.rendition.viewport.getSpineItemView(spineItemIndex)
        if (!spineItemView) {
          return
        }

        // safari gesture events report clientX,Y positions in window context
        // other browsers wheel events report clientX,Y positions in iframe context
        if (iframeContext) {
          this.panManager.lastPinchXCenter =
            PanManager.convertIframeToWindowPositionX(clientX, spineItemView)
          this.panManager.lastPinchYCenter =
            PanManager.convertIframeToWindowPositionY(clientY, spineItemView)
        } else {
          this.panManager.lastPinchXCenter = clientX
          this.panManager.lastPinchYCenter = clientY
        }

        if (pinch) {
          this.lastScale = 100
          await this.onPinch('change', this.lastScale - scale * deltaY)
        }
      },
    )

    this.highlightManager = new HighlightManager(loader)
    this.setContentModuleTimeoutIfExists(this.highlightManager)
    this.addHighlightSelectedEventListener((index, info) => {
      this.onHighlightSelected(info)
    })

    // we need to create an instance even if the rendering is disabled because
    // later this feature can be turned on and as we don't support the initialization
    // of the page label manager from scratch this enabling won't work
    const pageLabelManager = new PageLabelManager(loader)
    this.setContentModuleTimeoutIfExists(pageLabelManager)
    this.pageLabelManager = pageLabelManager
    this.enablePageLabelRendering(this.pageLabelRenderingEnabled)

    this.panManager = new PanManager(loader)
    this.setContentModuleTimeoutIfExists(this.panManager)
    this.addPanEventListener((panEvent: PanEvent) => {
      this.onPan(panEvent)
    })

    this.tabFocusManager = new TabFocusManager(loader)
    this.setContentModuleTimeoutIfExists(this.tabFocusManager)
  }

  private async _gotoRelatvieHrefFromSpineItem(
    index: number,
    href: string,
  ): Promise<void> {
    const spineItem = this.publication.spine[index]
    if (!spineItem) {
      console.error('invalid spine item index: ' + index)
      return
    }

    let targetHref = spineItem.href

    const hrefUri = new URI(href)
    const fileName = hrefUri.filename()
    if (fileName) {
      const normalizedUri = new URI(hrefUri, spineItem.href)
      const pathname = decodeURIComponent(normalizedUri.pathname())
      targetHref = pathname
    }

    const targetSpineItem =
      this.publication.findSpineItemIndexByHref(targetHref)
    if (!targetSpineItem) {
      console.error('invalid spine item: ' + targetHref)
      return
    }

    await this.gotoAnchorLocation(targetHref, hrefUri.fragment())
  }

