  private async onPinch(
    _scale: 'start' | 'change' | 'end',
    _pinchDist: number,
  ): Promise<void> {
    // TODO - CYP-756 ?? within the navigation queue
    if (!this.rendition.isFixedLayout()) {
      return
    }
    const setScaleNotRounded = Math.min(
      Math.max(
        (this.rendition.getZoomScale() * _pinchDist) / this.lastScale,
        1.0,
      ),
      4.0,
    )
    // round the scale to 2 digits after a comma
    const setScale =
      Math.floor((setScaleNotRounded + Number.EPSILON) * 100) / 100

    const scaleDiff = setScale - this.zoomScale // absolute difference in scale value

    // get the ratio difference of zoom
    const sizeDiff = scaleDiff / this.zoomScale

    // get the position of center of pinch as a percentage distance between
    // left/top side and right/bottom corner of content container
    const clipperPinchPositionX =
      this.contentContainer.scrollLeft +
      this.panManager.lastPinchXCenter -
      this.contentContainer.getBoundingClientRect().left

    const clipperPinchPositionY =
      this.contentContainer.scrollTop +
      this.panManager.lastPinchYCenter -
      this.contentContainer.getBoundingClientRect().top

    const scrollDiffX = sizeDiff * clipperPinchPositionX
    const scrollDiffY = sizeDiff * clipperPinchPositionY

    this.setZoomScale(setScale)

    // overflow must be changed after setting the zoom scale for iOS Safari to properly scroll
    const overflowValue = this.contentContainer.style.overflow
    // change overflow to something it is not
    this.contentContainer.style.overflow =
      overflowValue === 'scroll' ? 'auto' : 'scroll'
    await new Promise(window.requestAnimationFrame)
    // change overflow back
    this.contentContainer.style.overflow = overflowValue
    if (setScale === 1) {
      this.contentContainer.scrollLeft = 0
      this.contentContainer.scrollTop = 0
      return
    }
    // move content to center zoom on pinch location
    this.contentContainer.scrollLeft =
      this.contentContainer.scrollLeft + scrollDiffX
    this.contentContainer.scrollTop =
      this.contentContainer.scrollTop + scrollDiffY
  }

  // TODO - CYP-802 write a test
  private async onPan(event: PanEvent): Promise<void> {
    if (this.isTransitionToAnotherScreenActive) {
      return
    }

    const panningContext = this.panningContextOrNull

    if (!panningContext) {
      throw new Error('The panning context is not defined')
    }

    const panningStateName: PanningStateName = panningContext.name
    const isPanning =
      panningStateName !== PanningStateName.Inactive &&
      panningStateName !== PanningStateName.Disabled
    const eventSpineItemView = this.rendition.viewport.getSpineItemView(
      event.index,
    )

    this.panManager.processPan(event, eventSpineItemView)
    // if it's not a panning in progress, we can detect a "pinch" event instead
    if (!isPanning) {
      const { end, pinch } = event
      // iOS occasionally treats `touchend` with two touches
      // as two individual `touchend` events with a single touch each.
      // Checking for actual pinch distance is meant to correct that.
      const isTruePinch = end
        ? this.panManager.lastPinchDist !== this.panManager.startPinchDist
        : pinch

      if (isTruePinch) {
        await this.handlePinch(event)
        return
      }
    }
    panningContext.onPan(event)
  }

  // TODO - it might be a public method running in queue
  // transitionEndCallback?: () => void - perhaps we should wait for this callback
  // otherwise translate actions might influence each other
  protected translate(delta: number): void {
    this.rendCtx.rendition.viewport.translate(delta)
  }

  private resetZoom(): void {
    this.setZoomScale(1)
  }

  private lastScale = 100

  /**
   * Returns the zoom scale value. This specific value is used for page zooming, and not for zooming for page fitting (fit-by-width/height/auto).
   *
   * @returns Positive number, 1 is default zoom, smaller number means zoomed out, larger number means zoomed in.
   */
  public getZoomScale(): number {
    return this.zoomScale
  }

  private async handlePinch(event: PanEvent): Promise<void> {
    const { start, end } = event

    if (this.panManager.startPinchDist === 0) {
      return
    }

    const scale =
      (this.panManager.lastPinchDist / this.panManager.startPinchDist) * 100

    if (start) {
      this.lastScale = scale
      await this.onPinch('start', scale)
      return
    }

    if (end) {
      await this.onPinch('end', scale)
      setTimeout(() => {
        this.panManager.lastPinchDist = this.panManager.startPinchDist = 0
      })
      return
    }

    await this.onPinch('change', scale)
    this.lastScale = scale
  }

