  /**
   * Converts selection data to start or end locator.
   *
   * @param data selection data to extract locator from
   * @param spineLink spine item link from reading order
   * @param start true if start locator is needed, false if end locator is needed
   */
  private convertSelectionDataToLocation(
    data: SelectionData,
    spineLink: Link,
    start = true,
  ): Locator {
    let locationData = data.start
    if (!start) {
      locationData = data.end
    }

    const pageLocator = this.getPageLocatorForRelativePosition(
      locationData.offset,
      spineLink.href,
    )

    return {
      href: spineLink.href,
      type: spineLink.type ?? 'application/xhtml+xml', // TODO: Might be a bad idea
      locations: {
        relativePosition: locationData.offset,
        partialCfi: locationData.cfi,
      },
      text: {
        after: data.content,
      },
      title: pageLocator?.title,
    }
  }

  private convertSelectionDataToInfo(
    index: number,
    data: SelectionData,
  ): SelectionInfo {
    const spineLink = this.publication.readingOrder[index]

    const highlightIds = data.highlights.highlights.map((info) => {
      return info.id
    })

    const rectList: Rect[] = this.getAdjustedSelectionRects(index, data.rects)

    const finalSelection: SelectionInfo = {
      content: data.content,
      start: this.convertSelectionDataToLocation(data, spineLink, true),
      end: this.convertSelectionDataToLocation(data, spineLink, false),
      rects: rectList,
      highlights: highlightIds,
      href: data.href,
      spineItemIndex: index,
      highlightOverlappingByPosition: data.highlightOverlappingByPosition,
    }

    return finalSelection
  }

  private onSelectionChangedInternal = (
    index: number,
    data: SelectionData | null,
  ): void => {
    if (data === null) {
      this.onSelectionChanged(null)
      return
    }

    const finalSelection = this.convertSelectionDataToInfo(index, data)

    this.onSelectionChanged(finalSelection)
  }

  private onSelectionChangingInternal = (
    index: number,
    data: SelectionData | null,
  ): void => {
    if (data === null) {
      this.onSelectionChanging(null)
      return
    }

    const finalSelection = this.convertSelectionDataToInfo(index, data)

    this.onSelectionChanging(finalSelection)
  }

