  /**
   * Adjusts selection rects to be relative to
   * window coordinate space instead of iframe
   *
   * @param index Spine item index
   * @param rects Selection rects with values adjusted by
   * selection handling module's `getSingleRect`
   * @returns Selection rects with values
   * adjusted to window coordinate space
   */
  public getAdjustedSelectionRects(index: number, rects: Rect[]): Rect[] {
    const spineItemView = this.rendition.viewport.getSpineItemView(index)

    const iframeRect = spineItemView
      ? spineItemView.getIframeBoundingBox()
      : new DOMRect()
    const iframeOffsetHeight = spineItemView
      ? spineItemView.getIframeOffsetHeight()
      : 1
    const scale = iframeRect.height / iframeOffsetHeight

    const rectList = []

    for (let i = 0; i < rects.length; ++i) {
      const rect = rects[i]
      if (!rect) {
        continue
      }

      if (spineItemView) {
        rect.x = PanManager.convertIframeToWindowPositionX(
          rect.x,
          spineItemView,
        )
        rect.y = PanManager.convertIframeToWindowPositionY(
          rect.y,
          spineItemView,
        )
      } else {
        console.error('no spine item view')
        continue
      }

      rect.width *= scale
      rect.height *= scale
      rectList.push(rect)
    }

    return rectList
  }

