  /**
   * Set view settings, and apply it immediately
   * if "options.applyImmediately" === true
   *
   * For font-family, the book default can be assigned by providing a value of
   * 'default' or ''
   *
   * @param {(ViewSettings | string)} settings
   * @param {SetViewSettingsOptions} [options = {}]
   * @returns {Promise<void>}
   * @memberof Navigator
   */
  public async setViewSettings(
    settings: ViewSettings | string,
    options: Partial<SetViewSettingsOptions> = {},
  ): Promise<void> {
    const finalSettings: ViewSettings =
      typeof settings === 'string' ? JSON.parse(settings) : settings

    if (options.updateInitialViewSettingsOnly) {
      this.updateInitialSettings(finalSettings)
      return
    }
    await this.runNavigationInQueue(async () => {
      const settingEntries = this.viewSettingsToEntries(finalSettings)

      if (!this.initialViewSettings.length) {
        this.initialViewSettings = settingEntries
      }

      if (!this.navigator) {
        return
      }

      if (!this.lastLocation) {
        this.updateLastLocation(this.navigator.getCurrentLocation())
      }
      const tmpLocation = this.lastLocation

      this.rendition.updateViewSettings(settingEntries)

      if (tmpLocation) {
        await this.gotoLocationThroughNavigator(tmpLocation)
        this.updateLastLocation(tmpLocation, false)
      }
    }, NavigatorTaskName.SetViewSettings)
  }

  protected updateViewSetting(name: SettingName, value: unknown): void {
    const viewSetting: ISettingEntry = { name, value }
    // TODO - it's better to use a Map instead of a List as the type of initialViewSettings
    for (const setting of this.initialViewSettings) {
      if (setting.name === name) {
        setting.value = value
        return
      }
    }

    this.initialViewSettings.push(viewSetting)
  }

  private updateLastLocation(
    location: RendererLocation | null | undefined,
    updateLineLength = true,
  ): void {
    this.lastLocation = location
    if (updateLineLength) {
      this.lastLocationLineEndCfi = location ? this.getLineEndCfi(location) : ''
    }
  }

  private getLineEndCfi(location: RendererLocation): string {
    const range = this.getRangeForLocation(location)
    const iframeDocument =
      this.viewportMethods?.getSpineItemDocumentByHrefOrNull(location.getHref())
    if (!range || !iframeDocument) {
      return ''
    }

    return LocationUtils.getLineEndCfi(range.cloneRange(), iframeDocument)
  }

  protected async gotoLocationThroughNavigator(
    location: RendererLocation,
  ): Promise<void> {
    this.resetZoom()
    await this.navigator.gotoLocation(location)
  }

  protected getViewSettings(): ViewSettings {
    // TODO the result of this method is influenced by the queue
    // for public method we might need to run this in navigationQueue
    // to get the latest ones
    const settingEntries = this.rendition.viewSettings()
    return this.entriesToViewSettings(settingEntries.getAllSettings())
  }

  private viewSettingsToEntries(settings: ViewSettings): ISettingEntry[] {
    const settingEntries = []
    for (const setting in settings) {
      const entry: ISettingEntry = {
        name: setting as SettingName,
        value: settings[setting],
      }
      if (setting === SettingName.SpreadMode) {
        const publication = this.rendition?.getPublication()
        const spreadModeValue = getSpreadModeOrNullForPresentation(
          publication?.metadata?.presentation?.spread || null,
          entry.value,
        )
        if (!spreadModeValue) {
          continue
        }
        entry.value = spreadModeValue
      } else if (
        entry.name === SettingName.FontSize ||
        entry.name === SettingName.MaxColumnWidth ||
        entry.name === SettingName.MinColumnWidth ||
        entry.name === SettingName.ColumnGap
      ) {
        entry.value = parseFloat(entry.value)

        if (entry.name === SettingName.FontSize) {
          const fontOverrideSetting: ISettingEntry = {
            name: SettingName.FontSizeOverride,
            value: 'readium-font-size-on',
          }

          // Disable font size override when value reset to 100% as below
          if (entry.value === 100) {
            fontOverrideSetting.value = 'readium-font-size-off'
          }

          settingEntries.push(fontOverrideSetting)
        }
      } else if (entry.name === SettingName.FontFamily) {
        const fontOverrideSetting: ISettingEntry = {
          name: SettingName.FontOverride,
          value: 'readium-font-on',
        }

        // Toggle Readium font override depending on requested font setting
        if (entry.value === 'default') {
          fontOverrideSetting.value = 'readium-font-off'
        }

        settingEntries.push(fontOverrideSetting)
      }

      settingEntries.push(entry)
    }

    return settingEntries
  }

  private entriesToViewSettings(entries: ISettingEntry[]): ViewSettings {
    const vs: ViewSettings = {}
    for (const entry of entries) {
      if (
        entry.name === SettingName.FontSize ||
        entry.name === SettingName.MaxColumnWidth ||
        entry.name === SettingName.MinColumnWidth ||
        entry.name === SettingName.ColumnGap
      ) {
        vs[entry.name] = entry.value.toString()
      } else {
        vs[entry.name] = entry.value
      }
    }

    return vs
  }

