  /*
   * TODO:
   * Similar to Above, should only return simple Locator
   */
  private async getLocator(
    location: RendererLocation,
    begin = true,
  ): Promise<Locator> {
    // TODO the result of this method is influenced by the queue
    // for public method we might need to run this in navigationQueue
    // to get the latest ones
    const stringUntilLocation = await this.getStringUntil(location, begin)

    const processedResources = this.processedPublication.processedResources

    let totalSizeUntilLocation
    let currentResourceSize

    // TODO: Remove
    if (processedResources) {
      currentResourceSize = this.processedPublication.getResourceSize(
        location.getHref(),
      )

      const resourceIndex = processedResources.findIndex(
        (element) => element.href === location.getHref(),
      )

      const resourcesUtilCurrent = processedResources.slice(0, resourceIndex)

      totalSizeUntilLocation =
        processedResourcesSizeTotal(resourcesUtilCurrent) +
        stringUntilLocation.length
    }

    let pageLocator
    if (
      totalSizeUntilLocation !== undefined &&
      totalSizeUntilLocation !== null
    ) {
      pageLocator = this.processedPublication.getPageLocationAtPosition(
        totalSizeUntilLocation,
      )
    }
    return {
      href: location.getHref(),
      type: location.getMediaType(),
      locations: {
        fragments: location.getFragments(),
        partialCfi: location.getLocation(),
        relativePosition: stringUntilLocation.length,
        position: totalSizeUntilLocation,
      },
      resourceSize: currentResourceSize, // TODO: Remove
      publicationSize: this.processedPublication.publicationSize, // TODO: Remove
      title: pageLocator?.title,
    }
  }

  /**
   * This function gets a string from the beginning of document
   * to the designated location, which can then be degaussed for
   * progression information
   *
   * @param {RendererLocation} location
   * @param {boolean} [begin=true]
   * @returns {string}
   * @memberof Navigator
   * @deprecated use "navigator.getRangeForLocation" with 'import { utils } from "@flowpub/navigator"' utils.location.getStringFromRange instead
   */
  public getStringUntil(location: RendererLocation, begin = true): string {
    const range = this.getRangeForLocation(location)

    if (!range) {
      console.warn('Invalid range supplied. Unable to get text from fragment')
      return ''
    }
    return LocationUtils.getStringFromRange(range, begin)
  }

  /**
   * Checks if two range intersect.
   * Any overlap, including a shared boundary, is considered intersecting.
   * A pair of locators define the start and end of the range.
   * A single locator will be considered a range with length 0.
   * @param a Array containing one or two locators
   * @param b Array containing one or two locators
   * @throws Error Will throw error if locators don't contain enough location information
   */
  public doLocationsIntersect(
    [aStart, aEnd = aStart]: [Locator, Locator?],
    [bStart, bEnd = bStart]: [Locator, Locator?],
  ): boolean {
    return doLocationsIntersect(
      [aStart, aEnd],
      [bStart, bEnd],
      this.processedPublication.processedResources,
    )
  }

  /**
   * Checks if range inner is contained within range outer.
   * Range inner is contained within range outer if and only if the
   * entire range inner is between the start and end of the range outer.
   * A pair of locators defines the start and end of the range.
   * A single locator will be considered a range with length 0.
   * @param outer Array defining the boundaries of outer range
   * @param inner Array defining the boundaries of inner range
   * @param strict if true, the inner range must not intersect the boundary of the outer range
   * @throws Error Will throw error if any range contain locators with different hrefs
   * @deprecated use 'import { utils } from "@flowpub/navigator"' utils.locationComparators.isLocationContained instead
   */
  public isLocationContained(
    [outerStart, outerEnd = outerStart]: [Locator, Locator?],
    [innerStart, innerEnd = innerStart]: [Locator, Locator?],
    strict = false,
  ): boolean {
    return isLocationContained(
      [outerStart, outerEnd],
      [innerStart, innerEnd],
      strict,
      this.processedPublication.processedResources,
    )
  }

  /**
   * Returns the distance between two ranges. 0 means they are intersecting.
   * Negative means the second range is before the first range.
   * @param first Array defining the boundary of the first range
   * @param second Array defining the boundary of the second range
   * @throws Error Will throw error if the ranges are not of the same href
   * @throws Error Will throw error if any range contain locators with different hrefs
   * @deprecated use 'import { utils } from "@flowpub/navigator"' utils.locationComparators.getCharacterOffsetDistance instead
   */
  public getCharacterOffsetDistance(
    [firstStart, firstEnd = firstStart]: [Locator, Locator?],
    [secondStart, secondEnd = secondStart]: [Locator, Locator?],
  ): number {
    return getCharacterOffsetDistance(
      [firstStart, firstEnd],
      [secondStart, secondEnd],
      this.processedPublication.processedResources,
    )
  }

