import { AsyncTaskId, AsyncTaskDescriptionWithId } from '../../types'

import { AsyncTaskStore } from './async-task-store'

export enum AsyncTaskStoreEventName {
  // before add a task into queue
  BeforeTaskAdded = 'BeforeTaskAdded',
  // after a task has been added
  AfterTaskAdded = 'AfterTaskAdded',
  // before the task run
  BeforeNextTaskRun = 'BeforeNextTaskRun',
}

export type AsyncTaskStoreEventId = symbol

export interface AsyncTaskStoreEventBasic<N extends AsyncTaskStoreEventName> {
  /**
   * Unique identifier of the Event
   *
   * @type {AsyncTaskStoreEventId}
   * @memberof AsyncTaskStoreEventBasic
   */
  id: AsyncTaskStoreEventId
  /**
   * Name of the event
   *
   * @type {N}
   * @memberof AsyncTaskStoreEventBasic
   */
  eventName: N
  /**
   * Allows to manipulate with the tasks in queue
   *
   * @type {AsyncTaskStore}
   * @memberof AsyncTaskStoreEventBasic
   */
  asyncTaskStore: AsyncTaskStore
}

export interface AsyncTaskStoreEventWithTaskDescription<
  N extends AsyncTaskStoreEventName,
  R,
  ID extends AsyncTaskId
> extends AsyncTaskStoreEventBasic<N> {
  taskDescriptionWithId: AsyncTaskDescriptionWithId<R, ID>
}

export interface AsyncTaskStoreEventsList {
  /**
   * Describes the task that has been added
   *
   * @type {AsyncTaskStoreEventWithTaskDescription<AsyncTaskStoreEventName.BeforeTaskAdded, unknown, AsyncTaskId>}
   * @memberof AsyncTaskStoreEventsList
   */
  [AsyncTaskStoreEventName.BeforeTaskAdded]: AsyncTaskStoreEventWithTaskDescription<
    AsyncTaskStoreEventName.BeforeTaskAdded,
    unknown,
    AsyncTaskId
  >
  /**
   * Describes the task that should be added
   *
   * @type {AsyncTaskStoreEventWithTaskDescription<AsyncTaskStoreEventName.AfterTaskAdded, unknown, AsyncTaskId>}
   * @memberof AsyncTaskStoreEventsList
   */
  [AsyncTaskStoreEventName.AfterTaskAdded]: AsyncTaskStoreEventWithTaskDescription<
    AsyncTaskStoreEventName.AfterTaskAdded,
    unknown,
    AsyncTaskId
  >
  /**
   * Contains the description of the task which is picked out from the store for execution
   * It might be removed from the store in order to prevent its execution, then another task will be
   * picked out and this event will be fired once again with the description of the new task chosen.
   *
   * @type {(AsyncTaskStoreEventWithTaskDescription<AsyncTaskStoreEventName.BeforeNextTaskRun, unknown, AsyncTaskId>)}
   * @memberof AsyncTaskStoreEventsList
   */
  [AsyncTaskStoreEventName.BeforeNextTaskRun]: AsyncTaskStoreEventWithTaskDescription<
    AsyncTaskStoreEventName.BeforeNextTaskRun,
    unknown,
    AsyncTaskId
  >
}

export type AsyncTaskStoreEventListener<E extends AsyncTaskStoreEventName> = (
  parameter: AsyncTaskStoreEventsList[E],
) => unknown

export type AsyncTaskStoreEventParameter<
  E extends AsyncTaskStoreEventName
> = Omit<AsyncTaskStoreEventsList[E], 'id' | 'eventName'>

export interface AsyncTaskStoreEventEmitterReadOnly {
  addListener<E extends AsyncTaskStoreEventName>(
    eventName: E,
    listener: AsyncTaskStoreEventListener<E>,
  ): void
  removeListener<E extends AsyncTaskStoreEventName>(
    eventName: E,
    listener: AsyncTaskStoreEventListener<E>,
  ): void
}

export interface AsyncTaskStoreEventEmitter
  extends AsyncTaskStoreEventEmitterReadOnly {
  emit<E extends AsyncTaskStoreEventName>(
    eventName: E,
    parameter: AsyncTaskStoreEventParameter<E>,
  ): void
}
