import { Link, Publication } from '@flowpub/webpub-model'

import { PublicationEdge } from './const'

import { Locator } from '.'

export function processedResourcesSizeTotal(
  processedResources: ProcessedResource[],
): number {
  return processedResources
    .map((resource) => resource.textLength)
    .reduce((accumulator, currentValue) => accumulator + currentValue, 0)
}

export interface ProcessedResource {
  href: string
  textLength: number
  textLengthSoFar: number | undefined
}

export class ProcessedPublication {
  public processedResources: ProcessedResource[]
  public readingOrder: Link[]
  public pagePositionList: Locator[]
  public tocPositionList: Locator[] = []

  public get processedResourcesNumber(): number {
    return this.processedResources.length
  }

  constructor(basePublication: Publication) {
    this.processedResources = basePublication['fp:processedResources']
    this.pagePositionList = basePublication['fp:pageListPositionList']
    this.readingOrder = basePublication.readingOrder
    const tocPositionList = basePublication['fp:tocPositionList']
    if (tocPositionList) {
      this.tocPositionList = this.sortLocatorsByPosition(tocPositionList)
    }

    if (!this.processedResources) {
      this.processedResources = []
    }
    let textLengthSoFar = 0
    for (const resource of this.processedResources) {
      resource.textLengthSoFar = textLengthSoFar
      textLengthSoFar += resource.textLength ?? 0
    }
  }

  private sortLocatorsByPosition(locators: Locator[]): Locator[] {
    return [...locators].sort((a, b) => {
      if (a.locations?.position && b.locations?.position) {
        return a.locations.position - b.locations.position
      } else {
        return 0
      }
    })
  }

  /**
   * Get the page number relative to the start of the chapter from a position.
   * @param position
   * @returns page number relative to the start of the chapter or undefined if toc information is not available
   */
  public getPageOfTocItem(position: number): number | undefined {
    const positionPageLocator = this.getPageLocationAtPosition(position)
    const chapterLocator = this.getChapterLocatorAtPosition(position)
    const chapterStartPageLocator = this.getPageLocationAtPosition(
      chapterLocator?.locations?.position || 0,
    )

    if (!positionPageLocator || !chapterStartPageLocator) {
      return
    }

    const positionPageNumber:
      | number
      | undefined = this.pagePositionList.indexOf(positionPageLocator)
    const chapterStartPageNumber:
      | number
      | undefined = this.pagePositionList.indexOf(chapterStartPageLocator)

    if (
      positionPageNumber === undefined ||
      chapterStartPageNumber === undefined
    ) {
      // TODO CYP-1313: log reason for undefined return value
      return
    }

    return positionPageNumber - chapterStartPageNumber + 1
  }

  /**
   * Gets the locator for the toc item that contains the given position.
   * Will return undefined if position is larger than the publication size.
   * @param position
   */
  public getChapterLocatorAtPosition(position: number): Locator | undefined {
    if (position < 0 || position > this.publicationSize) {
      return
    }

    for (let i = 0; i < this.tocPositionList.length - 1; i++) {
      const thisTocLocator = this.tocPositionList[i]
      const thisTocPosition = thisTocLocator.locations?.position || 0
      const nextTocLocator = this.tocPositionList[i + 1]
      const nextTocPosition =
        nextTocLocator?.locations?.position || thisTocPosition
      if (thisTocPosition <= position && position < nextTocPosition) {
        return thisTocLocator
      }
    }

    const lastTocLocator = this.tocPositionList[this.tocPositionList.length - 1]
    const lastTocPosition = lastTocLocator.locations?.position || 0
    if (lastTocPosition <= position) {
      return lastTocLocator
    }
  }

  /**
   * Get the page location object that a position is on.
   *
   * @param position absolute position in the publication
   * @returns Locator object of page which contains given position, or undefined if not found
   */
  public getPageLocationAtPosition(position: number): Locator | undefined {
    if (!this.pagePositionList?.length) {
      return undefined
    }

    // check last page position
    const lastPagePosition = this.pagePositionList[
      this.pagePositionList.length - 1
    ]
    if (
      Number(lastPagePosition.locations?.position) < position &&
      position < this.publicationSize
    ) {
      return lastPagePosition
    }

    for (let i = 0; i < this.pagePositionList.length - 1; i++) {
      // check whether position is in between page i and next page positions
      const pagePosition = this.pagePositionList[i]
      if (Number(pagePosition.locations?.position) > position) {
        // page i position is after position
        continue
      }

      const nextPagePosition = this.pagePositionList[i + 1]
      if (Number(nextPagePosition.locations?.position) > position) {
        // next page position is after position
        return pagePosition
      }
    }
  }

  get publicationSize(): number {
    return processedResourcesSizeTotal(this.processedResources)
  }

  public getResourceSize(href: string): number | undefined {
    for (const resource of this.processedResources) {
      if (resource.href === href) {
        return resource.textLength
      }
    }
  }

  /**
   * Convert a relativePosition of a spine item to absolute position
   *
   * @param relativePosition relative position inside a spine item
   * @param href href of the spine item resource
   * @returns position number if found, undefined if spine item not found
   */
  public relativePositionToPosition(
    relativePosition: number,
    href: string,
  ): number | undefined {
    const sizeUntilHref = this.getSizeUpToResource(href)
    if (sizeUntilHref === undefined) {
      return undefined
    }

    return sizeUntilHref + relativePosition
  }

  /**
   * Generate a Locator object from a position, if possible.
   * Will return undefined if position is larger than the publication size.
   * Locator will contain proper href and relativePosition values.
   *
   * @param position Absolute position in units of characters, i.e., text offset
   * @returns Locator locator object if position is found, with position, relativePosition, and href info
   */
  public absolutePositionToLocator(position: number): Locator | undefined {
    // check very last position in book
    if (this.processedResources.length === 0) {
      return
    }
    const lastResource = this.processedResources[
      this.processedResources.length - 1
    ]
    if (
      lastResource.textLengthSoFar !== undefined &&
      position === lastResource.textLengthSoFar + lastResource.textLength
    ) {
      return this.createLocatorWithPositionInfo(
        lastResource.href,
        position,
        position - lastResource.textLengthSoFar,
      )
    }

    for (const resource of this.processedResources) {
      if (
        resource.textLengthSoFar !== undefined &&
        resource.textLengthSoFar <= position &&
        position < resource.textLengthSoFar + resource.textLength
      ) {
        return this.createLocatorWithPositionInfo(
          resource.href,
          position,
          position - resource.textLengthSoFar,
        )
      }
    }
  }

  /**
   * Creates a locator object with the information provided
   *
   * @param href href of the relevant resource
   * @param position absolute position in the book
   * @param relativePosition relative position in the resource
   * @private
   */
  private createLocatorWithPositionInfo(
    href: string,
    position: number,
    relativePosition: number,
  ): Locator {
    return {
      href,
      type: 'application/xhtml+xml',
      locations: {
        position,
        relativePosition,
      },
    }
  }

  public getSizeUpToResource(href: string): number | undefined {
    let sizeSoFar = 0
    for (const pageLink of this.readingOrder) {
      if (pageLink.href === href) {
        return sizeSoFar
      }

      for (const resource of this.processedResources) {
        if (resource.href === pageLink.href) {
          const resourceSize = resource.textLength
          if (resourceSize === undefined) {
            return undefined
          }

          sizeSoFar += resourceSize
          break
        }
      }
    }
  }

  /**
   * Returns a locator for the edge of the book
   *
   * @param {PublicationEdge} position
   * @returns {Locator}
   * @memberof ProcessedPublication
   */
  public getLocatorForEdge(edge: PublicationEdge): Locator {
    let targetSpineIndexOrNull: number | null = null
    if (edge === PublicationEdge.Start) {
      targetSpineIndexOrNull = 0
    } else if (edge === PublicationEdge.End) {
      targetSpineIndexOrNull = this.processedResourcesNumber - 1
    }
    if (targetSpineIndexOrNull == null) {
      throw new Error('The index of the target spine item is not found')
    }

    const targetHrefOrNull = this.getHrefOrNullBySpineIndex(
      targetSpineIndexOrNull,
    )
    if (!targetHrefOrNull) {
      throw new Error('The anchor of the target spine item is not found')
    }

    let targetOffset = 0
    if (edge === PublicationEdge.End) {
      targetOffset = this.getResourceSize(targetHrefOrNull) ?? 0
    }

    const targetLocator: Locator = {
      href: targetHrefOrNull,
      type: 'application/xhtml+xml',
      locations: {
        relativePosition: targetOffset,
      },
    }

    return targetLocator
  }

  protected getHrefOrNullBySpineIndex(resourceIndex: number): string | null {
    return this.readingOrder[resourceIndex].href ?? null
  }
}
