import {
  SettingName,
  ContentDomEventListener,
  Rendition,
} from '@flowpub/renderer'
import { TouchTracker, Point } from '@flowpub/glue-shared'

import { Navigator } from './navigator'

export interface ClickInfo {
  x: number
  y: number
  pointerType: string
}

interface TapListenerContext {
  viewportElement: HTMLElement
  navigator: Navigator
  rendition: Rendition
}

type ViewportTapListener = (
  event: Event & {
    offsetX: number
    offsetY: number
    pointerType: string
  },
) => void

/**
 * Utility function to normalize pointer event coordinates
 *
 * @param location Location of pointer event
 * @param maxima Upper bounds used to normalize pointer event location
 *
 *
 * @example
 * // returns { x: 0.01, y: 0.99}
 */
export const normalizeLocation = (location: Point, maxima: Point): Point => {
  return {
    x: Number((location.x / maxima.x).toFixed(2)),
    y: Number((1 - location.y / maxima.y).toFixed(2)), // Note: y axis of DOM click events is inverted
  }
}

/**
 * Class to register tap listeners
 *
 * Takes a context object from the navigator, along with a callback
 * to call with location coordinates once they are computed by
 * the listeners
 * @param context Values from the navigator used to set up listeners
 * @param callback Callback to be called on locations computed by listeners
 */
export class TapListener {
  private navigator: Navigator

  private colGap: number | undefined

  private clipperClientWidth: number

  private viewportClipperWidth: number

  private viewportElement: HTMLElement

  private touchTracker = new TouchTracker(25 * 2, 800)

  private callback: (clickInfo: ClickInfo) => void
  private rendition: Rendition

  public constructor(
    context: TapListenerContext,
    callback: (clickInfo: ClickInfo) => void,
  ) {
    this.navigator = context.navigator
    this.rendition = context.rendition
    this.colGap = this.rendition
      .viewSettings()
      .getSetting(SettingName.ColumnGap)

    this.viewportElement = context.viewportElement
    this.callback = callback
  }

  private setPointerEvents(event: MouseEvent): void {
    if (event.type === 'pointerdown') {
      this.touchTracker.onPointerDown(event)
    }

    if (event.type === 'pointermove') {
      this.touchTracker.onPointerMove(event)
    }

    if (event.type === 'pointerup') {
      this.touchTracker.onPointerUp(event)
    }
  }

  private shouldFireCallback(): boolean {
    if (!this.touchTracker.isDone()) {
      return false
    }

    if (this.touchTracker.pressedLong()) {
      return false
    }

    if (this.touchTracker.movedLong()) {
      return false
    }

    return true
  }

  /**
   * gets the position of the click relative to the viewport element
   * @param event
   */
  private getClickOffsetRelativeToViewportElement(event: PointerEvent): Point {
    const offset = { x: event.offsetX, y: event.offsetY }
    const target = event.target as HTMLElement
    if (target !== this.viewportElement) {
      const bounds = target.getBoundingClientRect()
      const viewBounds = this.viewportElement.getBoundingClientRect()
      offset.x += bounds.x - viewBounds.x
    }
    return offset
  }

  /**
   * Create a viewport tap listener
   *
   * Take a pointer event, computes normalized location of event
   * and calls callback on those coordinates
   * @param event Pointer event
   */
  public createViewportTapListener(): ViewportTapListener {
    const viewportTapListener = (
      event: Event & {
        offsetX: number
        offsetY: number
        pointerType: string
      },
    ): void => {
      const tapEvent = event as PointerEvent

      this.setPointerEvents(tapEvent)

      // the spine item's containing divs cover the viewport,
      // so they are likely the ones that received the click
      const clickCoordinates = this.getClickOffsetRelativeToViewportElement(
        tapEvent,
      )

      const clickLocation = normalizeLocation(clickCoordinates, {
        x: this.viewportElement.clientWidth,
        y: this.viewportElement.clientHeight,
      })

      if (this.shouldFireCallback()) {
        this.callback({
          x: clickLocation.x,
          y: clickLocation.y,
          pointerType: tapEvent.pointerType,
        })
      }
    }

    return viewportTapListener
  }

  /**
   * Create an iframe tap listener
   */
  public createIFrameTapListener(): ContentDomEventListener {
    /**
     * Takes an index and a Hammer event, computes normalized location
     * of event relative to the viewport, and calls callback function
     * on those coordinates
     * @param index Index of the spine item that received the click event
     * @param event dom event
     */
    const iframeTapListener = (index: number, event: Event): void => {
      const tapEvent = event as PointerEvent

      this.setPointerEvents(tapEvent)

      // get newest value of viewport clipper client width
      this.clipperClientWidth = this.rendition.viewport.getClipContainerWidth()

      this.viewportClipperWidth =
        this.clipperClientWidth - (this.colGap as number)

      // fxl pages could be scaled
      const spineItemView = this.rendition.viewport.getSpineItemView(index)

      const scale = spineItemView ? spineItemView.getScale() : 1
      const iframeOffset = spineItemView
        ? spineItemView.getIframeBoundingBox().x
        : 0

      // convert from iframe context to window context, then add iframe position relative to viewport
      const absoluteLocationX =
        tapEvent.clientX * scale +
        (iframeOffset - this.viewportElement.offsetLeft)

      const clickCoordinates = {
        x: absoluteLocationX,
        y: tapEvent.clientY * scale,
      }

      const clickLocation = normalizeLocation(clickCoordinates, {
        x: this.viewportElement.clientWidth,
        y: this.viewportElement.clientHeight,
      })

      if (this.shouldFireCallback()) {
        this.callback({
          x: clickLocation.x,
          y: clickLocation.y,
          pointerType: tapEvent.pointerType,
        })
      }
    }

    return iframeTapListener
  }

  /**
   * Register Viewport and IFrame listeners
   */
  public async init(): Promise<void> {
    const viewportTapListener = this.createViewportTapListener()
    const iframeTapListener = this.createIFrameTapListener()

    this.viewportElement.addEventListener('pointerdown', viewportTapListener)
    this.viewportElement.addEventListener('pointerup', viewportTapListener)

    await this.navigator.addContentDomEventListener(
      'pointerdown',
      iframeTapListener,
      { properties: ['timestamp', 'clientX', 'clientY', 'pointerType'] },
    )

    await this.navigator.addContentDomEventListener(
      'pointerup',
      iframeTapListener,
      { properties: ['clientX', 'clientY', 'pointerType'] },
    )
  }
}
