import { Caller } from '@flowpub/glue-rpc'
import { Callback, PanEventHandler, PanEvent } from '@flowpub/glue-shared'
import {
  ContentEventListenerContext,
  ContentEventManager,
  ContentEventSource,
  SpineItemView,
} from '@flowpub/renderer'

export const PanHandlingMessageAddListener = 'ADD_PAN_LISTENER'
export const PanHandlingMessageRemoveListener = 'REMOVE_PAN_LISTENER'
export const VelocityNormalizeValue = 1000

class PanHandling extends Caller {
  public async addPanListener(listener: Callback): Promise<number> {
    return this.call(PanHandlingMessageAddListener, [], listener)
  }

  public async removePanListener(listenerID: number): Promise<void> {
    return this.call(PanHandlingMessageRemoveListener, [listenerID])
  }
}

export enum PinchState {
  NotPinching = 1,
  Pinching,
  HangingPinch,
}

export type PanEventListener = (e: PanEvent) => void

export interface PanSettings {
  swipeVelocityThreshold: number
  panPageTurnThreshold: number
}

interface PanEventListenerContext extends ContentEventListenerContext {
  callback: PanEventListener
}

class PanEventSource implements ContentEventSource {
  public spineItemIndex = -1

  private eventSource: PanHandling

  public constructor(win: Window) {
    this.eventSource = new PanHandling('pan-handling', win)
  }
  public async addListener(listener: PanEventListenerContext): Promise<number> {
    const eventSourceCallback = (result: [PanEvent]): void => {
      const event = result[0]
      event.index = this.spineItemIndex
      listener.callback(event)
    }
    return await this.eventSource.addPanListener(eventSourceCallback)
  }

  public async removeListener(
    listener: PanEventListenerContext,
  ): Promise<void> {
    const listenerID = listener.listenerIDs[this.spineItemIndex]
    await this.eventSource.removePanListener(listenerID)
  }
}

export class PanManager extends ContentEventManager {
  private _panStart: PanEvent

  private _pinchState: PinchState = PinchState.NotPinching

  private _panningDisabled = false

  private _startPinchDist = 0
  private _lastPinchDist = 0

  private _lastPinchXCenter = 0
  private _lastPinchYCenter = 0

  private _lastScreenX = 0

  private _swipeThreshold = 300
  private _snapThreshold = 0.5

  public makeEventSource(
    win: Window,
    _spineItemIndex: number,
  ): ContentEventSource {
    return new PanEventSource(win)
  }

  public addPanListener(callback: PanEventListener): void {
    const newListener: PanEventListenerContext = {
      callback,
      listenerIDs: {},
      removed: false,
    }

    this.eventListeners.push(newListener)
  }

  public static convertIframeToWindowPositionX(
    clientX: number,
    spineItemView: SpineItemView,
  ): number {
    const iframeRect = spineItemView.getIframeBoundingBox()
    const iframeOffsetHeight = spineItemView.getIframeOffsetHeight()

    const absoluteScale = iframeRect.height / iframeOffsetHeight
    const positionX = absoluteScale * clientX + iframeRect.left

    return positionX
  }

  public static convertIframeToWindowPositionY(
    clientY: number,
    spineItemView: SpineItemView,
  ): number {
    const iframeRect = spineItemView.getIframeBoundingBox()
    const iframeOffsetHeight = spineItemView.getIframeOffsetHeight()

    const absoluteScale = iframeRect.height / iframeOffsetHeight
    return absoluteScale * clientY + iframeRect.top
  }

  public processPan(panEvent: PanEvent, spineItemView?: SpineItemView): void {
    const {
      start,
      pinch,
      screenX1,
      screenY1,
      screenX2,
      screenY2,
      numberOfTouches,
      clientX1,
      clientY1,
      clientX2,
      clientY2,
    } = panEvent

    if (numberOfTouches !== undefined) {
      this.updatePinchState(numberOfTouches)
    }

    if (
      pinch &&
      screenY1 !== undefined &&
      screenX2 !== undefined &&
      screenY2 !== undefined &&
      clientX2 !== undefined &&
      clientY2 !== undefined &&
      spineItemView
    ) {
      const clientYCenter = (clientY1 + clientY2) / 2
      this.lastPinchYCenter = PanManager.convertIframeToWindowPositionY(
        clientYCenter,
        spineItemView,
      )

      const clientXCenter = (clientX1 + clientX2) / 2
      this.lastPinchXCenter = PanManager.convertIframeToWindowPositionX(
        clientXCenter,
        spineItemView,
      )

      const pinchDist =
        ((screenX1 - screenX2) ** 2 + (screenY1 - screenY2) ** 2) ** 0.5

      if (start) {
        this.startPinchDist = pinchDist
        this.lastPinchDist = pinchDist
        return
      }

      this.lastPinchDist = pinchDist
      return
    }

    if (start && !pinch) {
      this.lastScreenX = screenX1
      return
    }
  }

  /**
   * PINCH STATE TRANSITION TABLE
   *
   *              |0            |1            |> 1          |
   * NotPinching  |             |             |Pinching     |
   * Pinching     |NotPinching  |HangingPinch |             |
   * HangingPinch |NotPinching  |             |             |
   *
   * @param numberOfTouches {number}
   */
  public updatePinchState(numberOfTouches: number): void {
    /**
     * panning should be disabled while pinching/hanging,
     * also on events that transition us from
     * pinching/hanging to not-pinching
     */
    this._panningDisabled = false

    switch (this._pinchState) {
      case PinchState.HangingPinch: {
        if (numberOfTouches === 0) {
          this._pinchState = PinchState.NotPinching
        }
        this._panningDisabled = true
        break
      }
      case PinchState.Pinching: {
        if (numberOfTouches === 1) {
          this._pinchState = PinchState.HangingPinch
        } else if (numberOfTouches === 0) {
          this._pinchState = PinchState.NotPinching
        }
        this._panningDisabled = true
        break
      }
      case PinchState.NotPinching: {
        if (numberOfTouches > 1) {
          this._pinchState = PinchState.Pinching
          this._panningDisabled = true
        }
        break
      }
    }
  }

  public getPinchParams(): { startPinchDist: number; lastPinchDist: number } {
    return {
      startPinchDist: this.startPinchDist,
      lastPinchDist: this.lastPinchDist,
    }
  }

  public getHorizontalSwipeVelocity(
    panStart: PanEvent,
    panEnd: PanEvent,
  ): number {
    const { screenX1: x1, timeStamp: t1 } = panStart
    const { screenX1: x2, timeStamp: t2 } = panEnd
    const velX = this.calculateXVelocity(x1, x2, t1 as number, t2 as number)
    return velX
  }

  public getSwipeVelocity(panStart: PanEvent, panEnd: PanEvent): number {
    const { screenX1: x1, screenY1: y1, timeStamp: t1 } = panStart
    const { screenX1: x2, screenY1: y2, timeStamp: t2 } = panEnd

    const velocity = this.calculateVelocity(
      x1,
      y1 as number,
      x2,
      y2 as number,
      t1 as number,
      t2 as number,
    )
    return velocity
  }

  public getSwipeHorizontalDistance(
    panStart: PanEvent,
    panEnd: PanEvent,
  ): number {
    const { screenX1: x1 } = panStart
    const { screenX1: x2 } = panEnd

    // result is positive when finger moves right, and vice-versa
    return x2 - x1
  }

  public calculateVelocity(
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    t1: number,
    t2: number,
  ): number {
    const direction = x2 - x1 >= 0 ? 1 : -1

    const distance = ((x2 - x1) ** 2 + (y2 - y1) ** 2) ** 0.5
    const time = t2 - t1

    const velocity = distance / time

    return Math.round(direction * velocity * VelocityNormalizeValue)
  }

  public calculateXVelocity(
    x1: number,
    x2: number,
    t1: number,
    t2: number,
  ): number {
    const distance = x2 - x1
    const time = t2 - t1

    const velocity = distance / time

    return Math.round(velocity * VelocityNormalizeValue)
  }

  public getGestureParams(): PanSettings {
    return {
      swipeVelocityThreshold: this._swipeThreshold,
      panPageTurnThreshold: this._snapThreshold,
    }
  }

  public setGestureParams(settings: PanSettings): void {
    this._swipeThreshold = settings.swipeVelocityThreshold
    this._snapThreshold = settings.panPageTurnThreshold
  }

  public get startPinchDist(): number {
    return this._startPinchDist
  }
  public set startPinchDist(value) {
    this._startPinchDist = value
  }

  public get panningDisabled(): boolean {
    return this._panningDisabled
  }

  public get pinchState(): PinchState {
    return this._pinchState
  }

  public get lastPinchDist(): number {
    return this._lastPinchDist
  }
  public set lastPinchDist(value) {
    this._lastPinchDist = value
  }

  public get lastPinchXCenter(): number {
    return this._lastPinchXCenter
  }
  public set lastPinchXCenter(value) {
    this._lastPinchXCenter = value
  }

  public get lastPinchYCenter(): number {
    return this._lastPinchYCenter
  }
  public set lastPinchYCenter(value) {
    this._lastPinchYCenter = value
  }

  public get lastScreenX(): number {
    return this._lastScreenX
  }

  public set lastScreenX(value) {
    this._lastScreenX = value
  }

  public get panStart(): PanEvent {
    return this._panStart
  }
  public set panStart(value: PanEvent) {
    this._panStart = value
  }
}

export class ViewportPanListener {
  private viewportElement: HTMLElement
  private panEventHandler: PanEventHandler

  public constructor(
    viewportElement: HTMLElement,
    callback: (event: PanEvent) => void,
  ) {
    this.viewportElement = viewportElement
    this.panEventHandler = new PanEventHandler(callback)
    this.attachListeners()
  }

  private attachListeners(): void {
    this.viewportElement.addEventListener(
      'touchstart',
      this.panEventHandler.prePanCheckEvent,
    )
    this.viewportElement.addEventListener(
      'touchend',
      this.panEventHandler.endEvent,
    )
    this.viewportElement.addEventListener(
      'touchmove',
      this.panEventHandler.moveEvent,
    )
  }
}
