import { SnapDirection } from '@flowpub/renderer'

import { PanningState, PanningStateName, PanningContext } from '../types'
import { NavigatorError } from '../../types'
import { NavigatorErrorType } from '../../const'

export class PanningScreenTransition implements PanningState {
  static state: PanningStateName = PanningStateName.ScreenTransition
  public get name(): PanningStateName {
    return PanningScreenTransition.state
  }
  private isActive = false
  constructor(private readonly context: PanningContext) {}
  public onPan(): void {
    if (this.isActive) {
      // if "handleEventAndChangeStep" is in progress
      return
    }

    this.isActive = true
    this.handleEventAndChangeStep()
  }

  private async handleEventAndChangeStep(): Promise<void> {
    try {
      await this.runScreenChange()
    } finally {
      this.context.changeState(PanningStateName.Inactive)
    }
  }

  private async runScreenChange(): Promise<void> {
    const context = this.context
    const direction: SnapDirection | null = context.activeSnapDirectionOrNull

    if (direction == null) {
      throw new Error('The direction of screen transition should be defined')
    }

    context.enableNavigatorScreenTransitionAnimation()
    context.disableNavigatorClearSelectionSetting()
    if (direction === SnapDirection.Prev || direction === SnapDirection.Next) {
      context.resetNavigatorZoomLevel()
    }
    try {
      await this.translateScreen(direction)
    } finally {
      await this.enableNavigatorClearSelectionSetting()
    }
  }

  private async translateScreen(direction: SnapDirection): Promise<void> {
    try {
      await this.context.snapNavigator(direction)
    } catch (err) {
      // TODO - we might need to add a system for handling custom inner errors in future
      if (
        (err as NavigatorError).flowpubNavigatorErrorType !==
        NavigatorErrorType.RejectedByQueueHandler
      ) {
        throw err
      }
    }
  }

  private async enableNavigatorClearSelectionSetting(): Promise<void> {
    await new Promise<void>((res) => {
      setTimeout(() => {
        try {
          this.context.enableNavigatorClearSelectionSetting()
        } finally {
          res()
        }
      })
    })
  }
}
