import {
  PageLabelVisibilityHandlerFabricByType,
  PageLabelVisibilityHandler,
  PageLabelVisibilityHandlerConstructor,
} from './types'
import { PageLabelVisibilityHandlerTypeName } from './enum'
import { PageLabelVisibilityHandlerFixed } from './page-label-visibility-handler-fxl'
import { PageLabelVisibilityHandlerReflowable } from './page-label-visibility-handler-reflowable'

const pageLabelVisibilityHandlerConstructors = [
  PageLabelVisibilityHandlerFixed,
  PageLabelVisibilityHandlerReflowable,
] as const

export const pageLabelVisibilityHandlerFabricByType: PageLabelVisibilityHandlerFabricByType = <
  HT extends PageLabelVisibilityHandlerTypeName
>(
  pageLabelVisibilityHandlerTypeName: HT,
): PageLabelVisibilityHandler<HT> => {
  const PageLabelVisibilityHandlerConstructorOrUndefined = pageLabelVisibilityHandlerConstructors.find(
    (Constructor) =>
      Constructor.pageLabelVisibilityHandlerFixedLayoutBookTypeName ===
      pageLabelVisibilityHandlerTypeName,
  ) as PageLabelVisibilityHandlerConstructor<HT> | undefined
  if (!PageLabelVisibilityHandlerConstructorOrUndefined) {
    throw new Error(
      `There is no constructor for the type ${pageLabelVisibilityHandlerTypeName} found`,
    )
  }
  return new PageLabelVisibilityHandlerConstructorOrUndefined()
}
