import { EventHandling } from '@flowpub/glue-modules'

import type { ContentLoader } from './content-loader'

export interface ContentEventListenerContext {
  listenerIDs: { [index: number]: number }
  removed: boolean
}

export interface ContentEventSource {
  spineItemIndex: number
  removeListener(listener: ContentEventListenerContext): Promise<void>
  addListener(listener: ContentEventListenerContext): Promise<number>
}

export abstract class ContentEventManager {
  /**
   * This value can be set globally:
   *   `import { ContentEventManager } from '@flowpub/renderer';`
   *   `ContentEventManager.DefaultTaskTimeoutMs = new_value`
   * However this won't have an effect on instances that have
   * already been instantiated. For those ones `setTaskTimeoutMs`
   * method should be used.
   *
   * @static
   * @memberof ContentEventManager
   */
  static DefaultTaskTimeoutMs = 1000
  /**
   * A limit on time of execution of async tasks.
   *
   * @protected
   * @memberof ContentEventManager
   */
  protected taskTimeoutMs = ContentEventManager.DefaultTaskTimeoutMs
  protected contentLoader: ContentLoader

  protected eventListeners: ContentEventListenerContext[] = []

  protected eventSources: [HTMLIFrameElement, ContentEventSource][] = []

  private runningTaskOrNull: Promise<void> | null = null

  public constructor(loader: ContentLoader) {
    this.contentLoader = loader

    this.contentLoader.addContentLoadedListener(
      async (
        spineItemIndex: number,
        iframe: HTMLIFrameElement,
      ): Promise<void> => {
        const eventSource = this.makeEventSource(
          iframe.contentWindow as Window,
          spineItemIndex,
        )
        eventSource.spineItemIndex = spineItemIndex

        const eventSources = [...this.eventSources, [iframe, eventSource]] as [
          HTMLIFrameElement,
          ContentEventSource,
        ][]

        this.eventSources = eventSources.sort((a, b) => {
          return a[1].spineItemIndex - b[1].spineItemIndex
        })
        while (this.runningTaskOrNull) {
          await this.runningTaskOrNull
        }
        try {
          await this.runAsyncTask(this.updateContentEventsInternal(eventSource))
        } catch (err) {
          console.error(err)
          throw err
        }
      },
    )

    this.contentLoader.addContentUnloadedListener((spineItemIndex: number) => {
      this.eventSources = this.eventSources.filter((value) => {
        return value[1].spineItemIndex !== spineItemIndex
      })
    })
  }

  /**
   * Set a limit on each individual task execution time run
   * by the instance.
   * TODO - CYP-1308 refactor/add tests
   *
   * @param {number} timeoutMs
   * @memberof ContentEventManager
   */
  public setTaskTimeoutMs(timeoutMs: number): void {
    this.taskTimeoutMs = timeoutMs
  }

  public async updateContentEvents(): Promise<void> {
    while (this.runningTaskOrNull) {
      await this.runningTaskOrNull
    }

    const promises = this.eventSources.map((value) => {
      return this.updateContentEventsInternal(value[1])
    })
    const promisesPending = Promise.all(promises)

    await this.runAsyncTask(promisesPending)

    this.eventListeners = this.eventListeners.filter((value) => {
      return !value.removed
    })
  }

  // TODO - if there are many places that require usage of a queue,
  // do refactoring with usage of AsyncQueue
  protected async runAsyncTask(task: Promise<any>): Promise<void> {
    // runningTaskOrNull should not throw an error
    this.runningTaskOrNull = task.catch()
    let timeoutTimer: number | undefined
    try {
      await Promise.race([
        task,
        new Promise((_, rej) => {
          timeoutTimer = setTimeout(
            this.rejectAsyncTaskByTimeout,
            this.taskTimeoutMs,
            rej,
          )
        }),
      ])
    } finally {
      if (timeoutTimer) {
        clearTimeout(timeoutTimer)
      }
      this.runningTaskOrNull = null
    }
  }

  private rejectAsyncTaskByTimeout = (rej: (err: Error) => void): void => {
    rej(
      new Error(
        'ContentEventManager:runAsyncTask: The async task has timed out',
      ),
    )
  }

  private async updateContentEventsInternal(
    eventSource: ContentEventSource,
  ): Promise<void> {
    for (const listener of this.eventListeners) {
      await eventSource.removeListener(listener)
      if (!listener.removed) {
        listener.listenerIDs[
          eventSource.spineItemIndex
        ] = await eventSource.addListener(listener)
      }
    }
  }

  protected abstract makeEventSource(
    win: Window,
    spineItemIndex: number,
  ): ContentEventSource
}

export type ContentDomEventListener = (index: number, event: Event) => void

interface ContentDomEventListenerContext extends ContentEventListenerContext {
  eventName: string
  callback: ContentDomEventListener
  opts?: ContentDomEventListenerOptions
}

export interface ContentDomEventListenerOptions
  extends AddEventListenerOptions {
  preventDefault?: boolean
  stopPropagation?: boolean
  stopImmediatePropagation?: boolean
  properties?: string[]
  target?: string
}

export class ContentDomEventSource implements ContentEventSource {
  public spineItemIndex = -1

  private eventSource: EventHandling

  constructor(win: Window) {
    this.eventSource = new EventHandling('event-handling', win)
  }

  public async addListener(
    listener: ContentEventListenerContext,
  ): Promise<number> {
    const domEventListener = listener as ContentDomEventListenerContext

    const eventSourceCallback: EventListener = (event) => {
      domEventListener.callback(this.spineItemIndex, event)
    }

    return await this.eventSource.addEventListener(
      domEventListener.eventName,
      eventSourceCallback,
      domEventListener.opts,
    )
  }

  public async removeListener(
    listener: ContentEventListenerContext,
  ): Promise<void> {
    const listenerID = listener.listenerIDs[this.spineItemIndex]
    await this.eventSource.removeEventListener(listenerID)
  }
}

export class ContentDomEventManager extends ContentEventManager {
  protected makeEventSource(win: Window): ContentEventSource {
    return new ContentDomEventSource(win)
  }

  public addContentDomEventListener(
    spaceSeparatedEventNames: string,
    callback: ContentDomEventListener,
    opts?: ContentDomEventListenerOptions,
  ): void {
    const eventNames = spaceSeparatedEventNames.split(' ')
    for (let i = 0; i < eventNames.length; i += 1) {
      const eventName = eventNames[i]
      const newListener: ContentDomEventListenerContext = {
        eventName,
        callback,
        opts,
        listenerIDs: {},
        removed: false,
      }

      this.eventListeners = [...this.eventListeners, newListener]
    }
  }

  public removeContentDomEventListener(
    spaceSeparatedEventNames: string,
    callback: ContentDomEventListener,
  ): void {
    const eventNames = spaceSeparatedEventNames.split(' ')
    for (let i = 0; i < eventNames.length; i += 1) {
      const eventName = eventNames[i]
      // "this.eventListeners" array might be processed by an async method,
      // therefore it shouldn't be changed in place but copied and change items
      // in this copy
      this.eventListeners = this.eventListeners.map((value) => {
        let listener = value as ContentDomEventListenerContext
        if (
          listener.eventName === eventName &&
          listener.callback === callback
        ) {
          listener = {
            ...listener,
            removed: true,
          }
        }
        return listener
      })
    }
  }
}
