import {
  PageLabelVisibilityHandler,
  VisiblePageLabelsInfoListener,
  ContentViewProperties,
  VisiblePageLabelsInfoListenerParameters,
  PageLabelInfoByVisibilityHandlerTypeName,
  PageLabelVisibilityHandlerFixedLayoutBookTypeName,
} from './types'
import { PageLabelVisibilityHandlerTypeName } from './enum'

export class PageLabelVisibilityHandlerFixed<
  P extends PageLabelInfoByVisibilityHandlerTypeName<
    PageLabelVisibilityHandlerFixedLayoutBookTypeName
  >
>
  implements
    PageLabelVisibilityHandler<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName
    > {
  static pageLabelVisibilityHandlerFixedLayoutBookTypeName: PageLabelVisibilityHandlerFixedLayoutBookTypeName =
    PageLabelVisibilityHandlerTypeName.Fixed
  protected firstVisibleSpineItemIndex = 0
  protected lastVisibleSpineItemIndex = 0
  private visiblePageLabelsInfoListenersSet: Set<
    VisiblePageLabelsInfoListener<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName,
      P
    >
  > = new Set()
  private isEnabled = false

  public enable(): void {
    this.isEnabled = true
  }

  public disable(): void {
    this.isEnabled = false
    this.emitEmptyPageLabelsVisibleInfo()
  }

  public addVisiblePageLabelsInfoListener(
    listener: VisiblePageLabelsInfoListener<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName,
      P
    >,
  ): void {
    this.visiblePageLabelsInfoListenersSet.add(listener)
  }
  public removeVisiblePageLabelsInfoListener(
    listener: VisiblePageLabelsInfoListener<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName,
      P
    >,
  ): void {
    this.visiblePageLabelsInfoListenersSet.delete(listener)
  }

  public setContentViewProperties(
    contentViewOffset: ContentViewProperties<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName
    >,
  ): void {
    const {
      firstVisibleSpineItemIndex,
      lastVisibleSpineItemIndex,
    } = contentViewOffset
    this.firstVisibleSpineItemIndex = firstVisibleSpineItemIndex
    this.lastVisibleSpineItemIndex = lastVisibleSpineItemIndex
  }

  public updatePageLabelsVisibility(pageLabelsInfo: P[]): void {
    if (!this.isEnabled) {
      return
    }

    const pageLabelsVisibleOnCurrentScreen: P[] = this.getInfoOfVisiblePageLabels(
      pageLabelsInfo,
    )
    const contentViewProperties: ContentViewProperties<PageLabelVisibilityHandlerFixedLayoutBookTypeName> = this.getContentViewProperties()
    const visiblePageLabelsInfoListenerParameters: VisiblePageLabelsInfoListenerParameters<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName,
      P
    > = {
      visiblePageLabelsInfo: pageLabelsVisibleOnCurrentScreen,
      contentViewProperties,
    }

    this.emitPageLabelsVisibleInfo(visiblePageLabelsInfoListenerParameters)
  }

  protected getContentViewProperties(): ContentViewProperties<
    PageLabelVisibilityHandlerFixedLayoutBookTypeName
  > {
    const { firstVisibleSpineItemIndex, lastVisibleSpineItemIndex } = this
    return {
      firstVisibleSpineItemIndex,
      lastVisibleSpineItemIndex,
    }
  }

  protected getInfoOfVisiblePageLabels(pageLabelsInfo: P[]): P[] {
    if (!pageLabelsInfo.length) {
      return []
    }

    const { firstVisibleSpineItemIndex, lastVisibleSpineItemIndex } = this

    return pageLabelsInfo.filter(({ spineItemIndex }: P): boolean => {
      return (
        spineItemIndex >= firstVisibleSpineItemIndex &&
        spineItemIndex <= lastVisibleSpineItemIndex
      )
    })
  }

  protected emitPageLabelsVisibleInfo(
    eventParameters: VisiblePageLabelsInfoListenerParameters<
      PageLabelVisibilityHandlerFixedLayoutBookTypeName,
      P
    >,
  ): void {
    this.visiblePageLabelsInfoListenersSet.forEach((listener) =>
      listener(eventParameters),
    )
  }

  protected emitEmptyPageLabelsVisibleInfo() {
    this.emitPageLabelsVisibleInfo({
      visiblePageLabelsInfo: [],
      contentViewProperties: this.getContentViewProperties(),
    })
  }
}
