import path from 'path-browserify'
import { Publication, FpBlobData, BlobMap } from '@flowpub/webpub-model'

/**
 * BlobHandler class handling blob data in publication. It is only used when blobData exists in manifest.
 * Need to check blobData in publication before creating a new instance of this class.
 * @export
 * @class BlobHandler
 * @throws Will throw an error if no blob data in the manifest.
 */
export class BlobHandler {
  private readonly blobData: FpBlobData
  private resolvedBlobMapArray: BlobMap[] = []
  private readonly publication: Publication
  constructor(publication: Publication) {
    if (!publication.blobData) throw Error('No blobData in the manifest')
    this.publication = publication
    this.blobData = publication.blobData
    this.createResolvedBlobMapArray()
  }

  /**
   * Build a blob map array with resolved paths
   * @private
   * @memberof BlobHandler
   */
  private createResolvedBlobMapArray(): void {
    for (const blobItem of this.blobData.blobs) {
      const blobMapResolveditem = Object.assign({}, blobItem)
      blobMapResolveditem.blobPath = this.buildPath(
        this.blobData.basePath,
        blobItem.blobPath,
      )
      this.resolvedBlobMapArray.push(blobMapResolveditem)
    }
  }

  /**
   * Build resolved path. If no base path or blob path is absolute, then use the blob path.
   * @private
   * @param {(string | undefined)} basePath
   * @param {string} blobPath
   * @return {string} resolved path
   * @memberof BlobHandler
   */
  private buildPath(basePath: string | undefined, blobPath: string): string {
    if (!basePath || path.isAbsolute(blobPath)) {
      return blobPath
    }
    return path.join(basePath, blobPath)
  }

  /**
   * Return blob raw data
   * @return {FpBlobData}
   * @memberof BlobHandler
   */
  getBlobData(): FpBlobData {
    return this.blobData
  }

  /**
   * Return blob map array with resolved paths
   * @return {BlobMap[]}
   * @memberof BlobHandler
   */
  getBlobsArray(): BlobMap[] {
    return this.resolvedBlobMapArray
  }

  /**
   * Return blob full path by spine href
   * @param {string} href
   * @return {(string | undefined)}
   * @memberof BlobHandler
   */
  getBlobPathForSpineHref(href: string): string | undefined {
    const resolvedBlobData = this.resolvedBlobMapArray.find(
      (blobItem: BlobMap) => {
        return blobItem.spineItemHref === href
      },
    )
    return resolvedBlobData?.blobPath
  }

  /**
   * Return blob full path by spine index
   * @param {(string | number)} spineIndex
   * @return {string}
   * @memberof BlobHandler
   */
  getBlobPathForSpineIndex(spineIndex: string | number): string | undefined {
    const index =
      typeof spineIndex === 'string' ? parseInt(spineIndex) : spineIndex
    if (isNaN(index) || index >= this.publication.spine.length || index < 0)
      return
    return this.getBlobPathForSpineHref(this.publication.spine[index].href)
  }
}
