// Readium Locator
// https://readium.org/architecture/models/locators/

import type {
  Viewport,
  ApplyResourcesToDocument,
  ApplyResourcesToDocumentAsync,
  SpineDocumentLoadingInterceptor,
  IFrameContentInjector,
  IFrameDocumentPostProcessor,
  XHTMLParser,
  InjectCSSAsync,
} from '@flowpub/renderer'

import { NavigatorErrorType } from './const'
import {
  PageLabelVisibilityHandler,
  PageLabelVisibilityHandlerTypeName,
} from './page-label-visibility-handler'
import { AssistiveSelection } from './assistive-selection/assistive-selection'

export interface Locator {
  href: string
  type: string
  title?: string
  locations?: Location
  text?: Text

  // Flowpub Extension
  resourceSize?: number
  publicationSize?: number
}
export interface Location {
  fragments?: string[]
  progression?: number
  position?: number
  totalProgression?: number

  // HTML Extension
  partialCfi?: string

  // Flowpub Extension
  relativePosition?: number
}
export interface Text {
  after?: string
  before?: string
  highlight?: string
}

// Selection Constructs
export interface SelectionInfo {
  content: string
  start: Locator
  end: Locator
  rects: Rect[]
  highlights: string[]
  href: string | null
  spineItemIndex?: number
  highlightOverlappingByPosition: string[]
}

export interface Rect {
  x: number
  y: number
  width: number
  height: number
}

export enum ThemeHighlightColor {
  Day = '#477651',
  Sepia = '#524338',
  Night = '#83ADEC',
}

export enum PageLabelSide {
  Right = 'RIGHT',
  Left = 'LEFT',
}

export interface PageLabelView extends PageLabelInfoWithPosition {
  side: PageLabelSide
}

export type Spread = 'auto' | 'single' | 'double'

export interface NavigatorError<
  T extends NavigatorErrorType = NavigatorErrorType,
> extends Error {
  /**
   * An inner type of an error. Should be handled
   * properly in all layers of the application.
   *
   * @type {NavigatorErrorType}
   * @memberof NavigatorError
   */
  readonly flowpubNavigatorErrorType: T
}

export enum PageLabelLocationType {
  Anchor,
  CFI,
  Offset,
  None,
}

export type PageLabelInfo = {
  type: PageLabelLocationType
  location: string | number
  label: string
  spineItemIndex: number
}

export type PageLabelInfoWithPosition = PageLabelInfo & {
  position: Rect
  timestampMs: number
}

export enum PageLabelOnScreenSide {
  Left = 'LEFT',
  Right = 'RIGHT',
}

export type PageLabelInfoWithOnScreenSide = PageLabelInfoWithPosition & {
  onScreenSide: PageLabelOnScreenSide
  pageLabelWidth: number
}

export type VisibleRangeUpdate = {
  actualStartOffset: number
  actualEndOffset: number
  spineItemIndex: number
  isFirstVisible: boolean
}

export type PageLabelsVisibleInfoListener = (
  visiblePageLabelsInfo: PageLabelInfo[],
) => void

export type PageLabelVisibilityHandlerEventListenerMethods = Pick<
  PageLabelVisibilityHandler<PageLabelVisibilityHandlerTypeName>,
  'addVisiblePageLabelsInfoListener' | 'removeVisiblePageLabelsInfoListener'
>

export interface PageLabelsVisibleInfoEventEmitter {
  /**
   * Listen for page labels visibility info updates
   *
   * @param {(Pick<PageLabelVisibilityHandler, 'addVisiblePageLabelsInfoListener' | 'removeVisiblePageLabelsInfoListener'>)} pageLabelVisibilityHandler
   * @memberof NavigatorVisiblePageLabelsInfoEventEmitter
   */
  attachToPageLabelVisibilityHandler(
    pageLabelVisibilityHandler: PageLabelVisibilityHandlerEventListenerMethods,
  ): void
  /**
   * Listen for an event that is fired whenever page labels
   * visible on the screen are changed
   *
   * @param {PageLabelsVisibleInfoListener} listener
   * @memberof PageLabelManagerEventsEmitter
   */
  addVisiblePageLabelsInfoListener(
    listener: PageLabelsVisibleInfoListener,
  ): void
  removeVisiblePageLabelsInfoListener(
    listener: PageLabelsVisibleInfoListener,
  ): void
}

export interface PageLabelManagerEventEmitter {
  addPageLabelsVisibilityFlagListener(
    listener: (arePageLabelsVisible: boolean) => void,
  ): void
  addListenerPageLabelsPositionsUpdate(
    listener: (pageLabelsInfo: PageLabelInfoWithPosition[]) => void,
  ): void
  addPageLabelsVisibleRangeUpdatedListener(
    listener: (visibleRange: VisibleRangeUpdate) => void,
  ): void
}

export enum HighlightType {
  CFI,
  Offset,
}

export interface Highlight {
  type: HighlightType
  start: string | number
  end: string | number
  spineIndex: number
  color: string
  id: string
  duration: number
}

export interface SingleHighlightInfo {
  id: string
  rects: Rect[]
}

export interface SelectedHighlightInfo {
  touchPoint: Rect
  highlights: SingleHighlightInfo[]
}

export interface SelectionData {
  content: string
  start: {
    cfi: string
    offset: number
  }
  end: {
    cfi: string
    offset: number
  }
  rects: Rect[]
  highlights: SelectedHighlightInfo
  highlightOverlappingByPosition: string[]
  href: string | null
}

export interface ViewSettings {
  [index: string]: string
}

export interface HighlightInfo {
  id: string
  startLocator: Locator
  endLocator: Locator
  color: string
  duration?: number
}

export type ListenerContentContainerScroll = (e: Event) => void
export type SetUpEnvironmentBeforeStartResizingCallback =
  () => void | Promise<void>

export type OpenPublicationOptions = {
  /**
   * A locator specifies which page to open as the first page
   *
   * @type {Locator}
   */
  locator?: Locator
  /**
   * View settings that should be applied before opening
   * a publication
   *
   * @type {ViewSettings}
   */
  viewSettings?: ViewSettings
  /**
   * A function that intercepts and handles each
   * request for loading spine item XHTML content
   *
   * @type {SpineDocumentLoadingInterceptor}
   */
  spineDocumentLoadingInterceptor?: SpineDocumentLoadingInterceptor
  /**
   * This function will be used to set the HTML
   * code as the IFrame document.
   * The default injection will be replaced
   * with this.
   *
   * @type {IFrameContentInjector}
   */
  iframeContentInjector?: IFrameContentInjector
  /**
   * Can process an iframe right before it'll be shown
   * to the user.
   *
   * @type {IFrameDocumentPostProcessor}
   */
  iframeDocumentPostProcessor?: IFrameDocumentPostProcessor
  /**
   * An implementation of the interface that will be used by
   * IFrameLoader to parse HTML code and make an instance of
   * HTMLDocument from it.
   *
   * @type {XHTMLParser}
   */
  iframeLoaderXHTMLParser?: XHTMLParser
  /**
   * This tool will be used to add JS/CSS files onto the
   * document of a spine item iframe.
   * E.g JS bundles will be added as <script ... /> tags
   * and CSS files as <link rel="stylesheet" .../>
   *
   * @type {ApplyResourcesToDocument | ApplyResourcesToDocumentAsync}
   */
  injectAssetsToSpineDocument?:
    | ApplyResourcesToDocument
    | ApplyResourcesToDocumentAsync

  /**
   * Inject CSS to spine iframe
   *
   * @type {InjectCSSAsync}
   * @memberof IFrameLoaderDependencies
   */
  injectCSS?: InjectCSSAsync

  /**
   * !WARNING - this option hasn't been tested well yet.
   * TODO - CYP-1308 refactor/add tests
   *
   * A timeout in milliseconds for the execution time of methods
   * of instances:
   * ContentDomEventManager
   * ContentLinkEventManager
   * SelectionEventManager
   * SelectionChangingEventManager
   * AssistiveSelectionEventManager
   * WheelEventManager
   * HighlightManager
   * TabFocusManager
   * PanManager
   * PageLabelManager
   *
   * @type {number}
   * @waning
   */
  contentManagerTimeoutMs?: number
  /**
   * Option to set the margin of the parents of an image to 0.
   * Resolves bugs related to large height images.
   * default true for safari based browser and false otherwise
   * Bugs:
   * On iOS images can become split over two or more pages (CYP-1316).
   * When using DRM images can be offset in between pages (CYP-1325).
   */
  resetImageParentMarginTop?: boolean
}

export type OpenPublicationOptionsOrJsonObject = OpenPublicationOptions | string

export type ViewportMethods = Pick<
  Viewport,
  | 'getContainerWidth'
  | 'setPrefetchPercent'
  | 'getSpineItemDocumentByHrefOrNull'
  | 'getDocumentsOfVisibleSpineItems'
  | 'setUnloadSpineItemHandler'
>

export type AssistiveSelectionMethods = Pick<
  AssistiveSelection,
  | 'selectFirstWordOnPage'
  | 'toggleActivePageForSelection'
  | 'selectNextWordInDirection'
  | 'expandSelectionInDirection'
  | 'exitAssistiveSelectionMode'
>

export interface SetViewSettingsOptions {
  applyImmediately: boolean
  updateInitialViewSettingsOnly: boolean
}
