export enum SelectionDirectionKey {
  ArrowRight = 'ArrowRight',
  ArrowLeft = 'ArrowLeft',
  ArrowUp = 'ArrowUp',
  ArrowDown = 'ArrowDown',
}

export interface PageInfo {
  spineIndex: number
  startCfi: string
  endCfi: string
}

export interface AssistiveSelectionInfo {
  pages: PageInfo[]
  curIndex: number
}

export type FirstPageStart = {
  spineIndexStart: number
  viewStartCfi: string | null
}

export type SecondPageEnd = {
  spineIndexEnd: number
  viewEndCfi: string | null
}

export type ViewBoundaries = FirstPageStart & SecondPageEnd
