import { Rendition, Navigator } from '@flowpub/renderer'

import { SelectionEventManager } from '../selection-handling'

import {
  AssistiveSelectionInfo,
  FirstPageStart,
  PageInfo,
  SecondPageEnd,
  SelectionDirectionKey,
  ViewBoundaries,
} from './types'
import { AssistiveSelectionEventManager } from './assistive-selection-event-manager'

export class AssistiveSelection {
  constructor(
    private rendition: Rendition,
    private rendererNavigator: Navigator,
    private assistiveSelectionEventManager: AssistiveSelectionEventManager,
    private selectionEventManager: SelectionEventManager,
  ) {}

  private assistiveSelectionInfo: AssistiveSelectionInfo = {
    pages: [],
    curIndex: 0,
  }

  /**
   * Breaks what is visible into pages if needed, then finds the most left
   * visible spine and selects the first word on that page
   *
   * @param secondPageOffset - offset of the second page in a two-page
   * reflowable layout. We need this to properly calculate the second page
   * rect for this layout
   */
  public async selectFirstWordOnPage(secondPageOffset: number): Promise<void> {
    const isDoublePageSpread = this.isDoublePageSpread()
    const viewBoundaries = await this.getCurrentViewBoundaries()

    if (viewBoundaries === null) {
      return
    }

    const pages = await this.getPagesForSpread(
      isDoublePageSpread,
      viewBoundaries,
      secondPageOffset,
    )

    if (!pages || !pages.length) {
      throw new Error('Nothing to select')
    }

    const assistiveSelectionInfo = {
      curIndex: 0,
      pages,
    }
    this.setAssistiveSelectionInfo(assistiveSelectionInfo)

    const firstPageInfo = this.assistiveSelectionInfo.pages[0]

    if (firstPageInfo === undefined) {
      throw new Error('Nothing to select')
    }

    this.assistiveSelectionEventManager.selectFirstWordOnPage(firstPageInfo)
  }

  /**
   * Selects next word in direction in Assistive Selection mode
   *
   * @param eventKey
   */
  public selectNextWordInDirection(eventKey: SelectionDirectionKey): void {
    this.assistiveSelectionEventManager.selectNextWordInDirection(eventKey)
  }

  /**
   * Expands the selection in direction in Assistive Selection mode
   *
   * @param eventKey
   */
  public expandSelectionInDirection(eventKey: SelectionDirectionKey): void {
    this.assistiveSelectionEventManager.expandSelectionInDirection(eventKey)
  }

  public exitAssistiveSelectionMode(): void {
    this.selectionEventManager.clearSelection()
    this.assistiveSelectionEventManager.exitAssistiveSelectionMode()
  }

  /**
   * Change active page for selection to the next/previous page in double spread
   * If single spread, reinit the selection back to the first word on the page
   */
  public toggleActivePageForSelection(): void {
    const assistiveSelectionInfo = this.assistiveSelectionInfo
    let nextIndex

    if (assistiveSelectionInfo.pages.length === 1) {
      nextIndex = assistiveSelectionInfo.curIndex
    } else {
      nextIndex = assistiveSelectionInfo.curIndex === 0 ? 1 : 0
    }

    const pageInfo = assistiveSelectionInfo.pages[nextIndex]

    if (!pageInfo) {
      return
    }

    // Clear existing selection on current spine
    this.exitAssistiveSelectionMode()

    assistiveSelectionInfo.curIndex = nextIndex

    this.assistiveSelectionEventManager.selectFirstWordOnPage(pageInfo)
  }

  /**
   * Get boundaries for current view - spine indices and CFIs
   * pointing to the start and end of the view.
   */
  private async getCurrentViewBoundaries(): Promise<ViewBoundaries | null> {
    const startPosition = this.rendition.viewport.getStartPosition()
    const endPosition = this.rendition.viewport.getEndPosition()

    // Get spine indices for screen start/end
    const spineIndexStart = startPosition?.spineItemIndex
    const spineIndexEnd = endPosition?.spineItemIndex

    if (spineIndexStart === undefined || spineIndexEnd === undefined) {
      return null
    }

    const viewStartCfi = await this.getScreenBeginCfiOrNull()
    const viewEndCfi = await this.getScreenEndCfiOrNull()

    if (!viewStartCfi && !viewEndCfi) {
      return null
    }

    return {
      spineIndexStart,
      spineIndexEnd,
      viewStartCfi,
      viewEndCfi,
    }
  }

  private setAssistiveSelectionInfo(
    assistiveSelectionInfo: AssistiveSelectionInfo,
  ): void {
    this.assistiveSelectionInfo = assistiveSelectionInfo
  }

  private async getPagesForSpread(
    isDoublePageSpread: boolean,
    viewBoundaries: ViewBoundaries,
    secondPageOffset: number,
  ): Promise<PageInfo[] | null> {
    const { spineIndexStart, viewEndCfi, viewStartCfi } = viewBoundaries

    let pages: PageInfo[] | null

    if (!isDoublePageSpread) {
      pages = this.getPagesForSingleSpread(
        spineIndexStart,
        viewStartCfi,
        viewEndCfi,
      )
    } else {
      pages = await this.getPagesForDoubleSpread(
        viewBoundaries,
        secondPageOffset,
      )
    }

    return pages
  }

  private getPagesForSingleSpread(
    spineIndexStart: number,
    viewStartCfi: string | null,
    viewEndCfi: string | null,
  ): PageInfo[] | null {
    if (!viewStartCfi || !viewEndCfi) {
      return null
    }

    return [
      {
        spineIndex: spineIndexStart,
        startCfi: viewStartCfi,
        endCfi: viewEndCfi,
      },
    ]
  }

  private async getPagesForDoubleSpread(
    viewBoundaries: ViewBoundaries,
    secondPageOffset: number,
  ): Promise<PageInfo[] | null> {
    const {
      spineIndexStart,
      spineIndexEnd,
      viewEndCfi,
      viewStartCfi,
    } = viewBoundaries

    const pages: PageInfo[] = []
    const isFixedLayout = this.rendition.isFixedLayout()

    /**
     * For reflowable double page, the second page start offset might be
     * not 0 if a single spine is displayed. Therefore we need offset
     * to calculate the second page start
     */
    const secondPageOffsetLayout = isFixedLayout ? 0 : secondPageOffset

    const firstPageStart: FirstPageStart = {
      spineIndexStart,
      viewStartCfi,
    }

    // Calculate first page if needed
    const firstPageInDoubleSpread = await this.getFirstPageForDoubleSpreadIfExists(
      firstPageStart,
    )

    if (firstPageInDoubleSpread) {
      pages.push(firstPageInDoubleSpread)
    }

    const secondPageEnd: SecondPageEnd = {
      spineIndexEnd,
      viewEndCfi,
    }

    // Calculate second page if needed
    const secondPageInDoublePageSpread = await this.getSecondPageForDoubleSpreadIfExists(
      secondPageEnd,
      secondPageOffsetLayout,
    )

    if (secondPageInDoublePageSpread) {
      pages.push(secondPageInDoublePageSpread)
    }

    if (!pages.length) {
      return null
    }

    return pages
  }

  private async getFirstPageForDoubleSpreadIfExists(
    firstPageStart: FirstPageStart,
  ): Promise<PageInfo | null> {
    const { spineIndexStart, viewStartCfi } = firstPageStart

    if (!viewStartCfi) {
      return null
    }

    // We have the start - calculate the end
    const firstPageEndCfi = await this.getFirstPageEndCfiOrNull()

    if (!firstPageEndCfi) {
      return null
    }

    return {
      spineIndex: spineIndexStart,
      startCfi: viewStartCfi,
      endCfi: firstPageEndCfi,
    }
  }

  private async getSecondPageForDoubleSpreadIfExists(
    secondPageEnd: SecondPageEnd,
    secondPageOffsetLayout: number,
  ): Promise<PageInfo | null> {
    const { spineIndexEnd, viewEndCfi } = secondPageEnd

    if (!viewEndCfi) {
      return null
    }

    // We have the end - calculate the start
    const secondPageStartCfi = await this.getSecondPageStartCfiOrNull(
      secondPageOffsetLayout,
    )

    if (!secondPageStartCfi) {
      return null
    }

    return {
      spineIndex: spineIndexEnd,
      startCfi: secondPageStartCfi,
      endCfi: viewEndCfi,
    }
  }

  private isDoublePageSpread(): boolean {
    if (this.rendition.isFixedLayout()) {
      const startPos = this.rendition.viewport.getStartPosition()
      const endPos = this.rendition.viewport.getEndPosition()

      const startSpineHref = startPos?.spineItemIndex
      const endSpineHref = endPos?.spineItemIndex

      return startSpineHref !== endSpineHref
    }

    return this.rendition.getNumOfPagesPerSpread() === 2
  }

  private async getScreenBeginCfiOrNull(): Promise<string | null> {
    return await this.rendererNavigator.getScreenBeginCfiOrNull()
  }

  private async getScreenEndCfiOrNull(): Promise<string | null> {
    return await this.rendererNavigator.getScreenEndCfiOrNull()
  }

  private async getFirstPageEndCfiOrNull(): Promise<string | null> {
    return await this.rendererNavigator.getFirstPageEndCfiOrNull()
  }

  /**
   * Get second page start CFI
   *
   * @param columnWidth - used as an offset of the second page in a two-page
   * reflowable layout. We need this to properly calculate the second page
   * rect for this layout
   */
  private async getSecondPageStartCfiOrNull(
    columnWidth = 0,
  ): Promise<string | null> {
    return await this.rendererNavigator.getSecondPageStartCfiOrNull(columnWidth)
  }
}
