import { AsyncTaskStoreEventName } from '../utils/async-tasks-storing-and-handling'
import { NavigatorTaskName } from '../const'
import { AsyncTaskId } from '../utils/types'
import { AsyncTaskDescriptionStrict } from '../utils/types/async-task'
import {
  AsyncTaskStore,
  AsyncTaskStoreEventsList,
} from '../utils/async-tasks-storing-and-handling/types'

import { QueueEventsHandlerAbstract } from './queue-events-handler-abstract'
import {
  NavigatorQueueEventHandlerFabric,
  NavigatorQueueEventHandlerFabricParameters,
} from './types'

export class QueueScreenNavigationEventsHandler extends QueueEventsHandlerAbstract {
  public get supportedTaskNames(): NavigatorTaskName[] {
    return [NavigatorTaskName.NextScreen, NavigatorTaskName.PreviousScreen]
  }

  constructor(parameters: NavigatorQueueEventHandlerFabricParameters) {
    super(parameters)

    this.handleEventAfterTaskAdded = this.handleEventAfterTaskAdded.bind(this)
    this.setEventsListeners()
  }

  protected setOrUnsetEventsListeners(
    method: 'addListener' | 'removeListener',
  ): void {
    const asyncTaskStoreEventEmitter = this.asyncTaskStoreEventEmitter
    asyncTaskStoreEventEmitter[method](
      AsyncTaskStoreEventName.AfterTaskAdded,
      this.handleEventAfterTaskAdded,
    )
  }

  protected filterTasksWithOppositeDirectionOfNavigation<
    T extends AsyncTaskDescriptionStrict<unknown>
  >(
    taskNameFromEvent: NavigatorTaskName,
    taskDescriptionsSupported: T[],
    asyncTaskStore: AsyncTaskStore,
  ): T[] {
    return taskDescriptionsSupported.filter(
      ({ name: taskName, id: taskId }): boolean => {
        if (taskName === taskNameFromEvent) {
          return true
        }
        this.rejectTaskById(
          taskId,
          asyncTaskStore,
          `${taskName}::Rejected by "QueueScreenNavigationEventsHandler:filterTasksWithOppositeDirectionOfNavigation" rule`,
        )
        return false
      },
    )
  }

  protected keepOnlyLastThreeTasks<
    T extends AsyncTaskDescriptionStrict<unknown>
  >(taskDescriptionsSupported: T[], asyncTaskStore: AsyncTaskStore): T[] {
    const timestampTaskIdMap = new Map<number, AsyncTaskId>()

    taskDescriptionsSupported.forEach(
      ({ id: taskId, timestampMs: taskTimestamp }) => {
        timestampTaskIdMap.set(taskTimestamp, taskId)
      },
    )

    const lastThreeTimestamps: number[] = Array.from(timestampTaskIdMap.keys())
      .sort(
        (timestamp1: number, timestamp2: number): number =>
          timestamp1 - timestamp2,
      )
      .slice(0, 2)

    if (!lastThreeTimestamps.length) {
      return taskDescriptionsSupported
    }
    return taskDescriptionsSupported.filter(
      ({ id: taskId, name: taskName, timestampMs: taskTimestamp }): boolean => {
        if (
          lastThreeTimestamps.includes(taskTimestamp) &&
          timestampTaskIdMap.get(taskTimestamp) === taskId
        ) {
          return true
        }
        this.rejectTaskById(
          taskId,
          asyncTaskStore,
          `${taskName}::Rejected by "QueueScreenNavigationEventsHandler:keepOnlyLastThreeTasks" rule`,
        )
        return false
      },
    )
  }

  protected handleEventAfterTaskAdded(
    event: AsyncTaskStoreEventsList[AsyncTaskStoreEventName.AfterTaskAdded],
  ) {
    if (!this.isEventSupported(event)) {
      return
    }

    const { asyncTaskStore, taskDescriptionWithId } = event
    const { name } = taskDescriptionWithId
    const taskIds = asyncTaskStore.getAllStoredTasksIds()
    const taskDescriptionsOrNulls = taskIds.map(
      (taskId: AsyncTaskId): AsyncTaskDescriptionStrict<unknown> | null =>
        asyncTaskStore.getTaskDescriptionOrNullById(taskId),
    )
    const taskDescriptionsSupported: AsyncTaskDescriptionStrict<
      unknown
    >[] = this.filterSupportedTaskDescriptionsExcludingNull(
      taskDescriptionsOrNulls,
    )
    const taskWithTheSameDirectionOfNavigation: AsyncTaskDescriptionStrict<
      unknown
    >[] = this.filterTasksWithOppositeDirectionOfNavigation(
      name as NavigatorTaskName,
      taskDescriptionsSupported,
      asyncTaskStore,
    )
    this.keepOnlyLastThreeTasks(
      taskWithTheSameDirectionOfNavigation,
      asyncTaskStore,
    )
  }
}

export const queueScreenNavigationEventsHandlerFabric: NavigatorQueueEventHandlerFabric = (
  parameters: NavigatorQueueEventHandlerFabricParameters,
): QueueScreenNavigationEventsHandler => {
  return new QueueScreenNavigationEventsHandler(parameters)
}
