import { Caller } from '@flowpub/glue-rpc'
import {
  ContentEventListenerContext,
  ContentEventManager,
  ContentEventSource,
} from '@flowpub/renderer'

import { getEventSourceForSpineItemOrNull } from '../utils/get-event-source-for-spine-item'

import { PageInfo, SelectionDirectionKey } from './types'

export const SelectFirstWordOnPage = 'SELECT_FIRST_WORD_ON_PAGE'
export const SelectNextWordInDirection = 'SELECT_NEXT_WORD_IN_DIRECTION'
export const ExpandSelectionInDirection = 'EXPAND_SELECTION_IN_DIRECTION'
export const ExitAssistiveSelectionMode = 'EXIT_ASSISTIVE_SELECTION_MODE'

class AssistiveSelectionHandling extends Caller {
  public async selectFirstWordOnPage(
    startCfi: string,
    endCfi: string,
  ): Promise<void> {
    return this.call(SelectFirstWordOnPage, [startCfi, endCfi])
  }

  public async selectNextWordInDirection(
    eventKey: SelectionDirectionKey,
  ): Promise<void> {
    return this.call(SelectNextWordInDirection, [eventKey])
  }

  public async expandSelectionInDirection(
    eventKey: SelectionDirectionKey,
  ): Promise<void> {
    return this.call(ExpandSelectionInDirection, [eventKey])
  }

  public async exitAssistiveSelectionMode(): Promise<void> {
    return this.call(ExitAssistiveSelectionMode, [])
  }
}

class AssistiveSelectionEventSource implements ContentEventSource {
  public spineItemIndex = -1

  private eventSource: AssistiveSelectionHandling

  public constructor(win: Window) {
    this.eventSource = new AssistiveSelectionHandling(
      'assistive-selection-handling',
      win,
    )
  }

  public async addListener(
    _listener: ContentEventListenerContext,
  ): Promise<number> {
    return 0
  }

  public async removeListener(
    _listener: ContentEventListenerContext,
  ): Promise<void> {
    // Empty function
  }

  public async selectFirstWordOnPage(
    startCfi: string,
    endCfi: string,
  ): Promise<void> {
    await this.eventSource.selectFirstWordOnPage(startCfi, endCfi)
  }

  public async selectNextWordInDirection(
    eventKey: SelectionDirectionKey,
  ): Promise<void> {
    await this.eventSource.selectNextWordInDirection(eventKey)
  }

  public async expandSelectionInDirection(
    eventKey: SelectionDirectionKey,
  ): Promise<void> {
    await this.eventSource.expandSelectionInDirection(eventKey)
  }

  public async exitAssistiveSelectionMode(): Promise<void> {
    await this.eventSource.exitAssistiveSelectionMode()
  }
}

export class AssistiveSelectionEventManager extends ContentEventManager {
  private spineIndexOrUndefined: number | undefined

  public makeEventSource(win: Window): ContentEventSource {
    return new AssistiveSelectionEventSource(win)
  }

  public selectFirstWordOnPage(pageInfo: PageInfo): void {
    const { spineIndex, startCfi, endCfi } = pageInfo

    this.spineIndexOrUndefined = spineIndex

    const selectionES = getEventSourceForSpineItemOrNull<
      AssistiveSelectionEventSource
    >(spineIndex, this.eventSources)

    if (selectionES) {
      selectionES.selectFirstWordOnPage(startCfi, endCfi)
    }
  }

  public selectNextWordInDirection(eventKey: SelectionDirectionKey): void {
    if (this.spineIndexOrUndefined === undefined) {
      return
    }

    const selectionES = getEventSourceForSpineItemOrNull<
      AssistiveSelectionEventSource
    >(this.spineIndexOrUndefined, this.eventSources)

    if (selectionES) {
      selectionES.selectNextWordInDirection(eventKey)
    }
  }

  public expandSelectionInDirection(eventKey: SelectionDirectionKey): void {
    if (this.spineIndexOrUndefined === undefined) {
      return
    }

    const selectionES = getEventSourceForSpineItemOrNull<
      AssistiveSelectionEventSource
    >(this.spineIndexOrUndefined, this.eventSources)

    if (selectionES) {
      selectionES.expandSelectionInDirection(eventKey)
    }
  }

  public exitAssistiveSelectionMode(): void {
    if (this.spineIndexOrUndefined === undefined) {
      return
    }

    const selectionES = getEventSourceForSpineItemOrNull<
      AssistiveSelectionEventSource
    >(this.spineIndexOrUndefined, this.eventSources)

    if (selectionES) {
      selectionES.exitAssistiveSelectionMode()
    }
  }
}
