import { Location as RendererLocation } from '@flowpub/renderer'

import { Locator } from '..'

/**
 * Returns a RendererLocation object given a Locator.
 * If provided with offsetUpToSpine then the RendererLocation will also contain a relativePosition, if the provided locator contained a position value
 *
 * @param locator
 * @param offsetUpToSpine absolute position value of the start of the spine item of the locator
 */
export function locatorToRendererLocation(
  locator: Locator,
  offsetUpToSpine?: number,
): RendererLocation {
  const { locations, type, href } = locator

  if (!locations) {
    throw new Error('Bad Locator: "locations" should not be empty')
  }

  const { partialCfi, fragments } = locations
  let relativePosition = locations.relativePosition
  if (relativePosition === undefined || relativePosition === null) {
    const position = locations.position
    if (
      position !== undefined &&
      position !== null &&
      offsetUpToSpine !== undefined
    ) {
      relativePosition = position - offsetUpToSpine
    }
  }

  if (partialCfi == undefined && relativePosition == undefined) {
    throw new Error(
      'Bad Locator: "partialCfi" and "relativePosition" should not be empty',
    )
  }

  const location = new RendererLocation(
    partialCfi ?? '',
    type,
    href,
    fragments ?? [],
    relativePosition,
  )
  return location
}
