import { imageCopyGetter } from './image-copy-getter'
import { imageCopyProcessor } from './image-copy-processor'
import { ImageCopyTrackerImpl } from './image-copy-tracker'
import { originalImagesCollector } from './original-images-collector'
import type {
  ImageCopyTracker,
  ImageCopyTrackerConstructor,
  ImageCopyTrackerConstructorParameters,
} from './types'

/**
 * Instantiates ImageCopyTracker interface using a given constructor
 * or a default one.
 *
 * @export
 * @param {ImageCopyTrackerConstructor} [Constructor=ImageCopyTrackerImpl]
 * @return {ImageCopyTracker}
 */
export function createImageCopyTrackerDefaultImpl(
  Constructor: ImageCopyTrackerConstructor = ImageCopyTrackerImpl,
): ImageCopyTracker {
  const parameters: ImageCopyTrackerConstructorParameters = {
    imageCollector: originalImagesCollector,
    imageCopyGetter,
    imageCopyProcessor,
  }
  return new Constructor(parameters)
}
