import {
  AsyncTaskDescription,
  AsyncTaskDescriptionWithId,
  AsyncTaskId,
} from '../types'
import { NavigatorErrorType } from '../../const'

import {
  AsyncTaskRejectionByQueueHandlerError,
  AsyncTaskRejectionByTimeoutError,
  AsyncTaskRejectionErrorFabric,
  AsyncTaskStorage,
} from './types'
import {
  AsyncTaskRunner,
  AsyncTaskRunnerFabric,
  AsyncTaskRunnerFabricParameters,
} from './types/async-task-runner'

type RejectCurrentTaskCallback = (
  error: AsyncTaskRejectionByQueueHandlerError | Error,
) => void

export class AsyncTaskRunnerImpl implements AsyncTaskRunner {
  private readonly storage: AsyncTaskStorage

  private taskRunningDescriptionOrNull: AsyncTaskDescriptionWithId<
    unknown
  > | null = null
  private rejectCurrentTaskCallbackOrNull: RejectCurrentTaskCallback | null
  private asyncTaskRejectionErrorFabric: AsyncTaskRejectionErrorFabric<
    NavigatorErrorType.RejectedByTimeout
  >

  constructor(parameters: AsyncTaskRunnerFabricParameters) {
    const { storage, asyncTaskRejectionErrorFabric } = parameters
    this.storage = storage
    this.asyncTaskRejectionErrorFabric = asyncTaskRejectionErrorFabric
  }

  public async runTaskById(
    taskPendingId: AsyncTaskId,
    timeoutMs: number,
    beforeFinishCallback?: () => void,
  ): Promise<unknown> {
    this.throwIfTaskRunningExists()

    const taskDescription: AsyncTaskDescriptionWithId<
      unknown,
      typeof taskPendingId
    > = this.getTaskDescriptionFromStorageById(taskPendingId)

    this.removeTaskFromStorageById(taskPendingId)

    let errorOrNull: Error | null = null
    let result: unknown

    try {
      this.setTaskRunningDescriptionOrNull(taskDescription)
      const taskPending = taskDescription.fabric()
      const taskPendingWithTimeLimit: Promise<unknown> = this.runPromiseWithTimeout(
        taskPending,
        timeoutMs,
      )

      result = await this.runCurrentTaskAndSetRejectCurrentTaskCallback(
        taskPendingWithTimeLimit,
      )
      // https://stackoverflow.com/questions/64452484/how-can-i-safely-access-caught-error-properties-in-typescript
    } catch (err) {
      errorOrNull = err instanceof Error ? err : new Error('Unknown error')
    }

    this.unsetCurrentTask()
    this.runBeforeFinishCallbackInTryCatch(beforeFinishCallback)
    if (errorOrNull) {
      taskDescription.onError(errorOrNull)
      throw errorOrNull
    }
    taskDescription.onResolve(result)
    return result
  }

  public rejectCurrentTask(
    error: AsyncTaskRejectionByQueueHandlerError | Error,
  ): void {
    this.rejectTaskRunningIfExists(error)
    this.unsetCurrentTask()
  }

  protected rejectTaskByDescription(
    taskDescription: AsyncTaskDescription<unknown>,
    errorOrNull: Error,
  ): void {
    taskDescription.onError(errorOrNull)
  }

  protected throwIfTaskRunningExists(): void {
    if (this.taskRunningDescriptionOrNull) {
      throw new Error('There is already exists a task running')
    }
  }

  protected rejectTaskRunningIfExists(error: Error): void {
    this.rejectCurrentTaskCallbackOrNull?.(error)
  }

  protected setTaskRunningDescriptionOrNull(
    taskPendingDescription: AsyncTaskDescriptionWithId<unknown>,
  ): void {
    this.taskRunningDescriptionOrNull = taskPendingDescription
  }

  protected unsetTaskRunningDescription(): void {
    this.taskRunningDescriptionOrNull = null
  }

  protected setRejectCurrentTaskCallback(
    rejectCurrentTaskCallback: RejectCurrentTaskCallback,
  ): void {
    this.rejectCurrentTaskCallbackOrNull = rejectCurrentTaskCallback
  }

  protected unsetRejectCurrentTaskCallback(): void {
    this.rejectCurrentTaskCallbackOrNull = null
  }

  protected unsetCurrentTask(): void {
    this.unsetTaskRunningDescription()
    this.unsetRejectCurrentTaskCallback()
  }

  protected runBeforeFinishCallbackInTryCatch(
    beforeFinishCallback?: () => void,
  ): void {
    try {
      beforeFinishCallback?.()
    } catch (err) {
      console.error(err)
    }
  }

  protected createRejectionByTimeoutError(): AsyncTaskRejectionByTimeoutError {
    return this.asyncTaskRejectionErrorFabric(
      'Timed-out',
      NavigatorErrorType.RejectedByTimeout,
    )
  }

  protected async runPromiseWithTimeout<R>(
    promisePending: Promise<R>,
    timeoutMs: number,
  ): Promise<R> {
    let timer: ReturnType<typeof setTimeout> | undefined = undefined
    const timeoutPending: Promise<void> = new Promise((_res, rej) => {
      const rejectionByTimeoutError = this.createRejectionByTimeoutError()
      timer = setTimeout(() => rej(rejectionByTimeoutError), timeoutMs)
    })
    const result: R | void = await Promise.race([
      promisePending,
      timeoutPending,
    ]).finally(() => {
      if (timer) {
        clearTimeout(timer)
      }
    })
    return result as R
  }

  protected removeTaskFromStorageById(taskId: AsyncTaskId): void {
    this.storage.removeTaskById(taskId)
  }

  protected getTaskDescriptionFromStorageById<ID extends AsyncTaskId>(
    taskPendingId: ID,
  ): AsyncTaskDescriptionWithId<unknown, ID> {
    const taskDescription = this.storage.getTaskOrNullById(taskPendingId)
    if (!taskDescription) {
      throw new Error(
        `Description is not found by the task identifier ${taskPendingId.toString()}`,
      )
    }
    return taskDescription
  }

  protected runCurrentTaskAndSetRejectCurrentTaskCallback<R>(
    taskRunning: Promise<R>,
  ): Promise<R> {
    const rejectTaskPromise = new Promise<void>((_res, rej) => {
      this.setRejectCurrentTaskCallback(rej)
    })
    return Promise.race([taskRunning, rejectTaskPromise]) as Promise<R>
  }
}

export const asyncTaskRunnerFabric: AsyncTaskRunnerFabric = (
  parameters: AsyncTaskRunnerFabricParameters,
): AsyncTaskRunner => {
  const asyncTaskRunner: AsyncTaskRunner = new AsyncTaskRunnerImpl(parameters)
  return asyncTaskRunner
}
