import { AsyncTaskDescriptionWithId, AsyncTaskId } from '../types'

import { AsyncTaskStorage } from './types'

type AsyncTasksDescriptionsMap<
  R,
  AsyncTask extends AsyncTaskDescriptionWithId<R> = AsyncTaskDescriptionWithId<
    R
  >
> = Map<AsyncTask['id'], AsyncTask>

export class AsyncTaskStorageImpl implements AsyncTaskStorage {
  public get isEmpty(): boolean {
    const isAnyTaskInStorage = Boolean(this.tasksDescriptions.size)
    return !isAnyTaskInStorage
  }
  private tasksDescriptions: AsyncTasksDescriptionsMap<any> = new Map()
  public addTask<R>(taskDescription: AsyncTaskDescriptionWithId<R>): void {
    const { id: taskId } = taskDescription
    this.tasksDescriptions.set(taskId, taskDescription)
  }
  public getAllStoredTasksIds(): AsyncTaskId[] {
    const array: AsyncTaskId[] = Array.from(this.tasksDescriptions.keys())
    return array
  }
  public getTaskOrNullById<ID extends AsyncTaskId>(
    id: ID,
  ): AsyncTaskDescriptionWithId<unknown, ID> | null {
    const taskStoredOrUndefined = this.tasksDescriptions.get(
      id,
    ) as AsyncTaskDescriptionWithId<unknown, ID>
    return taskStoredOrUndefined ?? null
  }
  public removeTaskById(id: AsyncTaskId): void {
    this.tasksDescriptions.delete(id)
  }
  public logStateInConsole(groupTitle: string): void {
    function addTaskToLog(
      queueTableToLog: any[],
      taskDescription: AsyncTaskDescriptionWithId<any>,
    ) {
      const { name, timeoutMs, timestampMs } = taskDescription

      queueTableToLog.push({
        name,
        timeoutMs,
        timestampMs,
      })
    }
    try {
      const queue = Array.from(this.tasksDescriptions.values())
      const queueTableLog: any[] = []

      queue.reverse().forEach((taskDescription) => {
        if (taskDescription) {
          addTaskToLog(queueTableLog, taskDescription)
        }
      })
      /* eslint-disable no-console */
      console.group(groupTitle)
      console.table(queueTableLog)
      console.log(queueTableLog)
      console.groupEnd()
      /* eslint-enable no-console */
    } catch (err) {
      console.error('Failed to log the queue')
    }
  }
}
