import { Publication } from '@flowpub/webpub-model'

import { IContentViewFactory } from './views/content-view/content-view-factory'
import { LayoutView } from './views/layout-view'
import {
  ISettingEntry,
  SettingName,
  ZoomOptions,
  ReadingMode,
  SpreadMode,
} from './views/types'
import { ViewSettings } from './views/view-settings'
import { Viewport } from './views/viewport'

export interface PageLayoutSettings {
  spreadMode: SpreadMode
  pageWidth?: number
  pageHeight?: number
}

export class Rendition {
  public viewport: Viewport
  public viewportRoot: HTMLElement
  public get bookLayoutView(): LayoutView {
    return this.bookView
  }

  private bookView: LayoutView

  private pub: Publication
  private pageWidth: number
  private pageHeight: number
  private spreadMode: SpreadMode = SpreadMode.FitViewportAuto
  private numOfPagesPerSpread = 0

  private contentViewFactory: IContentViewFactory

  private viewAsVertical = false

  private vs: ViewSettings = new ViewSettings()

  private repaginationHandler?: () => void

  constructor(
    pub: Publication,
    viewport: HTMLElement,
    cvFactory: IContentViewFactory,
  ) {
    this.pub = pub
    this.viewport = new Viewport(viewport)
    this.contentViewFactory = cvFactory
    this.initDefaultViewSettings()
  }

  public reset(): void {
    if (this.bookView) {
      this.bookView.reset()
    }
    this.viewport.reset()
  }

  public setPageLayout(layoutSetting: PageLayoutSettings): void {
    let spreadMode = layoutSetting.spreadMode
    if (
      this.pub.metadata.presentation &&
      this.pub.metadata.presentation.spread === 'none'
    ) {
      spreadMode = SpreadMode.FitViewportSingleSpread
    }
    const viewportSize = this.viewport.getViewportSize()
    let pageWidth = this.viewAsVertical
      ? this.viewport.getViewportSize2nd()
      : viewportSize
    let pageHeight = this.viewAsVertical
      ? viewportSize
      : this.viewport.getViewportSize2nd()
    const maxColWidth = this.vs.getSettingWithDefaultValue<number>(
      SettingName.MaxColumnWidth,
      700,
    )
    const minColWidth = this.vs.getSettingWithDefaultValue<number>(
      SettingName.MinColumnWidth,
      400,
    )
    const colGap = this.vs.getSettingWithDefaultValue<number>(
      SettingName.ColumnGap,
      0,
    )

    const minPageWidth = minColWidth + colGap

    let maxPageWidth
    if (
      this.pub.metadata.presentation &&
      this.pub.metadata.presentation.layout === 'fixed'
    ) {
      maxPageWidth = Number.MAX_SAFE_INTEGER
    } else {
      maxPageWidth = maxColWidth + colGap
    }

    let numOfPagesPerSpread = 1
    if (spreadMode === SpreadMode.Freeform) {
      numOfPagesPerSpread = 0
      if (layoutSetting.pageWidth && layoutSetting.pageHeight) {
        pageWidth = layoutSetting.pageWidth
        pageHeight = layoutSetting.pageHeight
      } else {
        console.warn('Missing page width or height for freeform layout')
      }
    } else if (spreadMode === SpreadMode.FitViewportAuto) {
      if (this.isFixedLayout()) {
        numOfPagesPerSpread = -1
        pageWidth = viewportSize
      } else {
        if (viewportSize > minPageWidth * 2) {
          if (this.viewAsVertical) {
            pageHeight = viewportSize / 2
          } else {
            pageWidth = Math.min(viewportSize / 2, maxPageWidth)
          }
          numOfPagesPerSpread = 2
        } else {
          pageWidth = Math.min(pageWidth, maxPageWidth)
        }
      }
    } else if (spreadMode === SpreadMode.FitViewportDoubleSpread) {
      if (this.viewAsVertical) {
        pageHeight = viewportSize / 2
      } else {
        pageWidth = Math.min(viewportSize / 2, maxPageWidth)
      }
      numOfPagesPerSpread = 2
    } else if (spreadMode === SpreadMode.FitViewportSingleSpread) {
      pageWidth = Math.min(viewportSize, maxPageWidth)
    }

    this.spreadMode = spreadMode
    this.numOfPagesPerSpread = numOfPagesPerSpread

    if (this.bookView) {
      this.bookView.setNumberOfPagesPerSpread(numOfPagesPerSpread)
      this.bookView.arrangeSpreads(
        viewportSize,
        this.viewport.getViewportSize2nd(),
      )
    }

    this.setPageSize(pageWidth, pageHeight)
    this.viewport.onPageSizeChanged(pageWidth, numOfPagesPerSpread, colGap)
  }

  public refreshPageLayout(): void {
    if (this.spreadMode === SpreadMode.Freeform) {
      return
    }

    this.setPageLayout({ spreadMode: this.spreadMode })
  }

  public updateViewSettings(settings: ISettingEntry[]): void {
    this.vs.updateSetting(settings)

    let spreadMode: SpreadMode | null = null
    for (const s of settings) {
      if (s.name === SettingName.SpreadMode) {
        spreadMode = this.stringToSpreadMode(s.value)
        if (!spreadMode && spreadMode === this.spreadMode) {
          spreadMode = null
        }
      }
    }

    this.setBackground()

    if (this.bookView) {
      this.bookView.beginViewUpdate()
    }

    if (spreadMode !== null) {
      this.setPageLayout({ spreadMode })
    }

    if (this.bookView) {
      this.bookView.updateViewSettings()
      this.bookView.endViewUpdate()
    }
  }

  public viewSettings(): ViewSettings {
    return this.vs
  }

  public isVerticalLayout(): boolean {
    return this.bookView.isVerticalLayout()
  }

  public isFixedLayout(): boolean {
    return this.pub?.metadata?.presentation?.layout === 'fixed'
  }

  public setZoom(option: ZoomOptions, scale: number): void {
    if (this.viewport && this.bookView) {
      this.viewport.setZoomScale(scale)
      this.bookView.setZoom(option, 1)
    }
  }

  public getZoomScale(): number {
    if (this.viewport) {
      return this.viewport.getZoomScale()
    }

    return 1
  }

  public getZoomOption(): ZoomOptions {
    if (this.bookView) {
      return this.bookView.getZoomOption()
    }

    return ZoomOptions.FitByPage
  }

  public setViewAsVertical(v: boolean): void {
    this.viewAsVertical = v
    if (this.bookView) {
      this.bookView.setVerticalLayout(v)
    }
  }

  public getPageWidth(): number {
    return this.pageWidth
  }

  public getPublication(): Publication {
    return this.pub
  }

  public getCfiFromAnchor(href: string, elementId: string): string | undefined {
    if (!this.bookView) {
      return undefined
    }

    return this.bookView.getCfiFromAnchor(href, elementId)
  }

  public getNumOfPagesPerSpread(): number {
    return this.numOfPagesPerSpread
  }

  public getReadingMode(): ReadingMode {
    return this.vs.getSettingWithDefaultValue<ReadingMode>(
      SettingName.ReadingMode,
      'day',
    )
  }

  // // tslint:disable-next-line:no-any
  // public getReadiumPackageDocument(): any {
  //   return this.bookView.getRsjPackageDocument();
  // }

  // // tslint:disable-next-line:no-any
  // public getReadiumPackage(): any {
  //   return this.bookView.getRsjPackage();
  // }

  public render(): Promise<void> {
    this.bookView = new LayoutView(this.pub, this.vs, this.contentViewFactory)
    this.bookView.setVerticalLayout(this.viewAsVertical)
    this.bookView.setPageSize(this.pageWidth, this.pageHeight)
    this.bookView.setNumberOfPagesPerSpread(this.numOfPagesPerSpread)
    this.bookView.arrangeSpreads(
      this.viewport.getViewportSize(),
      this.viewport.getViewportSize2nd(),
    )

    this.bookView.onRepagination(this.repaginationInternal.bind(this))

    this.viewport.setView(this.bookView)

    return Promise.resolve()
  }

  public onRepagination(handler: () => void): void {
    this.repaginationHandler = handler
  }

  public setAndApplyAnimationProperties(
    animationProperties: Partial<CSSStyleDeclaration>,
  ): void {
    this.viewport.setAndApplyAnimationProperties(animationProperties)
  }

  private repaginationInternal(): void {
    this.repaginationHandler && this.repaginationHandler()
  }

  private initDefaultViewSettings(): void {
    const settings = []

    const columnGapSetting = { name: SettingName.ColumnGap, value: 20 }
    settings.push(columnGapSetting)

    let spreadValue = 'auto'
    if (
      this.pub.metadata.presentation &&
      this.pub.metadata.presentation.spread === 'none'
    ) {
      spreadValue = 'single'
    }

    const spreadSetting = {
      name: SettingName.SpreadMode,
      value: spreadValue,
    }
    settings.push(spreadSetting)

    const fontSizeSetting = { name: SettingName.FontSize, value: 100 }
    settings.push(fontSizeSetting)

    const readingModeSetting = {
      name: SettingName.ReadingMode,
      value: 'readium-default-on',
    }
    settings.push(readingModeSetting)

    const maxColWidthSetting = { name: SettingName.MaxColumnWidth, value: 700 }
    settings.push(maxColWidthSetting)

    const minColWidthSetting = { name: SettingName.MinColumnWidth, value: 400 }
    settings.push(minColWidthSetting)

    const fontOverrideSetting = {
      name: SettingName.FontOverride,
      value: 'readium-font-on',
    }
    settings.push(fontOverrideSetting)

    this.vs.updateSetting(settings)
  }

  private setPageSize(pageWidth: number, pageHeight: number): void {
    this.pageWidth = pageWidth
    this.pageHeight = pageHeight

    if (this.bookView) {
      this.bookView.setPageSize(this.pageWidth, this.pageHeight)
    }
  }

  public stringToSpreadMode(val: string): SpreadMode | null {
    let mode: SpreadMode | null = null
    if (val === 'auto') {
      mode = SpreadMode.FitViewportAuto
    } else if (val === 'single') {
      mode = SpreadMode.FitViewportSingleSpread
    } else if (val === 'double') {
      mode = SpreadMode.FitViewportDoubleSpread
    }

    return mode
  }

  /**
   * Gets the background color for a given reading mode (theme).
   *
   * @param {ReadingMode} mode The reading mode to get the background color for.
   * @returns {string} color value in rgb() format(e.g., rgb(255, 255, 255)) or empty string
   */
  public getBackgroundColor(mode: ReadingMode): string {
    let bgColor = ''
    switch (mode) {
      case 'night':
        bgColor = 'rgb(0, 0, 0)'
        break
      case 'sepia':
        bgColor = 'rgb(250, 244, 232)'
        break
      case 'day':
      default:
        break
    }

    return bgColor
  }

  /**
   * Gets the current actual background color of the viewport.
   *
   * @returns {string} color value in a valid color format(e.g., color word, rgb(), rgba()) or empty string
   */
  public getCurrentBackgroundColor(): string {
    return window.getComputedStyle(this.viewportRoot).backgroundColor
  }

  private setBackground(): void {
    const mode = this.getReadingMode()
    this.viewportRoot.style.backgroundColor = this.getBackgroundColor(mode)
  }
}
