import { NavigatorErrorType } from '../const'
import {
  AsyncTaskRejectionByQueueHandlerError,
  AsyncTaskRejectionErrorFabric,
  AsyncTaskStore,
  AsyncTaskStoreEventEmitterReadOnly,
  AsyncTaskStoreEventName,
  AsyncTaskStoreEventsList,
} from '../utils/async-tasks-storing-and-handling'
import { AsyncTaskDescriptionStrict, AsyncTaskId } from '../utils/types'

import {
  QueueEventHandler,
  NavigatorQueueEventHandlerFabricParameters,
} from './types'

export abstract class QueueEventsHandlerAbstract implements QueueEventHandler {
  protected abstract readonly supportedTaskNames: string[]
  protected readonly asyncTaskStoreEventEmitter: AsyncTaskStoreEventEmitterReadOnly
  private readonly asyncTaskRejectionErrorFabric: AsyncTaskRejectionErrorFabric<
    NavigatorErrorType.RejectedByQueueHandler
  >
  constructor(parameters: NavigatorQueueEventHandlerFabricParameters) {
    const {
      asyncTaskStoreEventEmitter,
      asyncTaskRejectionErrorFabric,
    } = parameters

    this.asyncTaskStoreEventEmitter = asyncTaskStoreEventEmitter
    this.asyncTaskRejectionErrorFabric = asyncTaskRejectionErrorFabric
  }

  public close(): void {
    this.unsetEventsListeners()
  }

  protected abstract setOrUnsetEventsListeners(
    method: 'addListener' | 'removeListener',
  ): void

  protected setEventsListeners(): void {
    this.setOrUnsetEventsListeners('addListener')
  }

  protected unsetEventsListeners(): void {
    this.setOrUnsetEventsListeners('removeListener')
  }

  protected isTaskNameSupported(taskName: string): boolean {
    return this.supportedTaskNames.includes(taskName)
  }

  protected isEventSupported(
    event: AsyncTaskStoreEventsList[AsyncTaskStoreEventName],
  ): boolean {
    const { taskDescriptionWithId } = event
    const { name } = taskDescriptionWithId

    return this.supportedTaskNames.includes(name)
  }

  protected filterSupportedTaskDescriptions<
    T extends AsyncTaskDescriptionStrict<unknown>
  >(taskDescriptions: T[]): T[] {
    return taskDescriptions.filter((taskDescription) =>
      this.isTaskNameSupported(taskDescription.name),
    )
  }

  protected filterTaskDescriptionsFromNulls<
    T extends AsyncTaskDescriptionStrict<unknown>
  >(taskDescriptionsOrNulls: Array<null | T>): T[] {
    return taskDescriptionsOrNulls.filter(this.isNotNull)
  }

  protected filterSupportedTaskDescriptionsExcludingNull<
    T extends AsyncTaskDescriptionStrict<unknown>
  >(taskDescriptionsOrNulls: Array<T | null>): T[] {
    const taskDescriptions: T[] = this.filterTaskDescriptionsFromNulls(
      taskDescriptionsOrNulls,
    )
    return this.filterSupportedTaskDescriptions(taskDescriptions)
  }

  protected createAsyncTaskRejectionErrorByErrorMessage(
    errorMessage: string,
  ): AsyncTaskRejectionByQueueHandlerError {
    return this.asyncTaskRejectionErrorFabric(
      errorMessage,
      NavigatorErrorType.RejectedByQueueHandler,
    )
  }

  protected rejectTaskById(
    taskId: AsyncTaskId,
    asyncTaskStore: AsyncTaskStore,
    errorMessage: string,
  ): void {
    const rejectionError: AsyncTaskRejectionByQueueHandlerError = this.createAsyncTaskRejectionErrorByErrorMessage(
      errorMessage,
    )
    asyncTaskStore.rejectAndRemoveTaskById(taskId, rejectionError)
  }

  private isNotNull = <V>(v: V): v is Exclude<V, null> => {
    return v !== null
  }
}
